prompt --application/shared_components/logic/application_processes/get_aceess_token
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(15438247154906910)
,p_process_sequence=>1
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'get aceess token'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_clob 	        CLOB;',
'    l_resp          apex_json.t_values;',
'    lv_token        VARCHAR2(4000);',
'    j               apex_json.t_values; ',
'    l_service_url   VARCHAR2(4000);',
'BEGIN',
'   ',
'    BEGIN',
'        SELECT param_value',
'        INTO   l_service_url',
'        FROM   kbot_md_sys_conf',
'        WHERE  param_type = 1',
'        and    app_id = :APP_ID',
'        AND    status = 1',
'        and    rownum = 1;',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            l_service_url := NULL;',
'    END;',
'    APEX_DEBUG.WARN(''execute'');',
'    IF l_service_url IS NOT NULL AND :APP_ACCESS_TOKEN IS NULL THEN',
'        -- Get token',
'        apex_web_service.g_request_headers.delete();',
'        apex_web_service.g_request_headers(1).name  := ''accept'';',
'        apex_web_service.g_request_headers(1).value := ''application/json''; ',
'        apex_web_service.g_request_headers(2).name  := ''Content-Type'';',
'        apex_web_service.g_request_headers(2).value := ''application/x-www-form-urlencoded''; ',
'        l_clob := apex_web_service.make_rest_request(',
'                p_url => l_service_url||''/api/security/get_token'',',
'                p_http_method => ''POST'',',
'                p_body => ''username=Kbot_UI&password=kbot_ui''',
'        );',
'        ',
'        apex_json.parse(',
'            p_values => l_resp,',
'            p_source => l_clob);',
'',
'        lv_token := apex_json.get_varchar2(',
'            p_path => ''access_token'',',
'            p_values => l_resp);',
'',
'        :APP_ACCESS_TOKEN := lv_token;',
'    END IF;',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        :APP_ACCESS_TOKEN := null;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_version_scn=>12205112537552
);
end;
/
prompt --application/shared_components/logic/application_processes/get_sys_conf_val
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(8501428905200732)
,p_process_sequence=>1
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_SYS_CONF_VAL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    lv_val   VARCHAR2(4000);  ',
'BEGIN',
'   SELECT PARAM_VALUE INTO lv_val FROM KBOT_MD_SYS_CONF WHERE APP_ID = V(''APP_ID'') AND PARAM_TYPE = apex_application.g_x01 AND STATUS = 1 AND ROWNUM = 1;',
'   IF lv_val IS NOT NULL AND apex_application.g_x01 = 2 THEN',
'        lv_val :=  REPLACE(lv_val, CHR(35) || ''APP_FILES'' || CHR(35), :APP_FILES);',
'   END IF;',
'   HTP.P(lv_val);',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        HTP.P('''');',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
,p_version_scn=>12205093745103
);
end;
/
prompt --application/shared_components/logic/application_processes/get_rag_url
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(149558261424688993)
,p_process_sequence=>1
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_RAG_URL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_url       varchar2(2000);   ',
'    v_result    varchar2(4000);',
'    ln_page_num number;',
'begin',
'    select PAGE_ID INTO ln_page_num from KMCHAT_RAG_LIST_CONTROL where APP_ID = V(''APP_ID'') and RAG_NAME = apex_application.g_x02;',
'    v_result := APEX_PAGE.GET_URL (',
'            p_page   => ln_page_num,',
'            p_items  => ''P''||ln_page_num||''_KNOWLEDGE_BASE_NAME'',',
'            p_values =>  apex_application.g_x01,',
'            p_request => ''init''',
'            );',
'    htp.prn(v_result);',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_version_scn=>12205042386845
);
end;
/
prompt --application/shared_components/logic/application_processes/add_admin_auth
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(97605809929467816)
,p_process_sequence=>1
,p_process_point=>'ON_NEW_INSTANCE'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'add admin auth'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    ln_cnt      NUMBER;',
'    ln_data_cnt NUMBER;',
'BEGIN',
'',
'    SELECT COUNT(1)',
'    INTO   ln_cnt ',
'    FROM   kbot_ui_user',
'    WHERE  auth_role = ''ADMIN''',
'    AND    app_id = V(''APP_ID'');',
'--',
'    IF ln_cnt = 0 THEN ',
'        INSERT INTO kbot_ui_user(user_name, user_pwd, auth_role, created_by, updated_by, app_id)',
'        VALUES(''admin'',kbot_ui_utl.encode(''12345678''),''ADMIN'',''SYS'',''SYS'',V(''APP_ID''));',
'    END IF;',
'EXCEPTION',
'    WHEN OTHERS THEN',
'     apex_debug.warn(''ln_cnt:''||sqlerrm);',
'        NULL;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_when_type=>'NEVER'
,p_version_scn=>12204996403446
);
end;
/
