unistr('-- \7B2C\4E00\7EA7\FF1A\4E1A\52A1\57DF'),
'SELECT ',
'    ''DOMAIN_'' || DOMAIN_ID AS ID,',
'    NULL AS PARENT_ID,',
'    NAME,',
'    ''fa fa-globe'' AS ICON,',
'    ''domain'' AS TYPE,',
'    1 AS TREE_LEVEL,',
'    DOMAIN_ID AS ORIGINAL_ID',
'FROM ',
'    KBOT_MD_DOMAIN',
'WHERE ',
'    APP_ID = :APP_ID',
'    AND STATUS = 1',
'',
'UNION ALL',
'',
unistr('-- \7B2C\4E8C\7EA7\FF1A\77E5\8BC6\5E93'),
'SELECT ',
'    ''KB_''||k.KB_ID AS ID,',
'    ''DOMAIN_'' || k.DOMAIN_ID AS PARENT_ID,',
'    k.KB_NAME AS NAME,',
'    ''fa fa-television'' AS ICON,',
'    ''kb'' AS TYPE,',
'    2 AS TREE_LEVEL,',
'    k.KB_ID AS ORIGINAL_ID',
'FROM ',
