'from   tb1,tb2,tb3',
'where tb1.KB_ID = tb2.KB_ID(+)',
'and   tb1.KB_ID = tb3.KB_ID(+)',
'and   tb1.BATCH_NAME = tb2.BATCH_NAME(+)',
