'      ,KBOT_MD_MODELS kmm1',
'      ,kbot_md_domain kmd',
'where  kma.app_id = :app_id',
'and    kmm.model_id(+) = kma.LLM_ID',
'and    kmm.CATEGORY = 1',
'and    kma.RERANKER_MODEL_ID = kmm1.MODEL_ID(+) ',
'and    kmm1.CATEGORY = 4',
'and    kma.domain_id = kmd.domain_id'))
);
