'BEGIN',
'    lv_order_by := '' order by created_time desc'';',
'    lv_sql := ''select "ID",',
'                    null LINK_CLASS,',
'                    apex_page.get_url(p_items => ''''P24_ID'''', p_values => "ID") LINK,',
'                    null ICON_CLASS,',
'                    null LINK_ATTR,',
'                    null ICON_COLOR_CLASS,',
