'                    null LIST_BADGE',
'                from "KBOT_UI_KB_SYNONYM_CONF" x',
'                where app_Id = V(''''APP_ID'''') AND',
'                     (:P24_SEARCH is null',
'                        or upper(x."KB_NAME") like ''''%''''||upper(:P24_SEARCH)||''''%''''',
'                        or upper(x."SYNONYM_NAME") like ''''%''''||upper(:P24_SEARCH)||''''%''''',
'                      )'';',
'    RETURN lv_sql||lv_order_by;',
'END;',
''))
