'    AND   app_Id =  :APP_ID),',
'tb2 as (SELECT MASTER_ID, COUNT(IS_EMBEDDING) as cnt FROM KBOT_UI_KB_SYNONYM_DETAIL WHERE app_id = :APP_ID  group by MASTER_ID),',
'tb3 as (SELECT MASTER_ID, COUNT(IS_EMBEDDING) as cnt FROM KBOT_UI_KB_SYNONYM_DETAIL where app_id = :APP_ID and IS_EMBEDDING = ''Y'' group by MASTER_ID)',
'select tb1.ID, ',
'       tb1.CONF_ID, ',
'       tb1.link,',
'       tb1.STANDARD_QUESTION,',
'       tb1.CREATED_BY,',
'       tb1.CREATE_DATE,',
'       nvl(tb2.cnt,0) total_count,',
'       nvl(tb3.cnt,0) embedding_count,',
'       nvl(tb2.cnt,0)-nvl(tb3.cnt,0) unembedding_count',
'from   tb1,tb2,tb3',
'where  tb1.id = tb2.MASTER_ID(+)',
'and    tb1.id = tb3.MASTER_ID(+);'))
);
