wwv_flow_imp_shared.create_translation(
 p_id=>wwv_flow_imp.id(96915698045204822)
,p_page_id=>10000
,p_translated_flow_id=>117
,p_translate_to_id=>wwv_flow_imp.id(96506920311545104.117)
,p_translate_from_id=>wwv_flow_imp.id(96506920311545104)
,p_translate_column_id=>21
,p_translate_to_lang_code=>'zh-cn'
,p_translation_specific_to_item=>'NO'
,p_template_translatable=>'N'
,p_translate_to_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH all_roles AS (',
'  SELECT INITCAP(''ADMIN'') AS auth_role UNION ALL',
'  SELECT INITCAP(''DOMAIN ADMIN'') UNION ALL',
'  SELECT INITCAP(''TIER OPERATOR'')',
'),',
'user_counts AS (',
'  SELECT auth_role, COUNT(1) AS user_count',
'  FROM kbot_ui_user',
'  WHERE app_id = :app_id',
'  GROUP BY auth_role',
')',
'SELECT ',
'  ar.auth_role, ',
'  COALESCE(uc.user_count, 0) AS user_count',
'FROM all_roles ar',
'LEFT JOIN user_counts uc ON upper(ar.auth_role) = uc.auth_role'))
,p_translate_from_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH all_roles AS (',
'  SELECT INITCAP(''ADMIN'') AS auth_role UNION ALL',
'  SELECT INITCAP(''DOMAIN ADMIN'') UNION ALL',
'  SELECT INITCAP(''TIER OPERATOR'')',
'),',
'user_counts AS (',
'  SELECT auth_role, COUNT(1) AS user_count',
'  FROM kbot_ui_user',
'  WHERE app_id = :app_id',
'  GROUP BY auth_role',
')',
'SELECT ',
'  ar.auth_role, ',
'  COALESCE(uc.user_count, 0) AS user_count',
'FROM all_roles ar',
'LEFT JOIN user_counts uc ON upper(ar.auth_role) = uc.auth_role'))
);
