'DECLARE',
'    lv_sql VARCHAR2(32766);',
'    lv_available_view_prompt VARCHAR2(4000);',
'BEGIN',
'    lv_sql := ''SELECT ID,',
'           PROFILE_NAME,',
'           PROFILE_DESC,',
'           APP_USER,',
'           CREATE_DATE,',
'           APP_ID,',
'           LLM_MODEL,',
'           CHAT_CATAGORY,',
'           PROMPT_NAME,',
'           QUERY_SIMILARITY_FLAG,',
'           SEARCH_TYPE,',
'           SUMMARY,',
'           VECTOR_TOPK,',
'           RERANKER_MODEL,',
'           RERANKER_TOPK,',
'           SCORE_THRESHOLD,',
'           HISTORY_K,',
'           USER_DEFAULT_PROFILE',
'      from KMCHAT_CHAT_USER_PROFILE',
'      WHERE  APP_ID = :P20_APP_ID',
'      '';',
'    IF :P20_IS_ADMIN = ''YES'' OR apex_app_setting.get_value(p_name => ''ACCESS_CONTROL_SCOPE'') = ''ALL_USERS'' THEN',
'        RETURN lv_sql ||'' AND ( UPPER(APP_USER) = UPPER(:P20_USER_NAME_PROFILE) OR PROFILE_NAME = ''''Sys_Default'''')'';',
'    ELSE',
'        RETURN lv_sql ||'' AND UPPER(APP_USER) = UPPER(:P20_USER_NAME_PROFILE)''; ',
'    END IF;',
'END;',
''))
,p_translate_from_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
