'  l_result.attribute_08        := l_show_duration;',
'  l_result.attribute_09        := l_hide_duration;',
'  l_result.attribute_10        := l_timeout;',
'  l_result.attribute_11        := l_extended_timeout;',
'  --',
'  RETURN l_result;',
'  --',
'END render_toastr;'))
