,p_attribute_02=>'notification-menu'
,p_attribute_04=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    ''fa-info-circle-o'' AS NOTE_ICON, ',
'    ''u-color-14-border'' AS NOTE_ICON_COLOR, ',
'     RELEASE_TITLE AS NOTE_HEADER,',
'     RELEASE_CONTENT||''<br/>''||''<span style="color:#508223;font-size:13px;" ><span aria-hidden="true" class="fa fa-hand-o-right fa-anim-flash" style="padding-top:2px"></span>&nbsp Release Notes... </span>'' AS NOTE_TEXT, ',
'    APEX_PAGE.GET_URL (p_page   => 17) AS NOTE_LINK,',
'    ''#497620'' AS NOTE_COLOR,',
'    NULL AS NOTE_ACCEPT,',
'    NULL AS NOTE_DECLINE,',
'    0 AS NO_BROWSER_NOTIFICATION',
'FROM  KBOT_MD_RELEASE_NOTE',
'WHERE app_id = V(''APP_ID'')',
