'function addParticleEffect() {',
'    $(''.t-Body-main'').on(''click'', function(e) {',
'        // if ($(e.target).is(''input, select, textarea, button, a, .no-effect'')) return;',
'        ',
'        var colors = [''#FBCA54'',''#772829'',''#AB99B2'',''#FBCA54'',''#98C7AD'',''#23595C'',''#D3C388''];',
'        var particleCount = 8;',
'        ',
'        for (var i = 0; i < particleCount; i++) {',
'            var particle = $(''<div class="particle"></div>'').css({',
'                ''position'': ''absolute'',',
'                ''width'': ''8px'',',
'                ''height'': ''8px'',',
'                ''background'': colors[Math.floor(Math.random() * colors.length)],',
'                ''border-radius'': ''50%'',',
'                ''pointer-events'': ''none'',',
'                ''z-index'': ''9999'',',
'                ''left'': e.pageX + ''px'',',
'                ''top'': e.pageY + ''px''',
'            });',
'            ',
'            $(''body'').append(particle);',
'            ',
'            var angle = Math.random() * Math.PI * 2;',
'            var distance = 50 + Math.random() * 50;',
'            ',
'            particle.animate({',
'                ''left'': e.pageX + Math.cos(angle) * distance + ''px'',',
'                ''top'': e.pageY + Math.sin(angle) * distance + ''px'',',
'                ''opacity'': ''0''',
'            }, 600, function() {',
'                $(this).remove();',
'            });',
'        }',
'    });',
'}'))
