'select kma.AGENT_ID,',
'       kmd.NAME AS DOMAIN_NAME,',
'       kma.AGENT_NAME,',
'       kmm.DISPLAY_NAME as llm_name,',
'       kmm1.DISPLAY_NAME as RERANKER_MODEL,',
'       kbot_md_ui_utl.get_dic_dname(''AGENT_STATUS'',kma.AGENT_STATUS) as Badge_Column,',
'       kma.AGENT_STATUS AS AGENT_STATUS_R,',
'       INITCAP(kma.UPDATED_BY) UPDATED_BY,',
'       TO_CHAR(kma.UPDATED_TIME,''DD-MON-YYYY'') AS UPDATED_TIME,',
'       ''u-color-17'' CARD_COLOR',
'  from KBOT_MD_AGENT kma',
'      ,KBOT_MD_MODELS kmm',
'      ,KBOT_MD_MODELS kmm1',
'      ,kbot_md_domain kmd',
'where  kma.app_id = :app_id',
'and    kmm.model_id(+) = kma.LLM_ID',
'and    kmm.CATEGORY = 1',
'and    kma.RERANKER_MODEL_ID = kmm1.MODEL_ID(+) ',
'and    kmm1.CATEGORY = 4',
'and    kma.domain_id = kmd.domain_id'))
