,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    LV_LLM_MODEL       VARCHAR2(400);',
'    LV_CHAT_CATAGORY   VARCHAR2(400);',
'    LV_PROMPT_NAME     VARCHAR2(400);',
'    LV_QUERY_SIMILARITY_FLAG VARCHAR2(400);',
'    LV_SEARCH_TYPE     VARCHAR2(400);',
'    LN_VECTOR_TOPK     NUMBER;',
'    LV_RERANKER_MODEL  VARCHAR2(400);',
'    LN_RERANKER_TOPK   NUMBER;',
'    LN_SCORE_THRESHOLD NUMBER;',
'    LN_HISTORY_K       NUMBER;',
'    lv_url             VARCHAR2(4000);',
'BEGIN',
'    SELECT  LLM_MODEL,',
'            CHAT_CATAGORY,',
'            PROMPT_NAME,',
'            QUERY_SIMILARITY_FLAG,',
'            SEARCH_TYPE,',
'            VECTOR_TOPK,',
'            RERANKER_MODEL,',
'            RERANKER_TOPK,',
'            SCORE_THRESHOLD,',
'            HISTORY_K',
'    INTO    LV_LLM_MODEL,',
'            LV_CHAT_CATAGORY,',
'            LV_PROMPT_NAME,',
'            LV_QUERY_SIMILARITY_FLAG,',
'            LV_SEARCH_TYPE,',
'            LN_VECTOR_TOPK,',
'            LV_RERANKER_MODEL,',
'            LN_RERANKER_TOPK,',
'            LN_SCORE_THRESHOLD,',
'            LN_HISTORY_K',
'    FROM    KMCHAT_CHAT_USER_PROFILE',
'    WHERE (UPPER(APP_USER) = UPPER(V(''APP_USER'')) OR PROFILE_NAME = ''Sys_Default'')',
'    AND   APP_ID   = V(''APP_ID'')',
'    AND   ID = TO_NUMBER(:P1_PROFILE);',
'    ',
'    lv_url := APEX_PAGE.GET_URL (',
'        p_page   => 1,',
'        p_items  => ''P1_MODEL,P1_CHAT_CATAGORY,P1_PROMPT_NAME,P1_QUERYSIMILARITY_FLAG,P1_SEARCH_TYPE,P1_VECTOR_STORE_LIMIT,P1_RERANKER_MODEL,P1_RERANKER_TOPK,P1_SCORE_THRESHOLD,P1_HISTORY_K'',',
'        p_values =>  ''''||LV_LLM_MODEL||'',''||LV_CHAT_CATAGORY||'',''||LV_PROMPT_NAME||'',''||',
'            LV_QUERY_SIMILARITY_FLAG||'',''||LV_SEARCH_TYPE||'',''||LN_VECTOR_TOPK||'',''||',
'            LV_RERANKER_MODEL||'',''||LN_RERANKER_TOPK||'',''||LN_SCORE_THRESHOLD||'',''||LN_HISTORY_K||'''');',
'    -- APEX_DEBUG.WARN(''lv_url:''||lv_url);',
'    apex_util.redirect_url(lv_url);',
'    -- SELECT  LLM_MODEL,',
'    --         CHAT_CATAGORY,',
'    --         PROMPT_NAME,',
'    --         QUERY_SIMILARITY_FLAG,',
'    --         SEARCH_TYPE,',
'    --         VECTOR_TOPK,',
'    --         RERANKER_MODEL,',
'    --         RERANKER_TOPK,',
'    --         SCORE_THRESHOLD,',
'    --         HISTORY_K',
'    -- INTO    :P1_MODEL,',
'    --         :P1_CHAT_CATAGORY,',
'    --         :P1_PROMPT_NAME,',
'    --         :P1_QUERYSIMILARITY_FLAG,',
'    --         :P1_SEARCH_TYPE,',
'    --         :P1_VECTOR_STORE_LIMIT,',
'    --         :P1_RERANKER_MODEL,',
'    --         :P1_RERANKER_TOPK,',
'    --         :P1_SCORE_THRESHOLD,',
'    --         :P1_HISTORY_K',
'    -- FROM    KMCHAT_CHAT_USER_PROFILE',
'    -- WHERE (UPPER(APP_USER) = UPPER(V(''APP_USER'')) OR PROFILE_NAME = ''Sys_Default'')',
'    -- AND   APP_ID   = V(''APP_ID'')',
'    -- AND   ID = TO_NUMBER(:P1_PROFILE);',
'END;'))
,p_attribute_02=>'P1_PROFILE'
,p_attribute_03=>'P1_MODEL,P1_CHAT_CATAGORY,P1_PROMPT_NAME,P1_QUERYSIMILARITY_FLAG,P1_SEARCH_TYPE,P1_VECTOR_STORE_LIMIT,P1_RERANKER_MODEL,P1_RERANKER_TOPK,P1_SCORE_THRESHOLD,P1_HISTORY_K'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
,p_server_condition_type=>'NEVER'
);
