'BEGIN',
'    -- ServiceURL 1',
'    INSERT INTO kbot_md_sys_conf(param_type, param_name, param_value, status, created_by, updated_by, app_id)',
'    VALUES (1, ''Service'', ''http:127.0.0.1:8090'', ''Y'', V(''APP_USER''), V(''APP_USER''), V(''APP_ID''));',
'',
'    -- Search 3',
'    INSERT INTO kbot_md_sys_conf(param_type, param_name, param_value, status, created_by, updated_by, app_id)',
'    VALUES (3,''VectorTopk'', ''10'', ''Y'', V(''APP_USER''), V(''APP_USER''), V(''APP_ID''));',
'    INSERT INTO kbot_md_sys_conf(param_type, param_name, param_value, status, created_by, updated_by, app_id)',
'    VALUES (3,''RerankerModel'', ''bgeReranker'', ''Y'', V(''APP_USER''), V(''APP_USER''), V(''APP_ID''));',
'    INSERT INTO kbot_md_sys_conf(param_type, param_name, param_value, status, created_by, updated_by, app_id)',
'    VALUES (3,''RerankerModel'', ''cohereReranker'', ''Y'', V(''APP_USER''), V(''APP_USER''), V(''APP_ID''));',
'    INSERT INTO kbot_md_sys_conf(param_type, param_name, param_value, status, created_by, updated_by, app_id)',
'    VALUES (3,''RerankerModel'', ''disableReranker'', ''Y'', V(''APP_USER''), V(''APP_USER''), V(''APP_ID''));',
'    INSERT INTO kbot_md_sys_conf(param_type, param_name, param_value, status, created_by, updated_by, app_id)',
'    VALUES (3,''RerankerTopk'', ''2'', ''Y'', V(''APP_USER''), V(''APP_USER''), V(''APP_ID''));',
'    INSERT INTO kbot_md_sys_conf(param_type, param_name, param_value, status, created_by, updated_by, app_id)',
'    VALUES (3,''RerankerScoreThreshold'', ''0.3'', ''Y'', V(''APP_USER''), V(''APP_USER''), V(''APP_ID''));',
'',
'',
'    -- feedback 4',
'    INSERT INTO kbot_md_sys_conf(param_type, param_name, param_value, status, created_by, updated_by, app_id)',
'    VALUES (4, ''FeedbackSimilarityThreshold'', ''0.2'', ''Y'', V(''APP_USER''), V(''APP_USER''), V(''APP_ID''));',
'',
'    -- DataChunk 5',
'',
'',
'',
'    -- GRAPHGRAG 6',
'    COMMIT;  ',
'END;'))
