'    kuk.KB_NAME,',
'    kbot_md_ui_utl.get_dic_dname(''KB_CATEGORY'', kuk.KB_CATEGORY) AS KB_CATEGORY,',
'    kuk.DESCS,',
'    kuvci.DB_DISPLAY_NAME,',
'    txt_model.display_name AS TXT_EMBED_MODEL,',
'    img_model.display_name AS IMG_EMBED_MODEL,',
'    sum_model.display_name AS SUMMARY_MODEL,',
'    img2txt_model.display_name AS IMG2TXT_MODEL,',
'    kbot_md_ui_utl.get_dic_dname(''AGENT_STATUS'', kuk.kb_status) AS KB_STATUS,',
'    kuk.kb_status as hide_kb_status,',
'    kuk.CREATED_BY,',
'    kuk.CREATED_TIME,',
'    kuk.UPDATED_BY,',
'    kuk.UPDATED_TIME,',
'    ''Files'' AS view_files',
'FROM ',
'    KBOT_md_KB kuk',
'JOIN ',
'    KBOT_md_DB_CONF kuvci ON kuk.DB_CONN_ID = kuvci.db_id',
'LEFT JOIN ',
'    kbot_md_models txt_model ON kuk.TXT_EMBED_MODEL_ID = txt_model.model_id',
'LEFT JOIN ',
'    kbot_md_models img_model ON kuk.IMG_EMBED_MODEL_ID = img_model.model_id',
'LEFT JOIN ',
'    kbot_md_models sum_model ON kuk.SUMMARY_MODEL_ID = sum_model.model_id',
'LEFT JOIN ',
'    kbot_md_models img2txt_model ON kuk.IMG2TXT_MODEL_ID = img2txt_model.model_id',
'WHERE ',
'    kuk.APP_ID = :APP_ID',
'    AND kuk.domain_id = :P6_DOMAIN_ID'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P6_DOMAIN_ID,P6_SEARCH'
