 p_id=>wwv_flow_imp.id(88822331782526320)
,p_name=>'Domain'
,p_template=>wwv_flow_imp.id(106480523158103557)
,p_display_sequence=>20
,p_region_css_classes=>'search-results'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'t-MediaList--showIcons:t-MediaList--showDesc:t-MediaList--stack'
,p_display_point=>'REGION_POSITION_02'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    domain_ID,',
'    NULL link_class,',
'    apex_page.get_url(p_items => ''P6_DOMAIN_ID'', p_values => domain_id) LINK,',
'    ''fa fa-globe'' ICON_CLASS,',
'    null LINK_ATTR,',
'    ''u-color-14'' ICON_COLOR_CLASS,',
'    case when coalesce(:P6_domain_id,''0'') = domain_id',
'    then ''is-active'' ',
'    else ''''',
'    end LIST_CLASS,',
'    (substr(NAME, 1, 30)||( case when length(NAME) > 30 then ''...'' else '''' end )) LIST_TITLE,',
'    (substr(DESCS, 1, 30)||( case when length(DESCS) > 30 then ''...'' else '''' end )) LIST_TEXT,',
'    null LIST_BADGE',
'from kbot_md_domain x',
'where app_Id = V(''APP_ID'') ',
'AND   x.status = 1',
'AND',
'     (:P6_SEARCH is null ',
'     or upper(x.NAME) like ''%''||upper(:P6_SEARCH)||''%''',
'     or upper(x.DESCS) like ''%''||upper(:P6_SEARCH)|| ''%'' );'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P6_SEARCH'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(106485696477103559)
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
