wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(88691482652600022)
,p_plug_name=>'Master'
,p_region_name=>'MasterIGStatic'
,p_parent_plug_id=>wwv_flow_imp.id(88694412065600051)
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(106480523158103557)
,p_plug_display_sequence=>120
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with',
'tb1 as (',
'    SELECT batch_name,',
'           chunk_size,',
'           chunk_overlap,',
'           kb_id',
'    FROM kmchat_kb_batch WHERE app_id = :APP_ID),',
'tb2 as (SELECT kb_id,UPPER(BATCH_NAME) BATCH_NAME,COUNT(filename) as cnt FROM KMCHAT_KB_FILES WHERE app_id = :APP_ID  group by KB_ID,BATCH_NAME),',
'tb3 as (SELECT kb_id,UPPER(BATCH_NAME) BATCH_NAME,COUNT(filename) as cnt FROM KMCHAT_KB_FILES where app_id = :APP_ID and upload_status = ''yes''  group by KB_ID,BATCH_NAME)',
'select tb1.KB_ID, ',
'       tb1.BATCH_NAME, ',
'       tb1.CHUNK_SIZE,',
'       tb1.CHUNK_OVERLAP , ',
'       nvl(tb2.cnt,0) file_count,',
'       nvl(tb3.cnt,0) file_count_success,',
'       nvl(tb2.cnt,0)-nvl(tb3.cnt,0) file_count_faild',
'from   tb1,tb2,tb3',
'where tb1.KB_ID = tb2.KB_ID(+)',
'and   tb1.KB_ID = tb3.KB_ID(+)',
'and   tb1.BATCH_NAME = tb2.BATCH_NAME(+)',
'and   tb1.BATCH_NAME = tb3.BATCH_NAME(+)',
'and   tb1.KB_ID = :P7_ID;'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P7_ID'
,p_plug_display_condition_type=>'ITEM_IS_NOT_NULL'
