wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(86964451538215167)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'create kb'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    ln_kb_id     NUMBER;',
'    l_file_names apex_t_varchar2;',
'    lv_Filename  VARCHAR2(3000);',
'    lv_Mime_Type VARCHAR2(3000);',
'    lb_Blob_Content BLOB;',
'    ln_cnt      NUMBER;',
'    lv_msg      VARCHAR2(4000);',
'BEGIN',
'    -- INSERT',
'    :P7_MSG := NULL;',
'    IF :P7_ID IS NULL THEN',
'        -- instr kb',
'        KMCHAT_KB_BASE_PKG.llm_instr_kb(',
'            iv_kb_name  => TRIM(:P7_KNOWLEDGE_BASE_NAME),',
'            iv_embeeding_model  => :P7_EMBEEDING_MODEL,',
'            iv_vector_db    =>  :P7_VECTOR_DB,',
'            iv_kb_desc      =>  :P7_KB_DESC,',
'            iv_kb_status    =>  :P7_KB_PUBLISH_STATUS,',
'            ov_msg          =>  lv_msg',
'        );',
'        -- ERROR',
'        IF lv_msg IS NOT NULL THEN',
'            apex_error.add_error (',
'                p_message          => lv_msg,',
'                p_display_location => apex_error.c_inline_in_notification',
'            );',
'        END IF;',
'        ',
'--',
'    END IF;',
'',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(86993874495253821)
,p_process_success_message=>'Processing completed.'
,p_internal_uid=>16737596238817648
);
