wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(89541059312796921)
,p_process_sequence=>60
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'delete kb'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    lc_clob      CLOB;',
'    j            apex_json.t_values;',
'    lv_server    VARCHAR2(400);',
'    lV_input     VARCHAR2(32766);',
'    ln_code      VARCHAR2(4000);',
'    lv_text     apex_json.t_values;    ',
'BEGIN',
'    -- get server',
'    SELECT S_URL INTO lv_server FROM KMCHAT_KB_SERVER WHERE S_NAME = ''SERVER'' AND   APP_ID = V(''APP_ID'');',
'    apex_web_service.g_request_headers(1).name :=  ''Content-Type'';',
'    apex_web_service.g_request_headers(1).value := ''application/json'';',
'',
'    lV_input :=''{',
'      "knowledge_base_name": "''||:P7_KNOWLEDGE_BASE_NAME||''",',
'      "stub": "for json body, no need to input "',
'    }''; ',
'    ',
'    lc_clob := apex_web_service.make_rest_request(',
'        p_url => lv_server||''/knowledge_base/delete_kb'',',
'        p_http_method => ''POST'',',
'        p_body => lV_input',
'        -- p_wallet_path => ''file:///tmp/https_wallet''',
'    );',
'',
'    apex_json.parse(j, lc_clob);',
'',
'    IF apex_json.get_varchar2(p_path=>''code'',p_values=>j) = ''200'' THEN',
'        DELETE KMCHAT_KB WHERE ID = :P7_ID;',
'        DELETE KMCHAT_KB_FILES WHERE KB_ID = :P7_ID;',
'        DELETE KMCHAT_KB_BATCH WHERE KB_ID = :P7_ID;',
'        DELETE KMCHAT_GRAPH_CONFIG WHERE KB_NAME = :P7_KNOWLEDGE_BASE_NAME AND APP_ID = V(''APP_ID'');',
'        FOR rec_data IN (SELECT * FROM KMCHAT_KB_USER WHERE app_id = V(''APP_ID'')) LOOP',
'            IF INSTR(rec_data.AVAILABLE_VIEW_KB,:P7_KNOWLEDGE_BASE_NAME) > 0 THEN',
'               UPDATE KMCHAT_KB_USER',
'               SET    AVAILABLE_VIEW_KB = REPLACE(REPLACE(REPLACE(rec_data.AVAILABLE_VIEW_KB,'',''||:P7_KNOWLEDGE_BASE_NAME,NULL),:P7_KNOWLEDGE_BASE_NAME||'','',NULL),:P7_KNOWLEDGE_BASE_NAME,NULL)',
'               WHERE  ID = rec_data.ID; ',
'            END IF;',
'        END LOOP;',
'        COMMIT;',
'    ELSE',
'        apex_error.add_error (',
'            p_message          => lc_clob,',
'            p_display_location => apex_error.c_inline_in_notification',
'        );',
'    END IF;',
'EXCEPTION',
'    WHEN OTHERS THEN',
'    apex_error.add_error (',
'        p_message          => lc_clob||''  ; ''||SQLERRM,',
'        p_display_location => apex_error.c_inline_in_notification',
'    );',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'DELETE'
,p_process_when_type=>'REQUEST_EQUALS_CONDITION'
,p_process_success_message=>'The knowledge base has been deleted. '
,p_internal_uid=>19314204013399402
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(90887175681879620)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'get model and vector db'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_clob       clob;',
'    l1_clob      clob;',
'    j            apex_json.t_values;',
'    lv_column    VARCHAR2(32766);',
'    lv_sql       VARCHAR2(32766);',
'    lv_server    VARCHAR2(4000);',
'    ln_cnt       NUMBER;',
'BEGIN',
'    SELECT COUNT(1) INTO ln_cnt FROM  APEX_COLLECTIONS  WHERE  COLLECTION_NAME = ''TEMP_COL'';',
'',
'    IF ln_cnt = 0 THEN',
unistr('        -- \521B\5EFA\96C6\5408'),
'        APEX_COLLECTION.CREATE_OR_TRUNCATE_COLLECTION(p_collection_name => ''TEMP_COL'');',
'        SELECT S_URL INTO lv_server FROM KMCHAT_KB_SERVER WHERE S_NAME = ''SERVER'' AND   APP_ID = V(''APP_ID''); ',
'        -- get vector DB',
'        l_clob := apex_web_service.make_rest_request(',
'            p_url => lv_server||''/knowledge_base/list_vector_store_types'',',
'            p_http_method => ''GET''',
'            );',
'        apex_json.parse(j, l_clob);',
'        FOR I IN 1..apex_json.get_count(p_path=>''data'',p_values=>j) LOOP',
'            APEX_COLLECTION.ADD_MEMBER(',
'            	p_collection_name => ''TEMP_COL'',',
'            	p_c001            => apex_json.get_varchar2(p_path=>''data[''||I||'']'',p_values=>j),',
'                p_c002            => apex_json.get_varchar2(p_path=>''data[''||I||'']'',p_values=>j),',
'                p_c003            => ''V_DB''',
'            );',
'        END LOOP;',
'        -- get embedding_models',
'        l1_clob := apex_web_service.make_rest_request(',
'            p_url => lv_server||''/knowledge_base/list_embedding_models'',',
'            p_http_method => ''GET''',
'            );',
'        apex_json.parse(j, l1_clob);',
'        FOR I IN 1..apex_json.get_count(p_path=>''data'',p_values=>j) LOOP',
'            APEX_COLLECTION.ADD_MEMBER(',
'            	p_collection_name => ''TEMP_COL'',',
'            	p_c001            => apex_json.get_varchar2(p_path=>''data[''||I||'']'',p_values=>j),',
'                p_c002            => apex_json.get_varchar2(p_path=>''data[''||I||'']'',p_values=>j),',
'                p_c003            => ''E_MODEL''',
'            );            ',
'        END LOOP;',
'    END IF;',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        NULL;',
'END;',
'',
'',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>20660320382482101
);
