wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(102096231593987289)
,p_process_sequence=>30
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Set Batch default Value'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    ln_cnt NUMBER;',
'BEGIN',
'    IF :P7_ID IS NOT NULL THEN',
'        SELECT COUNT(1)',
'        INTO   ln_cnt',
'        FROM   KMCHAT_KB_BATCH',
'        WHERE  APP_ID = V(''APP_ID'')',
'        AND    KB_ID = :P7_ID',
'        AND    UPPER(batch_name) = ''DEFAULT'';',
'',
'        IF ln_cnt = 0 THEN',
'            :P7_BATCH_NAME := ''DEFAULT'';',
'        ELSE',
