wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(95747109666174823)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'FILE_DATA_SYNC'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    lc_clob          CLOB;',
'    j                apex_json.t_values;',
'    lv_msg           VARCHAR2(32766);',
'    lv_fileName      VARCHAR2(4000);',
'    ln_chunk_size    NUMBER;',
'    ln_chunk_overlap NUMBER;',
'    ln_max_batch_no  NUMBER;',
'    lv_batch_name    VARCHAR2(400);',
'    lv_status        VARCHAR2(400);',
'    ln_batch_cnt     NUMBER;',
'BEGIN',
unistr('    -- \5220\9664files\8868\6570\636E'),
'    lc_clob := apex_application.g_clob_01;',
'    apex_json.parse(j,lc_clob);',
'    -- delete files and batch',
'    DELETE KMCHAT_KB_FILES WHERE KB_ID = apex_application.g_x01 AND app_id = V(''APP_ID'');',
'    DELETE KMCHAT_KB_BATCH WHERE KB_ID = apex_application.g_x01 AND app_id = V(''APP_ID'');',
'--',
'    FOR I IN 1..apex_json.get_count(p_path=>''.'',p_values=>j) LOOP',
'',
'        lv_msg := apex_json.get_varchar2(p_path=>''[''||I||''].msg'',p_values=>j);',
'        lv_fileName := apex_json.get_varchar2(p_path=>''[''||I||''].file_basename'',p_values=>j);',
'        ln_chunk_size := apex_json.get_varchar2(p_path=>''[''||I||''].chunk_size'',p_values=>j);',
'        ln_chunk_overlap := apex_json.get_varchar2(p_path=>''[''||I||''].chunk_overlap'',p_values=>j);',
'        lv_batch_name := apex_json.get_varchar2(p_path=>''[''||I||''].batch_name'',p_values=>j);',
'        lv_status := apex_json.get_varchar2(p_path=>''[''||I||''].status'',p_values=>j);',
'        ',
'        SELECT count(1)',
'        INTO   ln_batch_cnt',
'        FROM   KMCHAT_KB_BATCH',
'        WHERE  app_id = V(''APP_ID'')',
'        AND    UPPER(batch_name) = UPPER(lv_batch_name)',
'        AND    kb_id             = apex_application.g_x01;',
'        ',
'        IF ln_batch_cnt = 0 THEN',
'            INSERT INTO kmchat_kb_batch(batch_name, chunk_size, chunk_overlap, kb_id, app_user, create_date, app_id)',
'                VALUES(',
'                    UPPER(lv_batch_name),',
'                    ln_chunk_size,',
'                    ln_chunk_overlap,',
'                    apex_application.g_x01,',
'                    V(''APP_USER''),',
'                    SYSDATE,',
'                    V(''APP_ID'')',
'                );',
'        END IF;',
'',
'        IF lv_status = ''success'' THEN',
'            INSERT INTO kmchat_kb_files(ID, appuser, create_date, filename, upload_status, kb_id, response_json_msg, batch_name, is_override, app_id)',
'            VALUES(',
'                KMCHAT_KB_FILES_SEQ.nextval,',
'                V(''APP_USER''),',
'                sysdate,',
'                lv_fileName,',
'                ''yes'',',
'                apex_application.g_x01,',
'                NULL,',
'                UPPER(lv_batch_name),',
'                ''true'',',
'                V(''APP_ID'')',
'                );',
'        ELSE',
'            INSERT INTO kmchat_kb_files(ID, appuser, create_date, filename, upload_status, kb_id, response_json_msg, batch_name, is_override, app_id)',
'            VALUES(',
'                KMCHAT_KB_FILES_SEQ.nextval,',
'                V(''APP_USER''),',
'                sysdate,',
'                lv_fileName,',
'                ''no'',',
'                apex_application.g_x01,',
'                lv_msg,',
'                UPPER(lv_batch_name),',
'                ''true'',',
'                V(''APP_ID'')',
'            );',
'        END IF;',
'',
'    END LOOP;',
'',
'    COMMIT;',
'    HTP.P(''''); ',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        HTP.P(SQLERRM);',
'        rollback;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>25520254366777304
);
