wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(89153730212175220)
,p_process_sequence=>50
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'DELETE_KB_FILE'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    lc_clob      CLOB;',
'    j            apex_json.t_values;',
'    lv_server    VARCHAR2(400);',
'    lV_input     VARCHAR2(32766);',
'    ln_code      VARCHAR2(4000);',
'    l_file_names apex_t_varchar2;',
'    TYPE TB_TYPE IS TABLE OF VARCHAR2(3000) INDEX BY BINARY_INTEGER;',
'    tb_file_name   TB_TYPE;',
'    lv_file_name VARCHAR2(32766);',
'BEGIN',
'    -- get server',
'    SELECT S_URL INTO lv_server FROM KMCHAT_KB_SERVER WHERE S_NAME = ''SERVER'' AND   APP_ID = V(''APP_ID'');',
'',
'    l_file_names := apex_string.split (',
'        p_str => apex_application.g_x02,',
'        p_sep => '','' ); ',
'',
'    FOR i IN 1 .. l_file_names.count LOOP',
'        tb_file_name(i) := substr(l_file_names(i),instr(l_file_names(i),''/'')+1,length(l_file_names(i)));',
'        IF  i = 1 THEN',
'            lv_file_name := ''"''|| apex_application.g_x04 || ''/'' || l_file_names(i);',
'        ELSE',
'            lv_file_name := lv_file_name || ''","'' || apex_application.g_x04 || ''/'' ||l_file_names(i);',
'        END IF;',
'    END LOOP;',
'    lv_file_name := lv_file_name||''"'';',
'    ',
'    apex_web_service.g_request_headers(1).name :=  ''Content-Type'';',
'    apex_web_service.g_request_headers(1).value := ''application/json'';',
'    lv_input := ''{',
'        "knowledge_base_name": "''||apex_application.g_x01||''",',
'        "filenames": [''||lv_file_name||'']',
'        }'';',
'    ',
'    lc_clob := apex_web_service.make_rest_request(',
'        p_url => lv_server||''/knowledge_base/delete_docs'',',
'        p_http_method => ''POST'',',
'        p_body => lv_input',
'    );',
'    apex_json.parse(j, lc_clob);',
'    ',
'    IF apex_json.get_varchar2(p_path=>''code'',p_values=>j) = ''200'' THEN',
'        FOR i IN 1 .. tb_file_name.count LOOP',
'            DELETE KMCHAT_KB_FILES',
'            WHERE  KB_ID = TO_NUMBER(apex_application.g_x03)',
'            AND    FILENAME = tb_file_name(i)',
'            AND    BATCH_NAME = apex_application.g_x04;',
'        END LOOP;',
'        COMMIT;',
'        HTP.P('''');',
'    ELSE',
'        htp.p(lc_clob);',
'    END IF;',
'EXCEPTION',
'    WHEN OTHERs THEN',
'        htp.p(sqlerrm);  ',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>18926874912777701
);
