,p_process_name=>'update'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'--set SERVEROUTPUT ON;',
'DECLARE',
'    lv_server    VARCHAR2(400);',
'    lv_input     VARCHAR2(32766);',
'    lc_clob      CLOB;',
'    J            apex_json.t_values;',
'    ln_code      VARCHAR2(3000);',
'    lv_pt_content VARCHAR2(32766);',
'BEGIN',
'    SELECT pt_content INTO lv_pt_content FROM kmchat_kb_prompt WHERE ID =  :P12_ID AND app_id = V(''APP_ID'');',
'',
'    IF lv_pt_content <> :P12_PT_CONTENT THEN',
'    -- get server',
'        SELECT s_url INTO lv_server FROM kmchat_kb_server WHERE s_name = ''SERVER'';',
'        ',
'        apex_web_service.g_request_headers(1).name :=  ''Content-Type'';',
'        apex_web_service.g_request_headers(1).value := ''application/x-www-form-urlencoded'';',
'        lc_clob := apex_web_service.make_rest_request(',
'            p_url => lv_server||''/prompt/update_prompt'',',
'            p_http_method => ''POST'',',
'            p_parm_name =>  apex_util.string_to_table(''name:template''),',
'            p_parm_value => apex_util.string_to_table(:P12_PT_NAME||'':''||:P12_PT_CONTENT)',
'            -- p_wallet_path => ''file:///tmp/https_wallet''',
'        );',
'',
'        apex_json.parse(J, lc_clob);',
'        ln_code := apex_json.get_varchar2(p_path=>''status'',p_values=>J);',
'        IF ln_code IS NULL THEN',
'            APEX_ERROR.ADD_ERROR (',
'                p_message => lc_clob,',
unistr('                p_display_location => apex_error.c_inline_in_notification   -- \9875\9762\7EA7\522B'),
'                );',
'        END IF;',
'        IF ln_code <> ''ok'' THEN',
'            APEX_ERROR.ADD_ERROR (',
'                p_message => NVL(apex_json.get_varchar2(p_path=>''err_msg'',p_values=>J),''Internal Server Error''),',
unistr('                p_display_location => apex_error.c_inline_in_notification   -- \9875\9762\7EA7\522B'),
'                );',
'        ELSE',
'            -- :P12_MSG := apex_json.get_varchar2(p_path=>''data'',p_values=>J);',
'            IF UPPER(APEX_UTIL.GET_SESSION_LANG) = ''ZH-CN'' THEN',
unistr('                :P12_MSG := ''\5DF2\66F4\65B0\63D0\793A\8BCD''||:P12_PT_NAME;'),
'            ELSE',
'                :P12_MSG := ''updated prompt''||:P12_PT_NAME;',
'            END IF;',
'        END IF;',
'',
'    ELSE',
'        IF UPPER(APEX_UTIL.GET_SESSION_LANG) = ''ZH-CN'' THEN',
unistr('            :P12_MSG := ''\5DF2\66F4\65B0\63D0\793A\8BCD''||:P12_PT_NAME||''.'';'),
'        ELSE',
'            :P12_MSG := ''updated prompt''||:P12_PT_NAME||''.'';',
'        END IF;',
'    END IF;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_when_button_id=>wwv_flow_imp.id(92385780677979399)
,p_internal_uid=>22192484462721003
);
