,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select kmch.HIS_ID,',
'       kmch.APP_ID,',
'       kmch.QUESTION,',
'       substr(kmch.ANSWER,1,50) as ANSWER,',
'       (select agent_name from kbot_md_agent where agent_id =kmch.agent_Id ) aGENT_name,',
'       kmch.CREATED_BY,',
'       kmch.CREATED_TIME,',
'       kmch.UPDATED_BY,',
'       kmch.UPDATED_TIME,',
'       kmch.SESSION_ID',
