,p_process_name=>'Del history'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'  ',
'  IF :P13_USER IS NULL THEN',
'    DELETE KBOT_MD_CHAT_HISTORY WHERE app_id = V(''APP_ID'');',
'  ELSE',
'    DELETE KBOT_MD_CHAT_HISTORY WHERE upper(created_by) = upper(:P13_USER) AND app_id = V(''APP_ID'');',
'  END IF;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_type=>'NEVER'
,p_internal_uid=>23761438589224210
