wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(136277710175962015)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'INSERT_KB_QA_OPTIMIZATION_H'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_kb_name  VARCHAR2(200);',
'  l_question VARCHAR2(4000);',
'  l_answer   CLOB;',
'  l_id      NUMBER;',
'BEGIN',
'  SELECT kb_name,question,REPLACE(REPLACE(REPLACE(COALESCE(REGEXP_SUBSTR(answer, ''(.*)<div>'',  1,  1,  NULL, 1),answer), ''<br/><br/>'', CHR(13) || CHR(10)),''<br/>'', CHR(13) || CHR(10)),'''''''', '''''''''''') ',
'    into l_kb_name, l_question, l_answer',
'    FROM KBOT_UI_KB_HISTORY',
'   WHERE id = apex_application.g_x01;',
'    ',
'    BEGIN',
'       SELECT id',
'       INTO   l_id',
'       FROM KBOT_UI_KB_QA_OPTIMIZATION',
'       WHERE  KB_NAME = l_kb_name',
'       AND    question = l_question',
'       AND    APP_ID  = :APP_ID;',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            l_id := NULL;',
'    END;',
'',
'    IF l_id IS NOT NULL THEN',
'        update KBOT_UI_KB_QA_OPTIMIZATION',
'        SET HID =  apex_application.g_x01',
'        WHERE ID = l_id;',
'    ELSE',
'        INSERT INTO KBOT_UI_KB_QA_OPTIMIZATION (HID, KB_NAME, QUESTION, ANSWER,PUBLISH_STATUS, CREATED_TIME, APP_ID, CREATED_BY)',
'        VALUES (apex_application.g_x01, l_kb_name, l_question, l_answer,''N'', current_date, V(''APP_ID''), V(''APP_USER''));',
'    END IF;',
'   ',
'   ',
'    COMMIT;',
'    HTP.P(1);',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        HTP.P(SQLERRM);',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_process_when_type=>'NEVER'
,p_internal_uid=>72942293612227636
);
end;
