begin
wwv_flow_imp_page.create_page(
 p_id=>16
,p_name=>'User Feedback'
,p_alias=>'USER-FEEDBACK'
,p_step_title=>'User Feedback'
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'let langCode = apex.item(P16_LANG_CODE).getValue();',
'function showMore(o, id) {',
'    let divID = "div#" + id;',
'    if ($(divID).is(":hidden")) {',
'        $(divID).show(500);',
'        $(o).html(''>> Show Less'');',
'    } else {',
'        $(divID).hide(500);',
'        $(o).html(''>> Show More'');',
'    }',
'}'))
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'$(document).ready(function(){',
'  $(document).on(''click'', ''.insert-btn'', function(){',
'    var qa_id = $(this).data(''id'');',
'    apex.message.clearErrors();',
'    apex.server.process(''INSERT_KB_QA_OPTIMIZATION_FB'', {',
'      x01: qa_id  ',
'    }, {',
'      dataType:''text'',',
'      success: function(pData) {',
'        if(pData == 1){',
'            if(langCode == ''zh-cn''){',
unistr('                apex.message.showPageSuccess("\63D2\5165\6210\529F\FF01");'),
'            }else{',
unistr('                apex.message.showPageSuccess("Data inserted successfully\FF01");'),
'            }',
'            apex.region("FeedbackStaticID").refresh();',
'        }else{',
'            apex.message.showErrors([{ type: "error", location: "page", message: pData, unsafe: false}]);',
'        }',
'        ',
'      },',
'      error: function(request, status, error) {',
'       if(langCode == ''zh-cn''){',
unistr('            apex.message.showErrors([{ type: "error", location: "page", message: ''\7CFB\7EDF\9519\8BEF\FF1A\8BE6\7EC6\9519\8BEF\4FE1\606F\8BF7\67E5\770B\6D4F\89C8\5668\63A7\5236\53F0\FF01'', unsafe: false}]);'),
'        }else{',
unistr('            apex.message.showErrors([{ type: "error", location: "page", message: ''system error:Please refer to the browser console for detailed error information\FF01'', unsafe: false}]);'),
'        }',
'        console.log(error);',
'      }',
'    });',
'  });',
'});'))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'#FeedbackStaticID th{',
