wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(90232542595685980)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'delete feedback'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'  ',
'  IF :P16_USER IS NULL THEN',
'    DELETE kbot_md_agent_feedback WHERE app_id = V(''APP_ID'');',
'',
'    UPDATE kbot_md_chat_session b',
'    SET b.FEEDBACK_ID = NULL,',
'        b.FEEDBACK_type = ''''',
'    WHERE EXISTS (',
'        SELECT 1',
'        FROM kbot_md_chat_session a',
'        WHERE a.session_id = b.PARENT_ID',
'        AND   a.app_id = V(''APP_ID'')',
'    );',
'  ELSE',
'    DELETE kbot_md_agent_feedback WHERE upper(created_by) = upper(:P16_USER) AND app_id = V(''APP_ID'');',
'    ',
'    UPDATE kbot_md_chat_session b',
'    SET b.FEEDBACK_ID = NULL,',
'        b.FEEDBACK_TYPE = ''''',
'    WHERE EXISTS (',
'        SELECT 1',
'        FROM kbot_md_chat_session a',
'        WHERE upper(a.APPUSER) = upper(:P16_USER)',
'        AND   a.session_id = b.PARENT_ID',
'        AND   a.app_id = V(''APP_ID'')',
'    );',
'',
'  END IF;',
'',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(90232423316685979)
,p_internal_uid=>9875834143784229
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(136278773630962026)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'INSERT_KB_QA_OPTIMIZATION_FB'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_kb_name  VARCHAR2(200);',
'  l_question VARCHAR2(4000);',
'  l_answer   CLOB;',
'  l_id      NUMBER;',
'BEGIN',
'  SELECT kb_name,question,REPLACE(REPLACE(REPLACE(COALESCE(REGEXP_SUBSTR(ANSWER_DISP, ''(.*)<div>'',  1,  1,  NULL, 1),ANSWER_DISP), ''<br/><br/>'', CHR(13) || CHR(10)),''<br/>'', CHR(13) || CHR(10)),'''''''', '''''''''''') ',
'    into l_kb_name, l_question, l_answer',
'    FROM kbot_ui_kb_feedback',
'   WHERE id = apex_application.g_x01;',
'   ',
'   BEGIN',
'       SELECT id',
'       INTO   l_id',
'       FROM KBOT_UI_KB_QA_OPTIMIZATION',
'       WHERE  KB_NAME = l_kb_name',
'       AND    question = l_question',
'       AND    APP_ID  = :APP_ID;',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            l_id := NULL;',
'    END;',
'',
'   IF l_id IS NOT NULL THEN',
'        update KBOT_UI_KB_QA_OPTIMIZATION',
'        SET FBID =  apex_application.g_x01',
'        WHERE ID = l_id;',
'   ELSE',
'        INSERT INTO KBOT_UI_KB_QA_OPTIMIZATION (FBID, KB_NAME, QUESTION, ANSWER, PUBLISH_STATUS, CREATED_TIME, APP_ID, CREATED_BY)',
'        VALUES (apex_application.g_x01, l_kb_name, l_question, l_answer, ''N'', current_date, V(''APP_ID''), V(''APP_USER''));',
'   END IF;',
'',
'  COMMIT;',
unistr('  -- \8FD4\56DE JSON \54CD\5E94'),
'  HTP.P(1);',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        HTP.P(SQLERRM);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_when_type=>'NEVER'
,p_internal_uid=>72943357067227647
);
end;
