,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select  UPPER(kku.USER_NAME) USER_NAME,',
'        kku.AUTH_ROLE,',
'        count(kcup.PROFILE_NAME) profile_count,',
'        kku.APP_ID               APP_ID',
'  from KMCHAT_CHAT_USER_PROFILE kcup,',
'       KMCHAT_KB_USER    kku',
'  where UPPER(kcup.app_user(+)) = UPPER(kku.user_name)',
'  AND   kcup.app_id(+)   =  kku.app_id',
'  AND   kcup.profile_name (+)<> ''Sys_Default''',
'  AND   kku.app_id  = V(''APP_ID'')',
'  AND   UPPER(kku.user_name ) = UPPER(:P20_USER_NAME_PROFILE)',
'  group by kku.USER_NAME,kku.AUTH_ROLE,kku.APP_ID',
'',
'',
'',
''))
,p_ajax_enabled=>'Y'
