 p_id=>wwv_flow_imp.id(96395186072901723)
,p_name=>'LLM_MODEL'
,p_source_type=>'DB_COLUMN'
,p_source_expression=>'LLM_MODEL'
,p_data_type=>'VARCHAR2'
,p_session_state_data_type=>'VARCHAR2'
,p_is_query_only=>false
,p_item_type=>'NATIVE_SELECT_LIST'
,p_heading=>'Llm Model'
,p_heading_alignment=>'LEFT'
,p_display_sequence=>90
,p_value_alignment=>'LEFT'
,p_is_required=>true
,p_lov_type=>'FUNCTION_BODY'
,p_lov_language=>'PLSQL'
,p_lov_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_clob clob;',
'    j            apex_json.t_values;',
'    lv_column    VARCHAR2(32766);',
'    lv_sql       VARCHAR2(32766);',
'    lv_server    VARCHAR2(4000);',
'BEGIN',
'    SELECT S_URL INTO lv_server FROM KMCHAT_KB_SERVER WHERE S_NAME = ''SERVER'' AND APP_ID = :P20_APP_ID; ',
'    l_clob := apex_web_service.make_rest_request(',
'        p_url => lv_server||''/chat/list_LLMs'',',
'        p_http_method => ''GET''',
'        );',
'    apex_json.parse(j, l_clob);',
'    FOR I IN 1..apex_json.get_count(p_path=>''data'',p_values=>j) LOOP',
'        IF I = 1 THEN',
'            lv_column := apex_json.get_varchar2(p_path=>''data[''||I||'']'',p_values=>j);',
'        ELSE',
'            lv_column := lv_column || '','' ||apex_json.get_varchar2(p_path=>''data[''||I||'']'',p_values=>j);',
'        END IF; ',
'    END LOOP;',
'',
'    lv_sql := ''SELECT regexp_substr (''''''||lv_column||'''''', ''''[^,]+'''',1, rownum) d,regexp_substr (''''''||lv_column||'''''', ''''[^,]+'''',1, rownum) r',
'    FROM   dual',
'    CONNECT BY LEVEL <= regexp_count (''''''||lv_column||'''''', ''''[^,]+'''')',
'    order by d',
'    '';',
'',
'    RETURN lv_sql;',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        RETURN ''select ''''- Service error -'''' d, null r from dual'';',
'END;',
'',
'',
''))
,p_lov_display_extra=>false
,p_lov_display_null=>false
,p_enable_filter=>true
,p_filter_operators=>'C:S:CASE_INSENSITIVE:REGEXP'
