,p_lov_type=>'FUNCTION_BODY'
,p_lov_language=>'PLSQL'
,p_lov_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    lv_sql VARCHAR2(4000);',
'    lv_available_view_prompt VARCHAR2(4000);',
'    lv_sql2 varchar2(4000);',
'BEGIN',
'    lv_sql := ''SELECT pt_name d, pt_name r FROM kmchat_kb_prompt WHERE pt_status = ''''Y'''' AND app_id = :P20_APP_ID'';',
'    lv_sql2 := '' select ''''rag_default'''' d , ''''rag_default'''' r from  dual'';',
'    IF :P20_IS_ADMIN = ''YES'' OR apex_app_setting.get_value(p_name => ''ACCESS_CONTROL_SCOPE'') = ''ALL_USERS'' THEN',
'        RETURN lv_sql ||'' union ''||lv_sql2 ;',
'    ELSE',
'        BEGIN',
'            SELECT available_view_prompt INTO lv_available_view_prompt FROM kmchat_kb_user WHERE UPPER(user_name) =:P20_USER_NAME_PROFILE AND app_id = :P20_APP_ID;',
'            lv_available_view_prompt := ''''''''||REPLACE(lv_available_view_prompt, '','' ,'''''','''''')||'''''''';',
'        EXCEPTION  ',
'            WHEN OTHERS THEN',
'                lv_available_view_prompt := NULL;',
'        END;',
'        ',
'        IF lv_available_view_prompt IS NOT NULL THEN',
'            lv_sql := lv_sql ||'' AND (pt_name IN(''||lv_available_view_prompt||'')'';',
'            RETURN lv_sql ||''    OR UPPER(create_by) = :P20_USER_NAME_PROFILE)'' ||'' union ''||lv_sql2;',
'        END IF;',
'        ',
'        RETURN lv_sql ||'' AND UPPER(create_by) = :P20_USER_NAME_PROFILE'' ||'' union ''||lv_sql2; ',
'        ',
'    END IF;',
'END;'))
