wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(99160486180275220)
,p_name=>'P20_USER_NAME_PROFILE'
,p_item_sequence=>30
,p_use_cache_before_default=>'NO'
,p_item_default=>'SELECT V(''APP_USER'') FROM DUAL'
,p_item_default_type=>'SQL_QUERY'
,p_prompt=>'Please select the user''s chat profile'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select UPPER(user_name) d,',
'       UPPER(user_name) r',
'from   KMCHAT_KB_USER',
'where  app_id = V(''APP_ID'')',
'ORDER BY AUTH_ROLE'))
,p_cSize=>30
,p_read_only_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    lv_auth_role VARCHAR2(500);',
'BEGIN',
'    IF apex_app_setting.get_value(p_name => ''ACCESS_CONTROL_SCOPE'') = ''ALL_USERS'' THEN',
'        RETURN FALSE;',
'    ELSE',
'        SELECT auth_role',
'        INTO   lv_auth_role',
'        FROM   kmchat_kb_user',
'        WHERE  UPPER(user_name) = V(''APP_USER'') AND app_id = V(''APP_ID'');',
'        ',
'        IF lv_auth_role = ''ADMIN'' THEN',
'            RETURN FALSE;',
'        ELSE',
'            RETURN TRUE;',
'        END IF;',
'    END IF;',
'    ',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        RETURN TRUE;',
'END;'))
,p_read_only_when2=>'PLSQL'
,p_read_only_when_type=>'FUNCTION_BODY'
,p_field_template=>wwv_flow_imp.id(106532568633103579)
,p_item_icon_css_classes=>'fa-server-user'
,p_item_template_options=>'#DEFAULT#:t-Form-fieldContainer--stretchInputs:margin-bottom-none'
,p_lov_display_extra=>'NO'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'case_sensitive', 'N',
  'display_as', 'POPUP',
  'fetch_on_search', 'N',
  'initial_fetch', 'FIRST_ROWSET',
  'manual_entry', 'N',
  'match_type', 'CONTAINS',
  'min_chars', '0')).to_clob
);
