wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(99386398774907201)
,p_tabular_form_region_id=>wwv_flow_imp.id(99139481744030572)
,p_validation_name=>'check profile_name'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    ln_cnt  NUMBER;',
'begin',
'    IF :PROFILE_NAME = ''Sys_Default'' and :ID IS NULL THEN',
'        select count(1) INTO ln_cnt from KMCHAT_CHAT_USER_PROFILE WHERE APP_ID = :P20_APP_ID AND PROFILE_NAME = ''Sys_Default'';',
'',
'        if ln_cnt > 0 then',
'            return false;',
'        else',
'            return true;',
'        end if;',
'    ELSE',
'        RETURN TRUE;',
'',
'    END IF;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>unistr('#COLUMN_HEADER# Already exists\3002')
,p_associated_column=>'PROFILE_NAME'
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(99389030535907228)
,p_tabular_form_region_id=>wwv_flow_imp.id(99139481744030572)
,p_validation_name=>'check user default profile'
,p_validation_sequence=>20
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    ln_cnt NUMBER;',
'begin',
'     case :APEX$ROW_STATUS',
'     when ''C'' then',
'        IF :USER_DEFAULT_PROFILE = ''Y'' THEN',
'            --',
'            select count(1) INTO ln_cnt ',
'            from KMCHAT_CHAT_USER_PROFILE ',
'            WHERE APP_ID = :P20_APP_ID ',
'            AND USER_DEFAULT_PROFILE = ''Y'' ',
'            AND UPPER(APP_USER) = UPPER(:P20_USER_NAME_PROFILE);',
'            --',
'            if ln_cnt > 0 then',
'                return false;',
'            else',
'                return true;',
'            end if; ',
'        end if;',
'     when ''U'' then',
'        IF :USER_DEFAULT_PROFILE = ''Y'' THEN',
'            --',
'            select count(1) INTO ln_cnt ',
'            from KMCHAT_CHAT_USER_PROFILE ',
'            WHERE APP_ID = :P20_APP_ID ',
'            AND USER_DEFAULT_PROFILE = ''Y'' ',
'            AND UPPER(APP_USER) = UPPER(:P20_USER_NAME_PROFILE)',
'            AND ID <> :ID;',
'            --',
'            if ln_cnt > 0 then',
'                return false;',
'            else',
'                return true;',
'            end if; ',
'        end if;',
'',
'     when ''D'' then',
'          RETURN TRUE;',
'     end case;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'#COLUMN_HEADER# can only be set to one default value.'
,p_associated_column=>'USER_DEFAULT_PROFILE'
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
