'             apex.item(P21_STATUS).setValue(''Error'');',
'                $("#P21_STATUS").css({"background":"#CD5C5C"});',
'                $("#SEND_BTN").prop(''disabled'', true);',
'                $("#P21_INPUT").prop("disabled", true);',
'          }',
'        });',
'}',
'',
'function saveProfile(){',
'    if(apex.item(P21_PROFILE_NAME).getValue().length == 0){',
'        if(langCode == ''zh-cn''){',
unistr('            apex.message.showErrors([{ type: "error", location: [ "page", "inline" ], pageItem: "P21_PROFILE_NAME", message: ''\3010\914D\7F6E\540D\79F0\3011\4E0D\80FD\4E3A\7A7A.'', unsafe: false}]);'),
'        }else{',
unistr('            apex.message.showErrors([{ type: "error", location: [ "page", "inline" ], pageItem: "P21_PROFILE_NAME", message: ''\3010Profile Name\3011 cannot be empty.'', unsafe: false}]);'),
'        }    ',
'        return;',
'        ',
