'                apex.item(P21_PROFILE).refresh();',
'                $("#SaveProfilesStatic").dialog("close");',
'            }else{',
'                apex.message.showErrors([{ type: "error", location: "page", message: data, unsafe: false}]);',
'            }',
'        },',
'        error: function( jqXHR, textStatus, errorThrown ) {',
'            // handle error',
'            apex.message.showErrors([{ type: "error", location: "page", message: textStatus, unsafe: false}]);',
'        }',
'    } );',
'}',
'',
'function keyup_submit(e) {',
'    var evt = window.event || e;',
'    if (evt.keyCode === 13) {',
unistr('        //\56DE\8F66\4E8B\4EF6'),
'        //   $(''#SEND_BTN'').click();',
'        // lCancelEvent = apex.event.trigger(''#SEND_BTN'', ''click'', [''apples'',''pears'']);',
'    }',
'    return false;',
'}',
'',
'function showMore(o, id) {',
'    let divID = "div#" + id;',
'    if ($(divID).is(":hidden")) {',
'        $(divID).show(500);',
'        $(o).html(''>> Show Less'');',
'    } else {',
'        $(divID).hide(500);',
'        $(o).html(''>> Show More'');',
'    }',
'}',
'',
'',
'var recorder;',
'const canvas = document.querySelector(''.visualizer'');',
'let audioCtx;',
'const canvasCtx = canvas.getContext("2d");',
'var myStream;',
'',
'function visualize(stream) {',
'    if (!audioCtx) {',
'        audioCtx = new AudioContext();',
'    }',
'',
'    const source = audioCtx.createMediaStreamSource(stream);',
'',
'    const analyser = audioCtx.createAnalyser();',
'    analyser.fftSize = 2048;',
'    const bufferLength = analyser.frequencyBinCount;',
'    const dataArray = new Uint8Array(bufferLength);',
'',
'    source.connect(analyser);',
'    //analyser.connect(audioCtx.destination);',
'',
'    draw()',
'',
'    function draw() {',
'        const WIDTH = canvas.width',
'        const HEIGHT = canvas.height;',
'',
'        requestAnimationFrame(draw);',
'',
'        analyser.getByteTimeDomainData(dataArray);',
'',
'        canvasCtx.fillStyle = ''rgb(145,225,104)'';//''rgb(200, 200, 200)'';',
'        canvasCtx.fillRect(0, 0, WIDTH, HEIGHT);',
'',
'        canvasCtx.lineWidth = 2;',
'        canvasCtx.strokeStyle = ''rgb(50, 50, 50)''//''rgb(0, 0, 0)'';',
'',
'        canvasCtx.beginPath();',
'',
'        let sliceWidth = WIDTH * 1.0 / bufferLength;',
'        let x = 0;',
'',
'',
'        for (let i = 0; i < bufferLength; i++) {',
'',
'            let v = dataArray[i] / 128.0;',
'            let y = v * HEIGHT / 2;',
'',
'            if (i === 0) {',
'                canvasCtx.moveTo(x, y);',
'            } else {',
'                canvasCtx.lineTo(x, y);',
'            }',
'',
'            x += sliceWidth;',
'        }',
'',
'        canvasCtx.lineTo(canvas.width, canvas.height / 2);',
'        canvasCtx.stroke();',
'',
'    }',
'}',
'',
'function AudioInit() {',
'    $(''#AUDIO-BTN'').prop(''disabled'', true);',
'    navigator.mediaDevices.getUserMedia({ audio: true }).then(function (stream) {',
'        myStream = stream;',
'        visualize(stream);',
'        var input = new AudioContext().createMediaStreamSource(stream);',
'        recorder = new Recorder(input, { sampleRate: 16000, numChannels: 1 });',
'        recorder.record();',
'    });',
'    setTimeout(function () {',
'        AudioStop();',
'        $("#popup_callout").popup("close");',
'    }, 1000 * 60 * 2);',
'}',
'',
'',
'function AudioStop() {',
'    if (recorder) {',
'        recorder && recorder.stop();',
'        // button.disabled = true;',
'        // button.previousElementSibling.disabled = false;',
'        // createDownloadLink();',
'        recorder.clear();',
'        myStream.getAudioTracks()[0].stop();',
'        $(''#AUDIO-BTN'').prop(''disabled'', false);',
'    }',
'}',
'',
'var myArrayBuffer;',
'function AudioSave() {',
'    if (recorder) {',
'        //                 const frameCount = audioCtx.sampleRate * 2.0;',
'        // myArrayBuffer = audioCtx.createBuffer(2, frameCount, audioCtx.sampleRate);',
'        //         alert("onloadend: "+myArrayBuffer.duration);',
'        // console.log(recorder); console.log(audioCtx); //alert(recorder.AudioContext().currentTime);',
'        recorder && recorder.exportWAV(function (blob) {',
'            var reader = new FileReader();',
'            reader.onloadend = function () {',
'                AudioStop();',
'                if (reader) {',
'                    var data = reader.result;',
'                    var afterData = data.replace(/^data:audio\/\w+;base64,/, "");',
'                    apex.server.process("saveAudio", {',
'                        "f01": afterData,',
'                        pageItems: ["P21_URL", "P21_MODEL", "P21_RIVA_URL", "P21_CHAT_ID", "P21_AUDIO_LANG"]',
'                    }, {',
'                        dataType: "text"',
'                    }).then(function (data) {',
'                        console.log(data);',
'                        let jsonObj = JSON.parse(data);',
'                        apex.item("P21_INPUT").setValue(jsonObj.text_disp);',
'                        apex.item("P21_CHAT_ID").setValue(jsonObj.id);',
'',
'                        // console.log(data);',
'                        // apex.item("P21_PENDING_ICON").setValue("0");',
'                        // apex.item("P21_CHAT_ID").setValue(data);',
'                        // apex.region("KMCHATBOT").refresh().then(function () {',
'                        //     popFeedback();',
'                        //     window.scrollTo(0, document.body.scrollHeight);',
'                        // });',
'                    });',
'                }',
'            };',
'',
'            reader.readAsDataURL(blob);',
'            var url = URL.createObjectURL(blob);',
'            // var div = document.getElementById(''recordingslist'');',
'            var au = document.createElement(''audio'');',
'            var hf = document.createElement(''a'');',
'',
'            au.controls = true;',
'            au.style = "width: 100%;";',
'            au.src = url;',
'            hf.href = url;',
'            hf.download = new Date().toISOString() + ''.wav'';',
'            hf.innerHTML = hf.download;',
'            // recordingslist.appendChild(au);',
'            // recordingslist.appendChild(hf);',
'        });',
'    }',
'',
'}',
'',
'',
'function replaceAudioSrc() {',
'    $("audio.my-audio").each(function (i) {',
'        let lk = this.src;',
'        let reader = new FileReader();',
'        // var reader = new File([await (await fetch(lk)).blob()], lk);//new FileReader(this.src);',
'',
'        reader.onloadend = function () {',
'            // console.log(reader);',
'        };',
'',
'        fetch(lk).then(res => res.blob()).then(blob => {',
'            reader.readAsDataURL(blob);',
'            let url = URL.createObjectURL(blob);',
'            this.src = url;',
'        });',
'',
'    });',
'}',
'',
'let objParent,chatId,feedBack;',
'',
'function afterReportFresh() {',
'    $(".fb-good").each(function (i) {',
'        $(this).on("click", function () {',
'            let chat_id = $(this).parent().prop(''id'');',
'            // save good feedback',
'            saveFeedbackAfter($(this).parent(), chat_id, "good",'''');',
'        });',
'    });',
'',
'    $(".fb-bad").each(function (i) {',
'        $(this).on("click", function () {',
'            let chat_id = $(this).parent().prop(''id'');',
'            // feedback info',
'            let lvresult = apex.event.trigger(''#HideBtnFd'', ''click'');',
'            // save bad feedback',
'            objParent = $(this).parent();',
'            chatId    = chat_id;',
'            feedBack  = "bad";',
'            // saveFeedbackAfter($(this).parent(), chat_id, "bad");',
'        });',
'    });',
'}',
'',
'function saveFeedbackAfter(o, id, feedback, info) {',
'    return saveFeedback(id, feedback, info).then(data => {',
'        if (data === 1) {',
'            o.fadeOut(500, function () {',
'                let str;',
'                if (feedback === "good") {',
unistr('                    str = ''<span class="feedback-readonly">\D83D\DC4D</span>'';'),
'                }',
'                else if (feedback === "bad") {',
unistr('                    str = ''<span class="feedback-readonly">\D83D\DC4E</span>'';'),
