'                // handle error',
'                alert("error");',
'                reject(jqXHR, textStatus, errorThrown);',
'            }',
'        });',
'    });',
'',
'}',
'',
'',
'function popFeedback() {',
'    setTimeout(function () {',
'        let htmlStr = ''<li id="feedback-dialog" style="display:none;" class="t-Comments-item #COMMENT_MODIFIERS#"><div class="t-Comments-icon"><div class="t-Comments-userIcon chatbot fa fa-commenting-o" aria-hidden="true">#USER_ICON#</div></div><div '
||'class="t-Comments-body"><div class="t-Comments-info"><span class="t-Comments-date"></span> <span class="t-Comments-actions"></span></div><div class="t-Comments-comment chatbot-comment">Is this answer helpful?<div class="fb-dialog"><span class="feedba'
||'ck-btn" style="margin-right: 1.5rem;" onclick="feedbackAction(this, 1)">??</span><span class="feedback-btn" onclick="feedbackAction(this, 0);">??</span>''',
'            + ''</div></div></div></div></div>'';',
'        htmlStr += ''</li>'';',
'        $(''#KMCHATBOT_report'').append(htmlStr);',
'        $(''#feedback-dialog'').fadeIn(1500);',
'        window.scrollTo(0, document.body.scrollHeight);',
