'        iconStatus = ''??'';',
'    }',
'    let htmlStr = ''<li class="t-Comments-item #COMMENT_MODIFIERS#"><div class="t-Comments-icon"><div class="t-Comments-userIcon appuser fa fa-user" aria-hidden="true">#USER_ICON#</div></div><div class="t-Comments-body"><div class="t-Comments-info"><s'
||'pan class="t-Comments-date"></span> <span class="t-Comments-actions"><span class="feedback-action"></span></span></div><div class="t-Comments-comment appuser-comment"><span class="feedback-readonly">'' +',
'        iconStatus +',
'        ''</span></div></div></li>'';',
'    $(''#KMCHATBOT_report'').append(htmlStr);',
'    $(''#feedback-dialog'').fadeIn(1200);',
'    window.scrollTo(0, document.body.scrollHeight);',
'',
'    $(o).parent().children(''span.feedback-btn'').each(function () {',
'        $(this).removeClass(''feedback-btn'').addClass(''feedback-readonly'');',
