wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(111037146607923093)
,p_name=>'P21_MODEL'
,p_item_sequence=>60
,p_item_plug_id=>wwv_flow_imp.id(138215613406820043)
,p_prompt=>'LLM Model'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov_language=>'PLSQL'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_clob clob;',
'    j            apex_json.t_values;',
'    lv_column    VARCHAR2(32766);',
'    lv_sql       VARCHAR2(32766);',
'    lv_server    VARCHAR2(4000);',
'BEGIN',
'    SELECT S_URL INTO lv_server FROM KMCHAT_KB_SERVER WHERE S_NAME = ''SERVER'' AND APP_ID = V(''APP_ID''); ',
'    l_clob := apex_web_service.make_rest_request(',
'        p_url => lv_server||''/chat/list_LLMs'',',
'        p_http_method => ''GET''',
'        );',
'    apex_json.parse(j, l_clob);',
'    FOR I IN 1..apex_json.get_count(p_path=>''data'',p_values=>j) LOOP',
'        IF I = 1 THEN',
'            lv_column := apex_json.get_varchar2(p_path=>''data[''||I||'']'',p_values=>j);',
'        ELSE',
'            lv_column := lv_column || '','' ||apex_json.get_varchar2(p_path=>''data[''||I||'']'',p_values=>j);',
'        END IF; ',
'    END LOOP;',
'',
'    lv_sql := ''SELECT regexp_substr (''''''||lv_column||'''''', ''''[^,]+'''',1, rownum) d,regexp_substr (''''''||lv_column||'''''', ''''[^,]+'''',1, rownum) r',
'    FROM   dual',
'    CONNECT BY LEVEL <= regexp_count (''''''||lv_column||'''''', ''''[^,]+'''')',
'    order by d',
'    '';',
'',
'    RETURN lv_sql;',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        RETURN ''select ''''- Service error -'''' d, null r from dual'';',
'END;',
'',
'',
''))
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(106532568633103579)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(111037233428923094)
,p_name=>'P21_PROMPT_NAME'
,p_item_sequence=>70
,p_item_plug_id=>wwv_flow_imp.id(138215613406820043)
,p_prompt=>'Prompt Name'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov_language=>'PLSQL'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    lv_sql VARCHAR2(32766);',
'    lv_available_view_prompt VARCHAR2(4000);',
'BEGIN',
'    lv_sql := ''SELECT pt_name d, pt_name r FROM kmchat_kb_prompt WHERE pt_status = ''''Y'''' AND app_id =V(''''APP_ID'''')'';',
'    IF apex_authorization.is_authorized (p_authorization_name => ''ADMIN'' ) = TRUE OR apex_app_setting.get_value(p_name => ''ACCESS_CONTROL_SCOPE'') = ''ALL_USERS'' THEN',
'        RETURN lv_sql;',
'    ELSE',
'        BEGIN',
'            SELECT available_view_prompt INTO lv_available_view_prompt FROM kmchat_kb_user WHERE UPPER(user_name) = V(''APP_USER'') AND app_id = V(''APP_ID'');',
'            lv_available_view_prompt := ''''''''||REPLACE(lv_available_view_prompt, '','' ,'''''','''''')||'''''''';',
'        EXCEPTION  ',
'            WHEN OTHERS THEN',
'                lv_available_view_prompt := NULL;',
'        END;',
'        ',
'        IF lv_available_view_prompt IS NOT NULL THEN',
'            lv_sql := lv_sql ||'' AND (pt_name IN(''||lv_available_view_prompt||'')'';',
'            RETURN lv_sql ||''    OR UPPER(create_by) = V(''''APP_USER''''))'';',
'        END IF;',
'        ',
'        RETURN lv_sql ||'' AND UPPER(create_by) = V(''''APP_USER'''')''; ',
'        ',
'    END IF;',
'END;',
''))
,p_lov_display_null=>'YES'
,p_lov_null_text=>'rag_default'
,p_lov_null_value=>'rag_default'
,p_cHeight=>1
