,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'let data = {',
'    "ask": "How to understand the multi-tenant architecture of Oracle database and what are its advantages? What scene is it suitable for?",',
'    "model_name": "Oracle19c_EN"',
'}',
'var requestOptions = {',
'    method: ''POST'',',
'    headers: {',
'        ''Content-Type'':',
'            ''application/json;charset=utf-8''',
'    },',
'    body: JSON.stringify(data)',
'};',
'',
'// http://152.69.226.154:8088/ords/xh/test/riva https://llm.oracle.k8scloud.site/chat/chat_llm_stream',
'fetch(''https://llm.oracle.k8scloud.site/chat/chat_llm_stream'', requestOptions).then(async (response) => {',
'    if (response.body) {',
'        //   // console.log(` 333  ${response.body}`);',
'        const textDecoder = new TextDecoder();',
'        const reader = response.body.getReader();',
'',
'        let charsReceived = 0;',
'        let result;',
'        let list2 = document.getElementById("list2");',
'        let para = document.getElementById("para");',
'        // read() returns a promise that resolves',
'        // when a value has been received',
'        reader.read().then(function processText({ done, value }) {',
'            // Result objects contain two properties:',
'            // done  - true if the stream has already given you all its data.',
'            // value - some data. Always undefined when done is true.',
'            if (done) {',
'                console.log("Stream complete");',
'                para.textContent = value;',
'                return;',
'            }',
'',
'            // value for fetch streams is a Uint8Array',
'            charsReceived += value.length;',
'            const chunk = value;',
'',
'            console.log(`Received ${charsReceived} characters so far. Current chunk = ${chunk}`);',
'            const chunkText = textDecoder.decode(chunk);',
'            console.log(` @@@  ${chunkText}`);',
'',
'            let listItem = document.createElement("li");',
'            listItem.textContent = `${chunkText}`;',
'',
'            list2.appendChild(listItem);',
'',
'            result += chunk;',
'',
'            // Read some more, and call this function again',
'            return reader.read().then(processText);',
'        });',
'',
'',
'    }',
'',
'});'))
);
