'        :P22_ID := NULL;',
'        :P22_LLM_ENDPOINT := NULL;',
'        :P22_LLM_MODEL := NULL;',
'        :P22_LLM_API_KEY := NULL;',
'        :P22_EMBEDDING_ENDPOINT := NULL;',
'        :P22_EMBEDDING_MODEL := NULL;',
'        :P22_EMBEDDING_API_KEY:= NULL;',
'        :P22_YAML_FILE:= NULL;',
'        :P22_PROMPT_FILE := NULL;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>45955774133537111
);
