wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(96153437029165922)
,p_name=>'Synonym Standard Question Management'
,p_template=>wwv_flow_imp.id(106470686057103554)
,p_display_sequence=>30
,p_include_in_reg_disp_sel_yn=>'Y'
,p_region_css_classes=>'js-detail-region'
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with tb1 as (',
'    select ID,',
'        CONF_ID,',
'       ''Details'' as link,  ',
'        STANDARD_QUESTION,',
'        CREATED_BY,',
'        to_char(CREATED_TIME,''yyyy-mm-dd hh24:mi:ss'')  CREATE_DATE',
'    from KBOT_UI_KB_SYNONYM_MASTER',
'    where CONF_ID = :P24_ID',
'    AND   app_Id =  :APP_ID),',
'tb2 as (SELECT MASTER_ID, COUNT(IS_EMBEDDING) as cnt FROM KBOT_UI_KB_SYNONYM_DETAIL WHERE app_id = :APP_ID  group by MASTER_ID),',
'tb3 as (SELECT MASTER_ID, COUNT(IS_EMBEDDING) as cnt FROM KBOT_UI_KB_SYNONYM_DETAIL where app_id = :APP_ID and IS_EMBEDDING = ''Y'' group by MASTER_ID)',
'select tb1.ID, ',
'       tb1.CONF_ID, ',
'       tb1.link,',
'       tb1.STANDARD_QUESTION,',
'       tb1.CREATED_BY,',
'       tb1.CREATE_DATE,',
'       nvl(tb2.cnt,0) total_count,',
'       nvl(tb3.cnt,0) embedding_count,',
'       nvl(tb2.cnt,0)-nvl(tb3.cnt,0) unembedding_count',
'from   tb1,tb2,tb3',
'where  tb1.id = tb2.MASTER_ID(+)',
'and    tb1.id = tb3.MASTER_ID(+);'))
,p_display_when_condition=>'P24_ID'
,p_display_condition_type=>'ITEM_IS_NOT_NULL'
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(106497507993103563)
,p_query_num_rows=>100
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'not data found.'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_query_row_count_max=>5000
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'Y'
);
