 p_id=>wwv_flow_imp.id(96191466007430906)
,p_process_sequence=>10
,p_process_point=>'AFTER_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Knowledge Base Check'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    lv_kb     varchar2(4000);',
'    lv_status varchar2(4000);',
'    ln_cnt    number;',
'begin',
'    if :P24_ID is not null then        ',
'         select count(1) ',
'         into ln_cnt ',
'         from KBOT_UI_KB ',
'         where KB_NAME = (select KB_NAME from KBOT_UI_KB_SYNONYM_CONF where id = :P24_ID)',
'         and  app_id   = V(''APP_ID'');',
'         ',
'         IF ln_cnt > 0 THEN',
'            IF UPPER(APEX_UTIL.GET_SESSION_LANG) = ''ZH-CN'' THEN',
unistr('                :P24_KB_STATUS := ''\6709\6548'';'),
'            ELSE',
'                :P24_KB_STATUS := ''Valid'';',
'            END IF;',
'         ELSE',
'            IF UPPER(APEX_UTIL.GET_SESSION_LANG) = ''ZH-CN'' THEN',
unistr('                :P24_KB_STATUS := ''\65E0\6548'';'),
'            ELSE',
'                :P24_KB_STATUS := ''Invalid'';',
'            END IF;',
'         END IF;',
'',
'    else',
'        :P24_KB_STATUS := NULL;',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>32856049443696527
);
