wwv_flow_imp_page.create_page(
 p_id=>25
,p_name=>'Clear knowledge base data'
,p_alias=>'CLEAR-KNOWLEDGE-BASE-DATA'
,p_step_title=>'Clear knowledge base data'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'let langCode = apex.item(P25_LANG_CODE).getValue();',
'',
'function callClearData(value){',
'    apex.message.clearErrors();',
'    apex.server.process( "CLEAR_KB_DATA", {',
'        x01: value',
'    }, {',
'        dataType:''text''',
'        ,success: function( data )  {',
'            if(data.trim().length == 0){',
'                if(langCode == ''zh-cn''){',
unistr('                    apex.message.showPageSuccess( ''\6570\636E\6E05\9664\6210\529F.'' );'),
'                }else{',
'                    apex.message.showPageSuccess( ''Data cleared successfully.'' );',
'                }',
'                apex.region("IGStatic").refresh();',
'            }else{',
'                apex.message.showErrors([{type:"error", location:"page", message:data, unsafe:false}]);',
'            }',
'        },',
'        error: function( jqXHR, textStatus, errorThrown ) {',
'            apex.message.showErrors([{type:"error", location:"page", message:textStatus+'',''+jqXHR+'',''+errorThrown, unsafe: false}]);',
'        }',
'    } );',
'}',
'function clearData(){',
'    let $grid = apex.region("IGStatic").widget().interactiveGrid("getViews", "grid");',
'    let i_ids = '''';',
'    for(let i = 0;i < $grid.getSelectedRecords().length;i++){',
'        if(i == $grid.getSelectedRecords().length-1){',
'            i_ids += $grid.model.getValue( $grid.getSelectedRecords()[i], "TYPE");',
'        }else{',
'            i_ids += $grid.model.getValue( $grid.getSelectedRecords()[i], "TYPE") + ",";',
'        }',
'    }',
'    if(i_ids.length == 0){',
'        let nullMsg;',
'        if(langCode == ''zh-cn''){',
unistr('            nullMsg = ''\8BF7\9009\62E9\8981\6E05\9664\7684\5185\5BB9.'';'),
'        }else{',
'            nullMsg = ''Please select the content to be cleared.'';',
'        }',
'        apex.message.alert(nullMsg);',
'    }else{',
'        let msgTitle,msgCancelLabel,msgConfirmLabel,msg;',
'        if(langCode == ''zh-cn''){',
unistr('            msgTitle = ''\8B66\544A!'';'),
unistr('            msgCancelLabel = ''\53D6\6D88'';'),
unistr('            msgConfirmLabel = ''\6211\786E\5B9A'';'),
unistr('            msg = "\60A8\786E\5B9A\8981\6E05\9664\6B64\8BB0\5F55\5417\FF1F";'),
'        }else{',
'            msgTitle = ''Warning!'';',
'            msgCancelLabel = ''Cancel'';',
'            msgConfirmLabel = "I''m sure";',
'            msg = "Are you sure you wish to clear this record?";',
'        }',
'        apex.message.confirm( msg, function( okPressed ) {',
'            if( okPressed ) {',
'                callClearData(i_ids);',
'            }',
'        }, {',
'            title: msgTitle,',
'            style: "danger",',
'            iconClasses: "fa fa-trash fa-2x",',
'            cancelLabel: msgCancelLabel,',
'            confirmLabel: msgConfirmLabel',
'        } );',
'',
'',
'    }',
'',
'}'))
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'21'
);
