,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ''kb_data'' as type, ',
unistr('       DECODE(UPPER(APEX_UTIL.GET_SESSION_LANG),''ZH-CN'',''\77E5\8BC6\5E93\6570\636E'',''Knowledge Base Data'') as Data_type, '),
'       ''4''  as  degree_of_importance,',
'        count(1) as COUNT',
'from kmchat_kb ',
'where APP_ID =  V(''APP_ID'')',
'union ',
'select ''prompt_data'' as type,  ',
unistr('       DECODE(UPPER(APEX_UTIL.GET_SESSION_LANG),''ZH-CN'',''\63D0\793A\8BCD\6570\636E'',''Prompt Data'') as Data_type,'),
'       ''4''  as  degree_of_importance,',
'        count(1) as COUNT',
'from KMCHAT_KB_PROMPT ',
'where APP_ID =  V(''APP_ID'')',
'UNION',
'select ''synonym_data'' as type, ',
unistr('       DECODE(UPPER(APEX_UTIL.GET_SESSION_LANG),''ZH-CN'',''\540C\4E49\8BCD\6570\636E'',''Synonym Data'') as Data_type,'),
'       ''3''  as  degree_of_importance,',
'        count(1) as COUNT',
'from KMCHAT_SYNONYM_MASTER ',
'where APP_ID =  V(''APP_ID'')',
'UNION',
'select ''user_chat_profile_data'' as type, ',
unistr('       DECODE(UPPER(APEX_UTIL.GET_SESSION_LANG),''ZH-CN'',''\7528\6237\804A\5929\914D\7F6E\6570\636E'',''User Chat Profile  Data'') as Data_type,'),
'       ''3''  as  degree_of_importance,',
'        count(1) as COUNT',
'from KMCHAT_CHAT_USER_PROFILE ',
'where APP_ID =  V(''APP_ID'')',
'UNION',
'select ''user_chat_QA_data'' as type, ',
unistr('       DECODE(UPPER(APEX_UTIL.GET_SESSION_LANG),''ZH-CN'',''\7528\6237\804A\5929Q&A\6570\636E'',''User Chat QA Data'') as Data_type,'),
'       ''1''  as  degree_of_importance,',
'        count(1) as COUNT',
'from KMCHAT_KB_QA',
'where APP_ID =  V(''APP_ID'')',
'UNION',
'select ''user_chat_feedback_data'' as type,  ',
unistr('       DECODE(UPPER(APEX_UTIL.GET_SESSION_LANG),''ZH-CN'',''\7528\6237\804A\5929\53CD\9988\6570\636E'',''User Chat Feedback Data'') as Data_type,'),
'       ''2''  as  degree_of_importance,',
'        count(1) as COUNT',
'from KMCHAT_KB_FEEDBACK ',
'where APP_ID =  V(''APP_ID'')',
'UNION',
'select ''system_config_data'' as type, ',
unistr('       DECODE(UPPER(APEX_UTIL.GET_SESSION_LANG),''ZH-CN'',''\7CFB\7EDF\914D\7F6E\6570\636E'',''System Config Data'') as Data_type,'),
'       ''5''  as  degree_of_importance,',
'        count(1) as COUNT',
'from KMCHAT_KB_DICT ',
'where APP_ID =  V(''APP_ID'')',
'UNION',
'select ''system_user_data'' as type, ',
unistr('       DECODE(UPPER(APEX_UTIL.GET_SESSION_LANG),''ZH-CN'',''\7CFB\7EDF\7528\6237\6570\636E'',''System User Data'') as Data_type,'),
'       ''5''  as  degree_of_importance,',
'        count(1) as COUNT',
'from KMCHAT_KB_USER ',
'where APP_ID =  V(''APP_ID'')',
'',
'',
''))
,p_plug_source_type=>'NATIVE_IG'
