wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(118431727239951680)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'CLEAR_KB_DATA'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    lv_types apex_t_varchar2;',
'BEGIN',
'    lv_types := apex_string.split (',
'        p_str => apex_application.g_x01,',
'        p_sep => '','' ); ',
'        ',
'    FOR i IN 1 .. lv_types.count LOOP',
'        IF lv_types(i) = ''kb_data'' THEN',
'            DELETE KMCHAT_KB WHERE APP_ID = V(''APP_ID'');',
'            DELETE KMCHAT_KB_BATCH WHERE APP_ID = V(''APP_ID'');',
'            DELETE KMCHAT_KB_FILES WHERE APP_ID = V(''APP_ID'');',
'            DELETE KMCHAT_GRAPH_CONFIG WHERE APP_ID = V(''APP_ID'');',
'        ELSIF lv_types(i) = ''prompt_data'' THEN',
'            DELETE KMCHAT_KB_PROMPT WHERE APP_ID = V(''APP_ID'');',
'        ELSIF lv_types(i) = ''synonym_data'' THEN',
'            DELETE KMCHAT_SYNONYM_MASTER WHERE APP_ID = V(''APP_ID'');',
'            DELETE KMCHAT_SYNONYM_CONF WHERE APP_ID = V(''APP_ID'');',
'            DELETE KMCHAT_SYNONYM_DETAIL WHERE APP_ID = V(''APP_ID'');',
'        ELSIF lv_types(i) = ''user_chat_profile_data'' THEN',
'            DELETE KMCHAT_CHAT_USER_PROFILE WHERE APP_ID = V(''APP_ID'');',
'        ELSIF lv_types(i) = ''user_chat_QA_data'' THEN',
'            DELETE KMCHAT_KB_RIVA WHERE APP_ID = V(''APP_ID'');',
'            DELETE KMCHAT_KB_QA WHERE APP_ID = V(''APP_ID'');',
'        ELSIF lv_types(i) = ''user_chat_feedback_data'' THEN',
'            DELETE KMCHAT_KB_FEEDBACK WHERE APP_ID = V(''APP_ID'');',
'        ELSIF lv_types(i) = ''system_config_data'' THEN',
'            DELETE KMCHAT_KB_DICT WHERE APP_ID = V(''APP_ID'');',
'        ELSIF lv_types(i) = ''system_user_data'' THEN',
'            DELETE KMCHAT_KB_USER WHERE APP_ID = V(''APP_ID'') AND UPPER(USER_NAME) <> ''ADMIN'';',
'        ELSE',
'            NULL;',
'        END IF;',
'    END LOOP;',
'    htp.p('''');',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        HTP.P(SQLERRM);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>55096310676217301
);
end;
