wwv_flow_imp_page.create_page(
 p_id=>28
,p_name=>'Synonym Standard Question Details Management'
,p_alias=>'SYNONYM-STANDARD-QUESTION-DETAILS-MANAGEMENT'
,p_page_mode=>'MODAL'
,p_step_title=>'Synonym Standard Question Details Management'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'let langCode = apex.item(P28_LANG_CODE).getValue();',
'function synonymEmbedding(){',
'    apex.message.clearErrors();',
'    let $grid = apex.region("DetailIGStatic").widget().interactiveGrid("getViews", "grid");',
'',
'    if($grid.getSelectedRecords().length == 0){',
'        if(langCode == ''zh-cn''){',
unistr('            apex.message.showErrors([{ type: "error", location: "page", message: ''\672A\9009\62E9\503C.'', unsafe: false}]);'),
'        }else{',
'            apex.message.showErrors([{ type: "error", location: "page", message: ''Unselected value.'', unsafe: false}]);',
'        }',
'        ',
'        return;',
'    }',
'',
'    if(apex.item(P28_EMBEDDING_MODEL).getValue() == "Invalid"){',
'        if(langCode == ''zh-cn''){',
unistr('            apex.message.showErrors([{ type: "error", location: "page", message: ''\5411\91CF\5316\6A21\578B\4E0D\53EF\7528.'', unsafe: false}]);'),
'        }else{',
'            apex.message.showErrors([{ type: "error", location: "page", message: ''The embedding model is not available.'', unsafe: false}]);',
'        }',
'        ',
'        return;',
'    }',
'    apex.event.trigger(''#EnableRefresh'', ''click'');',
'    for(let i = 0;i < $grid.getSelectedRecords().length;i++){',
'        kbotEmbedding($grid.model.getValue( $grid.getSelectedRecords()[i], "SYNONYM_QUESTION"), $grid.model.getValue( $grid.getSelectedRecords()[i], "ID"));',
'    }',
'    if(langCode == ''zh-cn''){',
unistr('        apex.message.showPageSuccess("\5411\91CF\5316\6210\529F!" );'),
'    }else{',
'        apex.message.showPageSuccess("Embedding Successful !" );',
'    }',
'    ',
'    apex.region("DetailIGStatic").refresh();',
'    apex.event.trigger(''#DisableRefresh'', ''click'');',
'}',
'',
'function kbotEmbedding(question,id){',
'',
'    var settings = {',
'        "url": apex.item(P28_SERVER_URL).getValue()+"/chat/text_embedding",',
'        "method": "POST",',
'        "timeout": 0,',
'        "headers": {',
'            "Content-Type": "application/json"',
'        },',
'        async:false,',
'        "data": JSON.stringify({',
'            "text": question,',
'            "embed_model": apex.item(P28_EMBEDDING_MODEL).getValue()',
'        }),',
'    };',
'    $.ajax(settings).done(function (response) {',
'        // let resp = JSON.parse(response);',
'        if(response.msg == "success"){',
'           saveDB(response.data, question, id)',
'        }else{',
'            apex.message.showErrors([{ type: "error", location: "page", message: response, unsafe: false}]);',
'        }',
'    });',
'}',
'',
'function saveDB(respVector,question, id){',
'    apex.server.process( "SAVE_RECTOR_DB", {',
'        x01: id,',
'        p_clob_01:respVector',
'    }, {',
'        dataType:''text''',
'        ,success: function( data )  {',
'            if(data.trim().length !== 0){',
'                apex.message.showErrors([{ type: "error", location: "page", message: response, unsafe: false}]);',
'            };',
'        },',
'        error: function( jqXHR, textStatus, errorThrown ) {',
'            apex.message.showErrors([{ type: "error", location: "page", message: textStatus, unsafe: false}]);',
'        }',
'    } );',
'}'))
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'$("#DetailIGStatic_ig_toolbar_QueSelect").addClass(''t-Button--success t-Button--simple t-Button--iconRight t-Button--hoverIconPush t-Button--stretch  t-Button--hot'');',
'// #P28_EMBEDDING_MODEL_CONTAINER .t-Form-itemWrapper{',
'//         background: #e5e5e5;',
'// }',
'$("#P28_EMBEDDING_MODEL_LABEL").css({"color":"white"});',
'$("#P28_EMBEDDING_MODEL_CONTAINER .t-Form-itemWrapper .apex-item-icon").css({"color":"white"});',
'',
'if(apex.item(P28_EMBEDDING_MODEL).getValue() == ''Invalid''){',
'    $("#P28_EMBEDDING_MODEL_CONTAINER .t-Form-itemWrapper").css({"background":"rgb(211,74,74)","color":"white","border-radius":"5px"});',
'}else{',
'    $("#P28_EMBEDDING_MODEL_CONTAINER .t-Form-itemWrapper").css({"background":"#508223","color":"white","border-radius":"5px"});',
'}',
'',
'if(langCode == ''zh-cn''){',
unistr('    $("#DetailIGStatic_ig_toolbar_QueSelect").find(''.a-Button-label'').text(''\5411\91CF\5316'');'),
'}',
''))
,p_page_template_options=>'#DEFAULT#:ui-dialog--stretch'
,p_page_component_map=>'21'
