,p_region_id=>wwv_flow_imp.id(96223833333884733)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'modified status'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'     case :APEX$ROW_STATUS',
'     when ''C'' then',
'         NULL;',
'     when ''U'' then',
'         update KMCHAT_SYNONYM_DETAIL',
'         set    IS_EMBEDDING =''N'',',
'                SYNONYM_VECTOR = NULL',
'         WHERE  ID = :ID;',
'     when ''D'' then',
'         NULL;',
'     end case;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
