,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SAVE_RECTOR_DB'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'--',
'    UPDATE KMCHAT_SYNONYM_DETAIL',
'    SET    SYNONYM_VECTOR = TO_VECTOR(apex_application.g_clob_01),',
'           IS_EMBEDDING   = ''Y''',
'    WHERE  ID  = apex_application.g_x01;',
'--',
'    COMMIT;',
'    htp.p('''');',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        HTP.P(SQLERRM);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>32857264487696539
);
