wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(232461605317903461)
,p_name=>'KM AI Chatbot'
,p_region_name=>'KMCHATBOT'
,p_template=>wwv_flow_imp.id(106480523158103557)
,p_display_sequence=>40
,p_region_css_classes=>'t-Chat'
,p_icon_css_classes=>'fa-comments-o'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#:t-Comments--chat'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select * from (select r.id, case when audio is not null ',
'    then to_clob(''<audio title="''||',
'    JSON_VALUE(r.RIVA_RESP, ''$.text'')',
'    ||''" controls controlslist="nofullscreen nodownload noplaybackrate noremoteplayback" disablePictureInPicture="true" oncontextmenu="return false" class="my-audio" src="''||',
'    apex_util.get_blob_file_src(''P3_AUDIO'',id)',
'    ||''" type="''||r.MIME_TYPE||''"> </audio>'') else r.TEXT_DISP end COMMENT_TEXT, ',
'case when r.appuser = ''chatbot'' then ''chatbot fa fa-commenting-o'' else ''appuser fa fa-user'' end ICON_MODIFIER,',
'case when r.appuser = ''chatbot'' then ''chatbot-comment'' else ''appuser-comment''|| case when r.audio is not null then '' appuser-audio'' end end KM_COMMENT,',
'null ATTRIBUTE_1, ',
'null ATTRIBUTE_2, ',
'null ATTRIBUTE_3, ',
'null ATTRIBUTE_4, ',
'case APPUSER',
'when ''chatbot'' then NULL',
'else ''t-Chat--own''',
'end comment_modifiers,',
'case when r.audio is not null then ''<div>''||r.TEXT_DISP||''</div>'' end USER_NAME, ',
'to_char(CREATED_TIME, ''YYYY-MM-DD HH24:MI:SS'') COMMENT_DATE, ',
unistr('case when r.appuser = ''chatbot'' then case when feedback is not null then case lower(r.feedback) when ''good'' then ''<span class="feedback-readonly">\D83D\DC4D</span>'' when ''bad'' then ''<span class="feedback-readonly">\D83D\DC4E</span>'' end else  ''<span id="''||r.id||''" cl')
||'ass="feedback"><span aria-hidden="true" class="fa fb-good fa-thumbs-up fa-lg"></span><span aria-hidden="true" class="fa fb-bad fa-thumbs-down fa-lg"></span></span>'' end end ACTIONS,',
'case when r.file_name is not null and r.TEXT_JSON  is null then ''N'' else ''Y'' end showYN',
'from KMCHAT_KB_RIVA r connect by prior r.id=r.parent_id',
'start with upper(r.appuser) = :APP_USER',
'and  app_id = V(''APP_ID'')',
'and  chat_type = ''Light RAG''',
'order by r.id asc) t ',
'where t.showYN = ''Y''',
'union all',
'select -1 id, to_clob(''<div class="is-typing"><div class="jump32"></div><div class="jump2"></div><div class="jump3"></div></div>'') COMMENT_TEXT, ''chatbot fa fa-commenting-o'' ICON_MODIFIER,''chatbot'' KM_COMMENT,',
''''' ATTRIBUTE_1, null ATTRIBUTE_2, null ATTRIBUTE_3, null ATTRIBUTE_4, null comment_modifiers, null USER_NAME, ',
'to_char(CURRENT_DATE, ''YYYY-MM-DD HH24:MI:SS'') COMMENT_DATE, null ACTIONS, ''Y'' showYN from dual where :P32_PENDING_ICON = 1;',
'',
'',
''))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P32_INPUT,P32_PENDING_ICON'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(106908118189229824)
