'DECLARE',
'    lv_sql VARCHAR2(32766);',
'    lv_available_view_prompt VARCHAR2(4000);',
'BEGIN',
'    lv_sql := ''SELECT pt_name d, pt_name r FROM kmchat_kb_prompt WHERE pt_status = ''''Y'''' AND app_id =V(''''APP_ID'''')'';',
'    IF apex_authorization.is_authorized (p_authorization_name => ''ADMIN'' ) = TRUE OR apex_app_setting.get_value(p_name => ''ACCESS_CONTROL_SCOPE'') = ''ALL_USERS'' THEN',
'        RETURN lv_sql;',
'    ELSE',
'        BEGIN',
'            SELECT available_view_prompt INTO lv_available_view_prompt FROM kmchat_kb_user WHERE UPPER(user_name) = V(''APP_USER'') AND app_id = V(''APP_ID'');',
'            lv_available_view_prompt := ''''''''||REPLACE(lv_available_view_prompt, '','' ,'''''','''''')||'''''''';',
'        EXCEPTION  ',
'            WHEN OTHERS THEN',
'                lv_available_view_prompt := NULL;',
'        END;',
'        ',
'        IF lv_available_view_prompt IS NOT NULL THEN',
'            lv_sql := lv_sql ||'' AND (pt_name IN(''||lv_available_view_prompt||'')'';',
'            RETURN lv_sql ||''    OR UPPER(create_by) = V(''''APP_USER''''))'';',
'        END IF;',
'        ',
'        RETURN lv_sql ||'' AND UPPER(create_by) = V(''''APP_USER'''')''; ',
'        ',
'    END IF;',
'END;',
''))
