wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(143358475539965652)
,p_process_sequence=>10
,p_process_point=>'AFTER_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Light init'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    lv_server    VARCHAR2(400);',
'    lV_input     VARCHAR2(32766);',
'    lc_clob      CLOB;',
'    j            apex_json.t_values;',
'    ln_code      NUMBER;',
'BEGIN',
'    :P32_MSG := null;',
'    -- get server',
'    SELECT S_URL INTO lv_server FROM KMCHAT_KB_SERVER WHERE S_NAME = ''SERVER'' AND APP_ID = V(''APP_ID'');',
'    lv_input := ''{',
'        "knowledge_base_name": "''||:P32_KNOWLEDGE_BASE_NAME||''",',
'        "stub": "no need to input"',
'    }'';',
'    apex_web_service.g_request_headers(1).name :=  ''Content-Type'';',
'    apex_web_service.g_request_headers(1).value := ''application/json'';',
'        ',
'    lc_clob := apex_web_service.make_rest_request(',
'        p_url => lv_server||''/lightrag/lightrag_init'',',
'        p_http_method => ''POST'',',
'        p_body => lv_input',
'    );',
'        ',
'    apex_json.parse(j, lc_clob);',
'    apex_debug.warn(lc_clob);',
'    apex_debug.warn(apex_json.get_varchar2(p_path=>''code'',p_values=>j));',
'    IF apex_json.get_varchar2(p_path=>''code'',p_values=>j) = 200 THEN',
'        :P32_MSG := apex_json.get_varchar2(p_path=>''msg'',p_values=>j);',
'    ELSE',
'        :P32_MSG := NULL;',
'        -- apex_application.show_error_message(lc_clob);',
'    END IF;',
'exception',
'    when others then',
'        null;',
'        -- apex_application.show_error_message(sqlerrm);',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'init'
,p_process_when_type=>'REQUEST_EQUALS_CONDITION'
,p_internal_uid=>80023058976231273
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(143357227077965645)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Clean History'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_clob 	        CLOB;',
'    l_server        VARCHAR2(4000);',
'BEGIN',
'',
'    delete from kmchat_kb_riva where id in (',
'    select r.id',
'    from KMCHAT_kb_RIVA r connect by prior r.id=r.parent_id',
'    start with upper(r.appuser) = :APP_USER and r.app_id = V(''APP_ID'') and r.chat_type = ''Light RAG''',
'    );',
'    commit;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(143352327678965632)
,p_internal_uid=>80021810514231266
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(143357618346965645)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'saveAudio'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_id number;',
'    l_clob  clob;',
'',
'    l_json clob;',
'    lb_blob blob;',
'    l_body clob;',
'    lv_filename KMCHAT_kb_RIVA.FILE_NAME%type := to_char(current_date, ''YYYYMMDDHH24MISS'')||''.wav'';',
'    lm_multipart apex_web_service.t_multipart_parts;',
'    l_rivaURL KMCHAT_KB_RIVA.RIVA_URL%type;',
'    j            apex_json.t_values;',
'    l_disp      KMCHAT_KB_RIVA.TEXT_DISP%type;',
'begin',
unistr('    -- htp.p('' f01\4E2A\6570: ''|| apex_application.g_f01.count() );'),
'    for i in 1 .. apex_application.g_f01.count() loop',
'        l_clob := l_clob || apex_application.g_f01(i) ;',
'    end loop;',
'',
'    l_rivaURL := :P32_RIVA_URL;--''http://152.69.226.154:8088/ords/xh/test/riva'';--''https://riva.oracle.k8scloud.site:8899/v1/audio/transcriptions'';',
'  ',
'    l_id := KMCHAT_KB_RIVA_SEQ.nextval;',
'    lb_blob := apex_web_service.clobbase642blob(l_clob);',
'    insert into kmchat_kb_riva(id, AUDIO, MIME_TYPE, FILE_NAME, APPUSER, RIVA_URL, APP_ID, CHAT_TYPE) ',
'        values(l_id, lb_blob, ''audio/wav'', lv_filename, :APP_USER, l_rivaURL ,V(''APP_ID''), ''Light RAG'');',
'    commit;',
'',
'    apex_web_service.APPEND_TO_MULTIPART (',
'        p_multipart => lm_multipart,',
'        p_name => ''file'',',
'        p_filename => lv_filename,',
'        p_content_type => ''multipart/form-data'',',
'        p_body_blob => lb_blob',
'    );',
'',
'    apex_web_service.set_request_headers(''lang_code'',:P32_AUDIO_LANG);',
'',
'    l_clob := apex_web_service.make_rest_request(',
'        p_url => l_rivaURL,',
'        p_http_method => ''POST'',',
'        p_body_blob => apex_web_service.generate_request_body(lm_multipart)',
'        -- p_wallet_path => ''file:///tmp/https_wallet''',
'        );',
'    update kmchat_kb_riva set RIVA_RESP = l_clob where id = l_id;',
'    commit;',
'',
'    apex_json.parse(j, l_clob);',
'    l_disp := apex_json.get_clob (p_values => j, p_path => ''text'');',
'',
'    update kmchat_kb_riva set TEXT_DISP = l_disp where id = l_id;',
'    commit;',
'',
'    -- l_id := KMCHAT_PKG.LLM_REST(:P32_URL, :P32_MODEL, l_disp, l_id);',
'',
'    :P32_CHAT_ID := l_id;',
'',
'    htp.p(''{"id": '' || l_id ||'', "text_disp": "''||l_disp||''"}'');',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_when_button_id=>wwv_flow_imp.id(143347864532965628)
,p_internal_uid=>80022201783231266
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(143358079358965652)
,p_process_sequence=>30
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'saveFeedback'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE ',
'    l_id             NUMBER;',
'    ln_p_id          NUMBER;',
'    lc_answer        CLOB;',
'    lv_ques          VARCHAR2(4000);',
'    lc_JSON          CLOB;',
'    j                apex_json.t_values;',
'    lv_kb_name       VARCHAR2(4000);',
'    lv_model         VARCHAR2(4000);',
'    lv_prompt_name   VARCHAR2(4000);',
'    lj_more_param    VARCHAR2(4000);',
'    lv_chat_catagory VARCHAR2(4000) := NULL;',
'    lc_answer_json   CLOB;',
'    lv_server        VARCHAR2(400);',
'    l_clob           CLOB;',
'    l_vector         VECTOR;',
'    lv_txt_embedding_status VARCHAR2(4000);',
'    lv_search_type   VARCHAR2(400);',
'BEGIN',
'--',
'    SELECT A.text_disp,A.text_JSON,B.text_disp,B.text_json',
'    INTO   lv_ques,lc_JSON,lc_answer,lc_answer_json',
'    FROM   kmchat_kb_riva A,',
'           kmchat_kb_riva B ',
'    WHERE  A.ID = B.parent_id ',
'    AND    B.ID = apex_application.g_x01;',
'--',
'    apex_json.parse(j,lc_JSON);',
'    lv_kb_name := apex_json.get_varchar2(p_path=>''knowledge_base_name'',p_values=>j);',
'    lv_model :=  apex_json.get_varchar2(p_path=>''model_name'',p_values=>j);',
'    lv_prompt_name := apex_json.get_varchar2(p_path=>''prompt_name'',p_values=>j);',
'    ',
'',
'    lj_more_param := null;',
'    ',
'    KMCHAT_KB_BASE_PKG.txt_embedding(',
'        iv_kb_name     => lv_kb_name,',
'        iv_text        => lv_ques,',
'        ov_text_vector => l_vector,',
'        ov_status      => lv_txt_embedding_status);',
'',
'    IF lv_txt_embedding_status = ''success'' THEN',
'--',
'        UPDATE kmchat_kb_riva',
'        SET    feedback = apex_application.g_x02 ',
'        WHERE  id = apex_application.g_x01',
'        AND    feedback is null;',
'--',
'        INSERT INTO kmchat_kb_feedback(kb_name, llm_model, chat_catagory, prompt_name, more_param, feedback, feedback_reason, question, question_vector, answer_disp, answer_json, chat_type, app_user, create_date, app_id) ',
'        VALUES(',
'            lv_kb_name,',
'            lv_model,',
'            lv_chat_catagory,',
'            lv_prompt_name,',
'            lj_more_param,',
'            apex_application.g_x02,',
'            apex_application.g_x03,',
'            lv_ques,',
'            to_vector(l_vector),',
'            lc_answer,',
'            lc_answer_json,',
'            ''Light RAG'',',
'            V(''APP_USER''),',
'            current_date,',
'            V(''APP_ID'')',
'        );',
'        COMMIT;',
'--',
'        htp.p(''1'');',
'    ELSE',
unistr('        -- kbot\5411\91CF\5316\9519\8BEF'),
'        htp.p(''0''); ',
'    END IF;',
'--',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        rollback;',
'        htp.p(''0:'');  ',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>80022662795231273
);
wwv_flow_imp_page.create_page_process(
