'        RERANKER_MODEL,',
'        RERANKER_TOPK,',
'        SCORE_THRESHOLD,',
'        HISTORY_K',
'    )',
'    VALUES',
'    (   :P32_PROFILE_NAME,',
'        :P32_PROFILE_DESCRIPTION,',
'        V(''APP_USER''),',
'        current_date,',
'        V(''APP_ID''),',
'        :P32_MODEL,',
'        :P32_CHAT_CATAGORY,',
'        :P32_PROMPT_NAME,',
