wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(143394493776972321)
,p_process_sequence=>10
,p_process_point=>'AFTER_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET VALUE'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    select  ID,',
'            LLM_Endpoint,',
'            LLM_Model,',
'            LLM_API_Key,',
'            Embedding_Endpoint,',
'            Embedding_Model,',
'            Embedding_API_Key,',
'            yaml_file_content,',
'            prompt_file_name,',
'            prompt_file_content,',
'            claim',
'    INTO   :P33_ID,',
'           :P33_LLM_ENDPOINT,',
'           :P33_LLM_MODEL,',
'           :P33_LLM_API_KEY,',
'           :P33_EMBEDDING_ENDPOINT,',
'           :P33_EMBEDDING_MODEL,',
'           :P33_EMBEDDING_API_KEY,',
'           :P33_YAML_FILE,',
'           :P33_PROMPT_FILE_NAME,',
'           :P33_PROMPT_FILE,',
'           :P33_CLAIM',
'    from    kmchat_graph_config',
'    where  kb_name = :P33_KB_NAME',
'    and    rag_type = ''Light RAG''',
'    and    app_id = V(''APP_ID'');',
'exception',
'    when others then',
'        :P33_ID := NULL;',
'        :P33_LLM_ENDPOINT := NULL;',
'        :P33_LLM_MODEL := NULL;',
'        :P33_LLM_API_KEY := NULL;',
'        :P33_EMBEDDING_ENDPOINT := NULL;',
'        :P33_EMBEDDING_MODEL := NULL;',
'        :P33_EMBEDDING_API_KEY:= NULL;',
'        :P33_YAML_FILE:= NULL;',
'        :P33_PROMPT_FILE := NULL;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>80059077213237942
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(143394899718972321)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SET_PROMPT'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    ln_id   NUMBER;',
'BEGIN',
'    IF :P33_ID IS NULL THEN',
'        insert into kmchat_graph_config',
'        (KB_NAME,prompt_file_name,prompt_file_content,app_user,create_date,app_id,rag_type)',
'        values(',
'            :P33_KB_NAME,',
'            :P33_PROMPT_FILE_NAME,',
'            :P33_PROMPT_FILE,',
'            V(''APP_USER''),',
'            current_date,',
'            V(''APP_ID''),',
'            ''Light RAG''',
'        )RETURNING ID INTO ln_id;',
'',
'        apex_json.open_object;',
'        apex_json.write(''code'', 200); ',
'        apex_json.write(''msg'', ''insert'');',
'        apex_json.write(''id'', ln_id);',
'        apex_json.close_object;',
'',
'    ELSE',
'        UPDATE kmchat_graph_config',
'        SET    prompt_file_content = :P33_PROMPT_FILE,',
'               prompt_file_name    = :P33_PROMPT_FILE_NAME',
'        WHERE ID = :P33_ID and KB_NAME = :P33_KB_NAME and rag_type = ''Light RAG'';',
'',
'        apex_json.open_object;',
'        apex_json.write(''code'', 200); ',
'        apex_json.write(''msg'', ''update'');',
'        apex_json.close_object;',
'    END IF;',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        apex_json.open_object;',
'        apex_json.write(''code'', SQLCODE); ',
'        apex_json.write(''msg'', SQLERRM);',
'        apex_json.close_object;   ',
'END;'))
