wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(142152910049223180)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PUBLISH_RECORD_KBOT'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_kb_name varchar2(200);',
'  l_question varchar2(4000);',
'  l_filename varchar2(200);',
'  l_filepage number;',
'  l_answer   clob;',
'  l_document clob;',
'  raw_uuid   RAW(16);',
'  doc_uuid   VARCHAR2(256 BYTE);',
'  --v_json_metadata JSON_OBJECT_T;',
'  v_json_string VARCHAR2(4000);',
'  l_vector vector;',
'  l_embedding_status VARCHAR2(4000);',
'  l_cnt       NUMBER;',
'begin',
'    select EID,KB_NAME,QUESTION,ANSWER,FILE_NAME,FILE_PAGE_NUMBER',
'    into doc_uuid,l_kb_name,l_question,l_answer,l_filename, l_filepage',
'    from KMCHAT_KB_QA_OPTIMIZATION',
'    where id = apex_application.g_x01;',
'    ',
'    select count(1)',
'    into   l_cnt',
'    FROM   KMCHAT_KB',
'    WHERE  KNOWLEDGE_BASE_NAME = l_kb_name',
'    AND    APP_ID   = :APP_ID;',
'',
'    IF l_cnt > 0 THEN',
'        l_question := REGEXP_REPLACE(REPLACE(REPLACE(l_question, CHR(10), '' ''), CHR(13), '' ''), '' {2,}'', '' '');',
'        l_answer := REGEXP_REPLACE(REPLACE(REPLACE(l_answer, CHR(10), '' ''), CHR(13), '' ''), '' {2,}'', '' '');',
'',
'        l_document := ''Question: ''|| l_question || '' '' || ''Answer: ''|| l_answer;',
'        v_json_string := ''{ "source": "'' || l_filename || ''", "source_type": "QA_RESULT_OPTIMIZE", "page_number": '' || l_filepage || ''}'';',
'',
'        KMCHAT_KB_BASE_PKG.txt_embedding(',
'            iv_kb_name     => l_kb_name,',
'            iv_text        => l_document,',
'            ov_text_vector => l_vector,',
'            ov_status      => l_embedding_status);',
'',
'        IF l_embedding_status = ''success'' THEN',
'            if doc_uuid is null then',
'                raw_uuid := SYS_GUID();',
'                doc_uuid := LOWER(RTRIM(REGEXP_REPLACE(RAWTOHEX(raw_uuid),''([A-F0-9]{8})([A-F0-9]{4})([A-F0-9]{4})([A-F0-9]{4})([A-F0-9]{12})'',''\1-\2-\3-\4-\5''),'' ''));',
'               ',
'                insert into KMCHAT_KBOT_ORACLE_EMBEDDINGS(id,COLLECTION_NAME,EMBEDDING,DOCUMENT,METADATA,CHUNK_CATEGORY)',
'                values(doc_uuid,l_kb_name,to_vector(l_vector),l_document,v_json_string,''SOURCE_DOCS'');',
'               ',
'                Update KMCHAT_KB_QA_OPTIMIZATION',
'                  set EID = doc_uuid,',
'                      PUBLISH_STATUS = ''Y''',
'                where id=apex_application.g_x01;',
'',
'                commit;',
'',
'            else',
'                update KMCHAT_KBOT_ORACLE_EMBEDDINGS',
'                  set EMBEDDING = to_vector(l_vector),',
'                      DOCUMENT = l_document, ',
'                      METADATA = v_json_string',
'                where id = doc_uuid;',
'',
'                Update KMCHAT_KB_QA_OPTIMIZATION',
'                  set PUBLISH_STATUS = ''Y''',
'                where id=apex_application.g_x01;',
'',
'                commit;',
'',
'            end if;',
'',
'            htp.p(1);',
'        ELSE',
unistr('            -- kbot\5411\91CF\5316\9519\8BEF'),
'            htp.p(''The vectorization of the answer to the question failed.'');',
'        END IF;',
'    ELSE',
unistr('        htp.p(''The knowledge base does \3010''|| l_kb_name ||''\3011 not exist, please delete the data in a timely manner.'');'),
'    END IF;',
'EXCEPTION',
'  WHEN OTHERS THEN',
'    rollback;',
'    htp.p(SQLERRM);',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>78817493485488801
);
end;
