prompt --application/pages/page_00037
begin
wwv_flow_imp_page.create_page(
 p_id=>37
,p_name=>'chat home'
,p_alias=>'CHAT-HOME'
,p_step_title=>'chat home'
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'let s_url = apex.item(P37_SERVER_URL).getValue();',
'let langCode = apex.item(P37_LANG_CODE).getValue();',
'let chatId ,$thumb, $bubble= '''';',
'',
'// show noneLLM Download',
'function show_noneLLM_download(response){',
'    let downloadDom ='''';',
'    response.data.forEach((item, index) => {',
'        if(index == 0){',
unistr('            downloadDom = `<br/>&gt;&gt; ${langCode == ''zh-cn''?''\53C2\8003\8D44\6E90'':''Reference Resources''}: <span class="refFileSpan" >[<a  class="refFileA" href="${item.source}" target="_blank"> ${langCode == ''zh-cn''?''\4E0B\8F7D'':''Download''} </a>]  </span>`; '),
'            return;',
'        }',
'    });',
'    return downloadDom;',
'}',
'',
'//get llm model',
'function get_model(){',
'    apex.message.clearErrors();',
'    axios.get(`${s_url}/chat/list_LLMs`, {',
'        timeout: 5000',
'        },{',
'            headers: {',
'            ''accept'': ''application/json''',
'        }',
'    })',
'    .then(response => {',
'        var select = apex.item(P37_MODEL).node;',
'        response.data.data.sort();',
'        response.data.data.forEach((item, index) => {',
'            if(index == 0){',
'                select.options.length = 0; ',
'            }',
'            var newOption = new Option(item, item);',
'',
'            select.add(newOption);',
'        });',
'        if(apex.item(P37_PROFILE_TEMP_MODEL).getValue()){',
'            apex.item(P37_MODEL).setValue(apex.item(P37_PROFILE_TEMP_MODEL).getValue(), apex.item(P37_PROFILE_TEMP_MODEL).getValue(), false);',
'        }else{',
'            apex.item(P37_MODEL).setValue(select.options[0].value, select.options[0].value, false);',
'        }',
'    })',
'    .catch(error => {',
'    if (error.code === ''ECONNABORTED'') {',
'        apex.message.showErrors([{ type: "error", location: "page", message: ''Get LLM timeout.'', unsafe: false}]);',
'    } else {',
'        apex.message.showErrors([{ type: "error", location: "page", message: "Other error:"+error.message + ".", unsafe: false}]);',
'    }',
'    });',
'}',
'',
'//Rag page switching',
'function redirect_page(pageid, kbname, resValue){',
'    apex.server.process(''GET_RAG_URL'',{',
'            x01: pageid,',
'            x02:kbname,',
'            x03:resValue',
'        },',
'        {',
'            dataType: "text",',
'            success: function (pData) {           ',
'                apex.navigation.redirect(pData);',
'            }             ',
'        }',
'    )',
'}',
'',
'function showMore(o, id) {',
'    let divID = "div#" + id;',
'    if ($(divID).is(":hidden")) {',
'        $(divID).show(100);',
'        if(langCode == ''zh-cn''){',
unistr('            $(o).html(''>> \9690\85CF'');'),
'        }else{',
'            $(o).html(''>> Show Less'');',
'        }',
'    } else {',
'        $(divID).hide(100);',
'        if(langCode == ''zh-cn''){',
unistr('            $(o).html(''>> \663E\793A\66F4\591A'');'),
'        }else{',
'            $(o).html(''>> Show More'');',
'        }',
'    }',
'}',
'',
'// save chat profile',
'function saveProfile(){',
unistr('    let cMsg = langCode == ''zh-cn''?''\53C2\6570\5305\542B\7279\6B8A\5B57\7B26'':''Parameters contain special characters'';'),
'    apex.message.clearErrors();',
'    if(jsCheck(''P37_PROFILE_NAME'', apex.item(P37_PROFILE_NAME).getValue(), cMsg)||jsCheck(''P37_PROFILE_DESCRIPTION'', apex.item(P37_PROFILE_DESCRIPTION).getValue(), cMsg)){',
'        return true;',
'    };',
'    if(apex.item(P37_PROFILE_NAME).getValue().length == 0){',
'        if(langCode == ''zh-cn''){',
unistr('            apex.message.showErrors([{ type: "error", location: [ "page", "inline" ], pageItem: "P37_PROFILE_NAME", message: ''\3010\914D\7F6E\540D\79F0\3011\4E0D\80FD\4E3A\7A7A.'', unsafe: false}]);'),
'        }else{',
unistr('            apex.message.showErrors([{ type: "error", location: [ "page", "inline" ], pageItem: "P37_PROFILE_NAME", message: ''\3010Profile Name\3011 cannot be empty.'', unsafe: false}]);'),
'        }    ',
'        return;',
'        ',
'    }',
'    apex.server.process( "SAVE_PROFILE", {',
'        pageItems: ["P37_PROFILE_NAME","P37_PROFILE_DESCRIPTION","P37_MODEL","P37_CHAT_CATEGORY","P37_PROMPT_NAME","P37_QUERYSIMILARITY_FLAG","P37_SEARCH_TYPE","P37_VECTOR_STORE_LIMIT","P37_RERANKER_MODEL","P37_RERANKER_TOPK","P37_SCORE_THRESHOLD","P'
||'37_HISTORY_K","P37_SUMMARY"]',
'    }, {',
'        dataType:''text''',
'        ,success: function( data )  {',
'            if(data.trim().length == 0){',
'                if(langCode == ''zh-cn''){',
unistr('                    apex.message.showPageSuccess( ''\804A\5929\914D\7F6E\6587\4EF6\5DF2\6210\529F\4FDD\5B58.'');'),
'                }else{',
'                    apex.message.showPageSuccess( ''Chat profile saved successfully.'' );',
'                }',
'                apex.item(P37_PROFILE).refresh();',
'                $("#SaveProfilesStatic").dialog("close");',
'            }else{',
'                apex.message.showErrors([{ type: "error", location: "page", message: data, unsafe: false}]);',
'            }',
'        },',
'        error: function( jqXHR, textStatus, errorThrown ) {',
'            // handle error',
'            apex.message.showErrors([{ type: "error", location: "page", message: textStatus, unsafe: false}]);',
'        }',
'    } );',
'}',
'',
unistr('// save fb(good\3001bad\3001cancel)'),
'function saveFeedback(chatId, type, reason, thisDom, thisPDom) {',
'    apex.message.clearErrors();',
'    apex.server.process(',
'        ''SAVE_FEEDBACK'', {',
'        x01: chatId,',
'        x02: type,',
'        x03: reason',
'    },',
'    {',
'        dataType:''text'',',
'        success: function (pData) {',
'            if(pData == 0){',
'                // error',
'                apex.message.showErrors([{ type: "error", location: "page", message: ''feedback error'', unsafe: false}]);',
'            }else if(pData == 1){',
'                // selected feedback',
'                thisPDom.find(''.thumb'').removeClass(''selected'');',
'                thisDom.addClass(''selected'');',
'            }else if(pData == 2){',
'                // bad cancel',
'                thisPDom.find(''.thumb'').removeClass(''selected'');',
'            }else{',
'                // good cancel',
'                $("#chat-area").empty();',
'                initChat();',
'                ',
'            }',
'            ',
'      },',
'        error: function (jqXHR, textStatus, errorThrown) {',
'            console.error("error", textStatus);',
'            apex.message.showErrors([{ type: "error", location: "page", message: textStatus, unsafe: false}]);',
'      }',
'    }',
'  );',
'}',
'',
'',
'',
'// Scroll to the bottom of the page',
'function scrollChatToBottom() {',
'    var $chatArea = $("#chat-area");',
'    $chatArea.scrollTop($chatArea[0].scrollHeight);',
'}',
'',
'//page init',
'function initChat() {',
'    apex.message.clearErrors();',
'    apex.server.process("LOAD_HISTORY", {',
'        x01: apex.item(P37_KNOWLEDGE_BASE_NAME).getValue()',
'    }, {',
'        dataType:''text'',',
'        success: function(pData) {',
'            let str = JSON.parse(pData);',
'            var $chatArea = $("#chat-area");',
'            //Welcome message',
