'',
'// Send message button click event',
'let isSending = false;',
'function sendMsg() {',
'    ',
'    if (isSending) return;',
'',
'    const userText = $(''#user-input'').val().trim();',
'    if (!userText) return;',
'    $(''#user-input'').val('''');',
'    if (userText === '''') return;',
'',
'    isSending = true;',
'',
'    var $chatArea = $("#chat-area");',
'    ',
'    // Display AI is thinking',
'    let $loadingBubble = $(',
'    `<div class="chat-bubble bot loading-bubble">',
unistr('        <div class="avatar">\D83E\DD16</div>'),
'        <div class="content">',
'            <div class="message"><span class="dot-typing"></span><span class="dot-typing"></span></div>',
'        </div>',
'    </div>`',
