||'TEGORY"]',
'    }, {',
'        success: function(pData) {',
'            let botText, response_json = '''';',
'            let response_status = ''success'';',
'            if(pData.bot_response){',
'                response_json = JSON.parse(pData.bot_response);',
'                if(response_json.status == ''success''){',
'                    //Normal kbot output',
'                    botText = pData.response||"";',
'                }else{',
'                    //Retrieve kbot error information',
'                    botText = response_json.err_msg;',
'                    response_status = ''faild'';',
'                }',
'            }else{',
'                //Retrieve PLSQL error information',
'                botText = pData.response||"";',
'                response_status = ''faild'';',
'            }',
