'',
'            let $botDiv = $(',
'                `<div class="chat-bubble bot" data-chat-id=" ${pData.chat_id} ">',
unistr('                    <div class="avatar">\D83E\DD16</div>'),
'                    <div class="content">',
'                        <div class="message"><span class="bot-stream"></span></div>',
'                        <div class="meta-row">',
'                            <div class="timestamp"> ${pData.ai_created_time} </div>',
'                            <div class="feedback">',
'                                <span class="thumb thumb-up ${likeSelected} "><span class="fa fa-thumbs-up" aria-hidden="true"></span></span>',
'                                <span class="thumb thumb-down ${dislikeSelected} "><span aria-hidden="true" class="fa fa-thumbs-down"></span></span>',
'                            </div>',
'                        </div>',
'                    </div>',
'                </div>`',
'            );',
'',
'            $chatArea.append($botDiv);',
'            let $streamSpan = $botDiv.find(''.bot-stream'');',
'',
'            let i = 0;',
'            function typeWriter() {',
'                if (i < botText.length) {',
'                    if (botText.substring(i, i + 5) === ''<br/>'') {',
'                        $streamSpan.append(''<br/>'');',
'                        i += 5; // skip </br>',
'                    } else {',
'                        $streamSpan.append(botText.charAt(i));',
'                        i++;',
'                    }',
'                    scrollChatToBottom();',
'                    setTimeout(typeWriter, 10);',
'                } else {',
'                    if(llmVal !== ''NoneLLM''){',
'                        let aiResponseDom = init_kbot_code_generation(pData.chat_id, response_json, pData.response, ''response'');',
