unistr('            let errorMsg = langCode == ''zh-cn''?''<div><strong>\7CFB\7EDF\9519\8BEF\FF1A</strong> \51FA\73B0\9519\8BEF\FF0C\8BF7\7A0D\540E\91CD\8BD5.</div>'':''<div><strong>System error\FF1A</strong> An error occurred, please try again later.</div>'';'),
