'',
'// kbot response error',
'function kbot_response_error(value){',
unistr('    let errorMsg = langCode == ''zh-cn''?`<strong>\7CFB\7EDF\9519\8BEF\FF1A</strong><span style="color:#870505">"${value}"</span>`:`<strong>System error\FF1A</strong><span style="color:#870505">"${value}"</span>`;'),
'    return errorMsg;',
'',
'}',
'// kbot respone success',
'function init_kbot_code_generation(chat_id,valueJson,valueText,type){',
'    let aiResponseDom = '''';',
'    valueJson.data.forEach((item, index) => {',
'        if(index == 0){',
'             // answer',
'            if(type == ''init''){',
'                aiResponseDom = aiResponseDom + valueText;',
'            }',
'        }else{',
'            // answer ref',
'            if(index == 1){',
unistr('                aiResponseDom = `${aiResponseDom} <div class="showMoreClass"><a class="moreLink" id="a_${chat_id}" onclick="showMore(this, ${chat_id});return false;" href="#">>> ${langCode == ''zh-cn''?''\663E\793A\66F4\591A'':''Show more''}</a><div class="moreDiv" style=')
||'"display:none;" id="${chat_id}"><ul>`;',
'            }',
'            aiResponseDom = `${aiResponseDom} <li class="super"> ${item.content}`;',
'            // answer ref url and page num',
'            if(item.source){',
unistr('                aiResponseDom = `${aiResponseDom} <br/><span class="refFileSpan" >[<a  class="refFileA" href="${item.source}" target="_blank"> ${langCode == ''zh-cn''?''\4E0B\8F7D'':''Download''} </a>]  | </span>`;'),
unistr('                aiResponseDom = `${aiResponseDom} <span class="refFileSpan" >[<a  class="refFileA"  onclick="viewSource(''${item.viewer_source}'')" target="_blank"> ${langCode == ''zh-cn''?''\67E5\770B\6E90\6587\4EF6'':''View source''} - ${langCode == ''zh-cn''?''\9875\7801'':''PageNum''}:${')
||'item.page_num} ]</span></a></span>`;',
'            }',
'            aiResponseDom = `${aiResponseDom}</li>`;',
'            if(valueJson.data.length - 1 == index){',
'                aiResponseDom = `${aiResponseDom}</ul></div></div>`;',
'            }',
'        }',
'    });',
'    return aiResponseDom;',
'}',
'',
'function viewSource(url){',
'    // console.log(1231);',
'    apex.server.process("GET_VIEW_SOURCE_URL", {',
'        x01: url',
'    }, {',
'         dataType: "text",',
'        success: function(pData) {',
'           apex.navigation.redirect(pData);',
'        }',
'    });',
'}',
'',
'//Get local time',
'function getLocalTime() {',
'    const now = new Date();',
'',
'    const year = now.getFullYear();',
'    const month = String(now.getMonth() + 1).padStart(2, ''0'');',
'    const day = String(now.getDate()).padStart(2, ''0'');',
'    ',
'    const hours = String(now.getHours()).padStart(2, ''0'');',
'    const minutes = String(now.getMinutes()).padStart(2, ''0'');',
'    const seconds = String(now.getSeconds()).padStart(2, ''0'');',
'    ',
'    return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;',
'}',
'',
''))
