wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(144101314111161196)
,p_name=>'P37_KNOWLEDGE_BASE_NAME'
,p_item_sequence=>20
,p_item_plug_id=>wwv_flow_imp.id(147500363710937490)
,p_prompt=>'Knowledge Base Name'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov_language=>'PLSQL'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    lv_sql VARCHAR2(32766);',
'    lv_available_view_kb VARCHAR2(4000);',
'BEGIN',
'    lv_sql := ''',
'        SELECT knowledge_base_name d, knowledge_base_name r',
'        FROM   kmchat_kb',
'        WHERE  kb_publish_status = ''''Published''''',
'        AND    app_id            =  V(''''APP_ID'''')',
'        '';',
'    IF apex_authorization.is_authorized (p_authorization_name => ''ADMIN'' ) = TRUE OR apex_app_setting.get_value(p_name => ''ACCESS_CONTROL_SCOPE'') = ''ALL_USERS'' THEN',
'        RETURN lv_sql;',
'    ELSE',
'        BEGIN',
'            SELECT available_view_kb INTO lv_available_view_kb FROM kmchat_kb_user WHERE UPPER(user_name) = V(''APP_USER'') AND app_id = V(''APP_ID'');',
'            lv_available_view_kb := ''''''''||REPLACE(lv_available_view_kb, '','' ,'''''','''''')||'''''''';',
'        EXCEPTION  ',
'            WHEN OTHERS THEN',
'                lv_available_view_kb := NULL;',
'        END;',
'        ',
'        IF lv_available_view_kb IS NOT NULL THEN',
'            lv_sql := lv_sql ||'' AND (knowledge_base_name IN(''||lv_available_view_kb||'')'';',
'            RETURN lv_sql ||''    OR UPPER(appuser) = V(''''APP_USER''''))'';',
'        END IF;',
'        ',
'        RETURN lv_sql ||'' AND UPPER(appuser) = V(''''APP_USER'''')''; ',
'        ',
'    END IF;',
'END;',
''))
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(106532568633103579)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
