wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(144103284153161216)
,p_process_sequence=>10
,p_process_point=>'AFTER_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Set select Profile'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    SELECT  LLM_MODEL,',
'            CHAT_CATAGORY,',
'            PROMPT_NAME,',
'            QUERY_SIMILARITY_FLAG,',
'            SEARCH_TYPE,',
'            VECTOR_TOPK,',
'            RERANKER_MODEL,',
'            RERANKER_TOPK,',
'            SCORE_THRESHOLD,',
'            HISTORY_K,',
'            SUMMARY',
'    INTO    :P37_PROFILE_TEMP_MODEL,',
'            :P37_CHAT_CATEGORY,',
'            :P37_PROMPT_NAME,',
'            :P37_QUERYSIMILARITY_FLAG,',
'            :P37_SEARCH_TYPE,',
'            :P37_VECTOR_STORE_LIMIT,',
'            :P37_RERANKER_MODEL,',
'            :P37_RERANKER_TOPK,',
'            :P37_SCORE_THRESHOLD,',
'            :P37_HISTORY_K,',
'            :P37_SUMMARY',
'    FROM    KMCHAT_CHAT_USER_PROFILE',
'    WHERE (UPPER(APP_USER) = UPPER(V(''APP_USER'')) OR PROFILE_NAME = ''Sys_Default'')',
'    AND   APP_ID   = V(''APP_ID'')',
'    AND   ID = TO_NUMBER(:P37_PROFILE);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'PROFILE_SETTING'
,p_process_when_type=>'REQUEST_EQUALS_CONDITION'
,p_internal_uid=>80767867589426837
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(144103336795161217)
,p_process_sequence=>20
,p_process_point=>'AFTER_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'init set profile'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    LV_LLM_MODEL       VARCHAR2(400);',
'    LV_CHAT_CATAGORY   VARCHAR2(400);',
'    LV_PROMPT_NAME     VARCHAR2(400);',
'    LV_QUERY_SIMILARITY_FLAG VARCHAR2(400);',
'    LV_SEARCH_TYPE     VARCHAR2(400);',
'    LN_VECTOR_TOPK     NUMBER;',
'    LV_RERANKER_MODEL  VARCHAR2(400);',
'    LN_RERANKER_TOPK   NUMBER;',
'    LN_SCORE_THRESHOLD NUMBER;',
'    LN_HISTORY_K       NUMBER;',
'    lv_url             VARCHAR2(4000);',
'BEGIN',
'    SELECT  LLM_MODEL,',
'            CHAT_CATAGORY,',
'            PROMPT_NAME,',
'            QUERY_SIMILARITY_FLAG,',
'            SEARCH_TYPE,',
'            VECTOR_TOPK,',
'            RERANKER_MODEL,',
'            RERANKER_TOPK,',
'            SCORE_THRESHOLD,',
'            HISTORY_K,',
'            SUMMARY',
'    INTO    :P37_PROFILE_TEMP_MODEL,',
'            :P37_CHAT_CATEGORY,',
'            :P37_PROMPT_NAME,',
'            :P37_QUERYSIMILARITY_FLAG,',
'            :P37_SEARCH_TYPE,',
'            :P37_VECTOR_STORE_LIMIT,',
'            :P37_RERANKER_MODEL,',
'            :P37_RERANKER_TOPK,',
'            :P37_SCORE_THRESHOLD,',
'            :P37_HISTORY_K,',
'            :P37_SUMMARY',
'    FROM    KMCHAT_CHAT_USER_PROFILE',
'    WHERE UPPER(APP_USER) = UPPER(V(''APP_USER''))',
'    AND   APP_ID   = V(''APP_ID'')',
'    and   USER_DEFAULT_PROFILE = ''Y'';',
'    ',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        BEGIN',
'            SELECT  LLM_MODEL,',
'                    CHAT_CATAGORY,',
'                    PROMPT_NAME,',
'                    QUERY_SIMILARITY_FLAG,',
'                    SEARCH_TYPE,',
'                    VECTOR_TOPK,',
'                    RERANKER_MODEL,',
'                    RERANKER_TOPK,',
'                    SCORE_THRESHOLD,',
'                    HISTORY_K,',
'                    SUMMARY',
'            INTO    :P37_PROFILE_TEMP_MODEL,',
'                    :P37_CHAT_CATEGORY,',
'                    :P37_PROMPT_NAME,',
'                    :P37_QUERYSIMILARITY_FLAG,',
'                    :P37_SEARCH_TYPE,',
'                    :P37_VECTOR_STORE_LIMIT,',
'                    :P37_RERANKER_MODEL,',
'                    :P37_RERANKER_TOPK,',
'                    :P37_SCORE_THRESHOLD,',
'                    :P37_HISTORY_K,',
'                    :P37_SUMMARY',
'            FROM    KMCHAT_CHAT_USER_PROFILE',
'            WHERE   APP_ID   = V(''APP_ID'')',
'            and   PROFILE_NAME = ''Sys_Default'';',
'        EXCEPTION',
'            WHEN OTHERS THEN',
'                NULL;',
'        END;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'init'
,p_process_when_type=>'REQUEST_EQUALS_CONDITION'
,p_internal_uid=>80767920231426838
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(144103055240161214)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Clean History'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_clob 	        CLOB;',
'    l_server        VARCHAR2(4000);',
'BEGIN',
'    --  clear',
'    SELECT S_URL INTO l_server FROM KMCHAT_KB_SERVER WHERE S_NAME = ''SERVER'' AND APP_ID = V(''APP_ID''); ',
'',
'    apex_web_service.g_request_headers.delete();',
'    apex_web_service.g_request_headers(1).name  := ''accept'';',
'    apex_web_service.g_request_headers(1).value := ''application/json'';',
'    apex_web_service.g_request_headers(2).name  := ''Content-Type'';',
'    apex_web_service.g_request_headers(2).value := ''application/json''; ',
'    l_clob := apex_web_service.make_rest_request(',
'            p_url => l_server||''/chat/clear_disable_memory_rag_history'',',
'            p_http_method => ''POST'',',
'            p_body => ''{',
'               "user": "''||:APP_USER||''",',
'               "kb_name" : "''||:P37_KNOWLEDGE_BASE_NAME||''",',
'               "llm_model":"''||:P37_MODEL||''"',
'               }',
'               ''',
'        );',
'',
'    delete from kmchat_kb_riva where id in (',
'    select r.id',
'    from KMCHAT_kb_RIVA r connect by prior r.id=r.parent_id',
'    start with upper(r.appuser) = :APP_USER and r.app_id = V(''APP_ID'') and r.chat_type = ''Chat RAG'' and r.kb_name = :P37_KNOWLEDGE_BASE_NAME',
'    );',
'    commit;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(144103000271161213)
,p_internal_uid=>80767638676426835
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(144100796574161191)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_BOT_RESPONSE'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_clob                    CLOB;',
'    lv_input                  kmchat_kb_riva.TEXT_JSON%TYPE;',
'    lv_catagory               VARCHAR2(400);',
'    lv_prompt_name            VARCHAR2(400);',
'    lv_chat_catagory          VARCHAR2(400);',
'    ln_user_id                NUMBER;',
'    ln_ai_id                  NUMBER;',
'    lv_server_url             VARCHAR2(4000);',
'    lv_question               kmchat_kb_riva.TEXT_JSON%TYPE := apex_application.g_x01;',
'    lv_json_question          kmchat_kb_riva.TEXT_JSON%TYPE;',
'    lv_syn_status            VARCHAR2(1);',
'    ln_synonym_similarity_threshold NUMBER;',
'    lc_vector                vector;',
'    lv_txt_embedding_status  VARCHAR2(400);',
'    ln_syn_distance          NUMBER;',
'    lv_standard_question     VARCHAR2(4000);',
'    lv_old_standard_question VARCHAR2(4000);',
'    lv_new_question          kmchat_kb_riva.TEXT_JSON%TYPE;',
'    ln_query_similarity_threshold NUMBER;',
'    lc_fb_answer_JSON        CLOB;',
'    lc_fb_answer             CLOB;',
'    ln_distance              NUMBER;',
'    ln_feedback_id           NUMBER;',
'    j                        apex_json.t_values;',
'    lv_status                VARCHAR2(100);',
'    l_paths                  apex_t_varchar2;',
'    lv_answer                CLOB;',
'    ld_ai_create_date        DATE;',
'    lv_chat_category         VARCHAR2(400);',
'BEGIN',
'    ',
'    SELECT S_URL INTO lv_server_url FROM KMCHAT_KB_SERVER WHERE S_NAME = ''SERVER'' AND APP_ID = V(''APP_ID''); ',
'    lv_chat_category := :P37_CHAT_CATEGORY;',
'    ',
'     IF :P37_MODEL = ''NoneLLM'' THEN',
'        lv_server_url := lv_server_url || ''/knowledge_base/query'';',
'    ELSE',
'        IF lv_chat_category= ''with_rag'' THEN',
'            lv_server_url := lv_server_url || ''/chat/with_rag'';',
'        ELSE',
'            lv_server_url := lv_server_url || ''/chat/with_history_rag'';',
'        END IF;',
'    END IF;',
'',
'    apex_web_service.g_request_headers(1).name :=  ''Content-Type'';',
'    apex_web_service.g_request_headers(1).value := ''application/json'';',
'    lv_prompt_name := :P37_PROMPT_NAME;',
'--',
'    lv_input := ''',
'        "kb_name":"'' ||:P37_KNOWLEDGE_BASE_NAME|| ''",',
'        "search_type": "'' ||:P37_SEARCH_TYPE|| ''",',
'        "summary_flag":"'' ||:P37_SUMMARY|| ''",',
'        "rerankerModel": "'' ||:P37_RERANKER_MODEL|| ''",',
'        "reranker_topk": '' ||:P37_RERANKER_TOPK|| '',',
'        "score_threshold": '' ||CASE WHEN :P37_SCORE_THRESHOLD LIKE ''.%'' THEN ''0''||:P37_SCORE_THRESHOLD ELSE to_char(:P37_SCORE_THRESHOLD) END|| '',',
'        "vector_store_limit": '' ||:P37_VECTOR_STORE_LIMIT|| '''';',
'--',
'    IF INSTR(lv_server_url,''with_history_rag'') > 0 THEN',
'        lv_input := lv_input||'',"user":"''||V(''APP_USER'')||''"''',
'                          ||'',"llm_model":"'' ||:P37_MODEL|| ''"''',
'                          ||'',"prompt_name": "'' ||lv_prompt_name||''"''',
'                          ||'',"history_k":''||:P37_HISTORY_K||''}'';',
'        lv_catagory :=  ''with_history_rag'';',
'        lv_chat_catagory := ''Enable Memory Chat'';',
'    ELSIF :P37_MODEL = ''NoneLLM'' THEN',
'        -- lv_input := lv_input|| ''}'';',
'        lv_input := lv_input|| '',"user":"''||V(''APP_USER'')||''"}'';',
'        lv_prompt_name := NULL;',
'        lv_chat_category := NULL;',
'    ELSE',
'        lv_input := lv_input||'',"user":"''||V(''APP_USER'')||''"''',
'                          ||'',"llm_model":"'' ||:P37_MODEL|| ''"''',
'                          ||'',"prompt_name": "'' ||lv_prompt_name||''"''',
'                          || ''}'';',
'        lv_catagory :=  ''with_rag'';',
'        lv_chat_catagory := ''Disable Memory Chat'';',
'    END IF;',
'    ln_user_id := KMCHAT_KB_RIVA_SEQ.nextval;',
'    lv_json_question := ''{"ask":"'' ||lv_question|| ''",''||lv_input ;',
'    insert into KMCHAT_KB_RIVA(id, MODEL_NAME, TEXT_DISP, text_json, APPUSER, APP_ID, CREATED_TIME, chat_type, kb_name) values(ln_user_id, :P37_MODEL, lv_question, lv_json_question, V(''APP_USER''), V(''APP_ID''), current_date, ''Chat RAG'' ,:P37_KNOWLEDGE'
||'_BASE_NAME);',
'    ',
'    COMMIT;',
'    -- Confirm whether synonyms in the knowledge base are enabled.',
'    BEGIN',
'        SELECT status,synonym_similarity_threshold',
'        INTO   lv_syn_status,ln_synonym_similarity_threshold',
'        FROM   kmchat_synonym_conf',
'        WHERE  kb_name = :P37_KNOWLEDGE_BASE_NAME',
'        AND    app_id = V(''APP_ID'');',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            lv_syn_status := ''N'';',
'            ln_synonym_similarity_threshold := ''0'';',
'    END;',
'',
'    -- FeedBack Check',
'    IF :P37_QUERYSIMILARITY_FLAG = ''On'' OR lv_syn_status = ''Y'' THEN',
'        KMCHAT_KB_BASE_PKG.txt_embedding(',
'                iv_kb_name     => :P37_KNOWLEDGE_BASE_NAME,',
'                iv_text        => lv_question,',
'                ov_text_vector => lc_vector,',
'                ov_status      => lv_txt_embedding_status);',
'',
unistr('        -- \53CD\9988\5185\5BB9\5411\91CF\5339\914D'),
'        IF :P37_QUERYSIMILARITY_FLAG = ''On'' AND lv_txt_embedding_status = ''success'' THEN',
unistr('            -- \83B7\53D6\76F8\4F3C\5EA6\9608\503C'),
'            BEGIN',
'                SELECT value ',
'                INTO   ln_query_similarity_threshold ',
'                FROM   kmchat_kb_dict',
'                WHERE  type=''QUERY_SIMILARITY_THRESHOLD'' ',
'                AND    active_yn = ''Y'' ',
'                AND    app_id = V(''APP_ID'')',
'                ORDER BY SEQ FETCH FIRST 1 ROWS ONLY;',
'            EXCEPTION',
'                WHEN OTHERS THEN',
'                    ln_query_similarity_threshold := 0;',
'            END;',
'            -- vector search',
'            BEGIN',
'                SELECT answer_json,',
'                       ANSWER_DISP,',
'                       VECTOR_DISTANCE(question_vector,lc_vector,COSINE) question_distance,',
'                       id',
'                INTO   lc_fb_answer_JSON,',
'                       lc_fb_answer,',
'                       ln_distance,',
'                       ln_feedback_id',
'                FROM   kmchat_kb_feedback',
'                WHERE  kb_name =  :P37_KNOWLEDGE_BASE_NAME',
'                AND    llm_model = :P37_MODEL',
'                AND    NVL(chat_catagory,1) = NVL(lv_chat_catagory,1)',
'                AND    NVL(prompt_name,1)   = NVL(lv_prompt_name,1)',
'                AND    app_user             = V(''APP_USER'')',
'                AND    app_id               = V(''APP_ID'')',
'                AND    feedback             = ''good''',
'                AND    chat_type            = ''Chat RAG''',
'                ORDER BY question_distance',
'                FETCH FIRST 1 ROWS ONLY;',
unistr('               -- \9608\503CCheck'),
'                -- apex_debug.warn(''question_distance:''||ln_distance);',
'                IF ln_distance > ln_query_similarity_threshold OR ln_feedback_id IS NULL THEN',
'                    lc_fb_answer_JSON := NULL;',
'                    lc_fb_answer := NULL;',
'                END IF;',
'            EXCEPTION',
'                WHEN OTHERS THEN',
'                    lc_fb_answer_JSON := NULL;',
'                    lc_fb_answer := NULL;',
'                    ln_feedback_id := NULL;',
'                    ln_distance := NULL;',
'            END;',
'        END IF;',
'        ',
'        IF lv_syn_status = ''Y'' AND lc_fb_answer_JSON is null THEN',
'            BEGIN',
'                SELECT vector_distance(ksd.synonym_vector,lc_vector,cosine) syn_distance,',
'                       ksm.standard_question',
'                INTO   ln_syn_distance,',
'                       lv_standard_question',
'                FROM   kmchat_synonym_conf  ksc,',
'                       kmchat_synonym_master ksm,',
'                       kmchat_synonym_detail ksd',
'                WHERE ksc.ID = ksm.conf_id',
'                AND   ksm.ID = ksd.master_id',
'                AND   ksc.kb_name = :P37_KNOWLEDGE_BASE_NAME',
'                AND   ksc.app_id = V(''APP_ID'')',
'                ORDER BY syn_distance',
'                FETCH FIRST 1 ROWS ONLY;',
unistr('                -- \9608\503CCheck'),
'                lv_old_standard_question := lv_standard_question;',
'                IF ln_syn_distance > ln_synonym_similarity_threshold THEN',
'                    lv_standard_question := NULL;',
'                END IF;',
'            EXCEPTION',
'                WHEN OTHERS THEN',
'                    lv_standard_question := NULL;',
'                    ln_syn_distance := NULL;',
'            END;      ',
'            lv_new_question := lv_standard_question;',
'        END IF;',
'    END IF;',
'    ',
'    IF lc_fb_answer_JSON IS NOT NULL THEN',
'        l_clob := lc_fb_answer_JSON;',
'        lv_answer := lc_fb_answer;',
'    ELSE',
'        apex_web_service.g_request_headers(1).name  := ''content-type'';',
'        apex_web_service.g_request_headers(1).value := ''application/json''; ',
'              ',
'        l_clob := apex_web_service.make_rest_request(',
'            p_url => lv_server_url,',
'            p_http_method => ''POST'',',
'            p_body => ''{"ask":"'' ||NVL(lv_new_question,lv_question)|| ''",''||lv_input',
'        );',
'           ',
'        apex_json.parse(j, l_clob);',
'        -- apex_json.parse(j, REPLACE(REPLACE(l_clob, ''\\n'', ''<br/>''), ''\n'', ''<br/>''));',
'        lv_status := apex_json.get_varchar2(p_path=>''status'',p_values=>j);',
'        IF  lv_status = ''success'' THEN',
'            l_paths := apex_json.find_paths_like (',
'                p_values         => j,',
'                p_return_path => ''data[%]''',
'            );',
'            BEGIN',
'                IF lv_new_question IS NOT NULL THEN',
'                    lv_answer := ''Rewrite Question: ''||lv_new_question||'' <br/>''||apex_json.get_varchar2(p_values => j, p_path => l_paths(1)||''.content'');',
'                ELSE',
'                    lv_answer := apex_json.get_varchar2(p_values => j, p_path => l_paths(1)||''.content'');',
'                END IF;',
'            EXCEPTION',
'                WHEN OTHERS THEN',
'                    lv_answer := null;',
'            END;',
'        ELSE',
'            lv_answer := apex_json.get_varchar2(p_path=>''err_msg'',p_values=>j);',
'        END IF;',
'    END IF;',
'',
'',
'    ln_ai_id := KMCHAT_KB_RIVA_SEQ.nextval;',
'    ld_ai_create_date := current_date;',
'    INSERT INTO kmchat_kb_riva(id, text_disp, text_json, created_time, appuser, parent_id, url, model_name, app_id, feedback, chat_type,feedback_id, kb_name) ',
'    VALUES(ln_ai_id, lv_answer , l_clob, ld_ai_create_date, ''chatbot'', ln_user_id, lv_server_url, :P37_MODEL, V(''APP_ID''),case when lc_fb_answer_JSON is not null then ''good'' else NULL end, ''Chat RAG'',ln_feedback_id, :P37_KNOWLEDGE_BASE_NAME);',
'    COMMIT;',
'    -- QA History Instr',
'    INSERT INTO kmchat_kb_qa',
'    (kb_name, llm_model, chat_catagory, prompt_name,  question, answer, app_user, create_date, app_id, feedback_id, vector_distance, query_similarity_flag, synonym_status ,synonym_vector_distance, synonym_standard_question, chat_type)',
'    VALUES',
'    (:P37_KNOWLEDGE_BASE_NAME, :P37_MODEL, lv_chat_category, lv_prompt_name, lv_question, lv_answer, V(''APP_USER''), ld_ai_create_date, V(''APP_ID''),ln_feedback_id, ln_distance, :P37_QUERYSIMILARITY_FLAG, lv_syn_status, ln_syn_distance, lv_old_standard'
||'_question, ''Chat RAG''); ',
'    COMMIT;',
'',
'    apex_json.open_object;',
'    apex_json.write(''response'', lv_answer);',
'    apex_json.write(''bot_response'', l_clob);',
'    apex_json.write(''chat_id'', ln_ai_id);',
'    apex_json.write(''ai_created_time'',TO_CHAR(ld_ai_create_date,''yyyy-mm-dd hh24:mi:ss''));',
'    apex_json.write(''feedback_type'', case when lc_fb_answer_JSON is not null then ''good'' else NULL end);',
'    apex_json.close_object;',
'END;',
'',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>80765380010426812
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(144100882030161192)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'LOAD_HISTORY'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'  apex_json.open_object;',
'  apex_json.open_array(''history'');',
'',
'  FOR rec IN (select  a.TEXT_DISP       as question',
'                    , b.MODEL_NAME      as model_name',
'                    , to_char(a.CREATED_TIME,''yyyy-mm-dd hh24:mi:ss'')    as question_date',
'                    , b.id, b.TEXT_DISP as answer',
'                    , b.TEXT_JSON       as answer_json',
'                    , to_char(b.CREATED_TIME,''yyyy-mm-dd hh24:mi:ss'')     as answer_data',
'                    , b.FEEDBACK',
'                from kmchat_kb_riva a,',
'                     kmchat_kb_riva b',
'                where a.id = b.PARENT_ID',
'                and   a.appuser = V(''APP_USER'')',
'                and   a.app_id =  V(''APP_ID'')',
'                and   a.CHAT_TYPE = ''Chat RAG''',
'                and   a.kb_name  = apex_application.g_x01',
'                ORDER BY a.CREATED_TIME asc',
'  ) LOOP',
'    apex_json.open_object;',
'    apex_json.write(''feedback_type'', rec.FEEDBACK);',
'    apex_json.write(''model_name'', rec.model_name);',
'    apex_json.write(''user_prompt'', rec.question);',
'    apex_json.write(''response'', rec.answer);',
'    apex_json.write(''bot_response'', rec.answer_json);',
'    apex_json.write(''user_created_time'', rec.question_date);',
'    apex_json.write(''ai_created_time'', rec.answer_data);',
'    apex_json.write(''chat_id'', rec.id);',
'    apex_json.close_object;',
'  END LOOP;',
'',
'  apex_json.close_array;',
'  apex_json.close_object;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>80765465466426813
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(144100981782161193)
,p_process_sequence=>30
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SAVE_FEEDBACK'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_chat_id      NUMBER := APEX_APPLICATION.G_X01;',
'    l_type         VARCHAR2(10) := APEX_APPLICATION.G_X02; -- ''LIKE'' or ''DISLIKE''',
'    l_reason       VARCHAR2(4000) := APEX_APPLICATION.G_X03;',
'    l_id             NUMBER;',
'    ln_p_id          NUMBER;',
'    lc_answer        CLOB;',
'    lv_ques          VARCHAR2(4000);',
'    lc_JSON          CLOB;',
'    j                apex_json.t_values;',
'    lv_kb_name       VARCHAR2(4000);',
'    lv_model         VARCHAR2(4000);',
'    lv_prompt_name   VARCHAR2(4000);',
'    lj_more_param    VARCHAR2(4000);',
'    lv_chat_catagory VARCHAR2(4000) := NULL;',
'    lc_answer_json   CLOB;',
'    lv_server        VARCHAR2(400);',
'    l_clob           CLOB;',
'    l_vector         VECTOR;',
'    lv_txt_embedding_status VARCHAR2(4000);',
'    lv_search_type   VARCHAR2(400);',
'    ln_feedback_id   NUMBER;',
'    lv_feedback      VARCHAR2(100);',
'BEGIN',
'--',
'    SELECT A.text_disp,A.text_JSON,B.text_disp,B.text_json,b.feedback,B.feedback_id',
'    INTO   lv_ques,lc_JSON,lc_answer,lc_answer_json,lv_feedback,ln_feedback_id',
'    FROM   kmchat_kb_riva A,',
'           kmchat_kb_riva B ',
'    WHERE  A.ID = B.parent_id ',
'    AND    B.ID = l_chat_id;',
'',
'    IF ln_feedback_id IS NOT NULL AND lv_feedback = l_type THEN',
'        UPDATE kmchat_kb_riva SET feedback = NULL AND feedback_id = NULL WHERE feedback_id = ln_feedback_id;',
'        DELETE kmchat_kb_feedback WHERE id = ln_feedback_id;',
'        IF lv_feedback = ''good'' THEN',
'            htp.p(''3'');',
'        ELSE',
'            htp.p(''2'');',
'        END IF;',
'    ELSE',
'        -- APEX_DEBUG.WARN(''uncancel'');',
'        -- Feedback is null',
'        apex_json.parse(j,lc_JSON);',
'        lv_kb_name := apex_json.get_varchar2(p_path=>''kb_name'',p_values=>j);',
'        lv_model := NVL(apex_json.get_varchar2(p_path=>''llm_model'',p_values=>j),''NoneLLM'');',
'        lv_prompt_name := apex_json.get_varchar2(p_path=>''prompt_name'',p_values=>j);',
'            ',
'        lj_more_param := ''{'';',
'        IF apex_json.get_varchar2(p_path=>''vector_store_limit'',p_values=>j) IS NOT NULL THEN',
'            lj_more_param := lj_more_param||''',
'                "vector_topk" : "''||apex_json.get_varchar2(p_path=>''vector_store_limit'',p_values=>j)||''"',
'            '';',
'        END IF;',
'',
'        IF apex_json.get_varchar2(p_path=>''search_type'',p_values=>j) IS NOT NULL THEN',
'            lj_more_param := lj_more_param||'',"search_type" : "''||apex_json.get_varchar2(p_path=>''search_type'',p_values=>j)||''"',
'            '';',
'        END IF;',
'            ',
'        IF apex_json.get_varchar2(p_path=>''summary_flag'',p_values=>j) IS NOT NULL THEN',
'            lj_more_param := lj_more_param||'',"summary_flag" : "''||apex_json.get_varchar2(p_path=>''summary_flag'',p_values=>j)||''"',
'            '';',
'        END IF;',
'',
'        IF apex_json.get_varchar2(p_path=>''rerankerModel'',p_values=>j) IS NOT NULL THEN',
'            lj_more_param := lj_more_param||'',"rerankerModel" : "''||apex_json.get_varchar2(p_path=>''rerankerModel'',p_values=>j)||''"',
'            '';',
'        END IF;',
'',
'        IF apex_json.get_varchar2(p_path=>''reranker_topk'',p_values=>j) IS NOT NULL THEN',
'            lj_more_param := lj_more_param||'',"reranker_topk" : "''||apex_json.get_varchar2(p_path=>''reranker_topk'',p_values=>j)||''"',
'            '';',
'        END IF;',
'',
'        IF apex_json.get_varchar2(p_path=>''score_threshold'',p_values=>j) IS NOT NULL THEN',
'            lj_more_param := lj_more_param||'',"score_threshold" : "''||apex_json.get_varchar2(p_path=>''score_threshold'',p_values=>j)||''"',
'            '';',
'        END IF;',
'',
'        IF apex_json.get_varchar2(p_path=>''history_k'',p_values=>j) IS NOT NULL THEN',
'            lj_more_param := lj_more_param||'',"history_k" : "''||apex_json.get_varchar2(p_path=>''history_k'',p_values=>j)||''"',
'            '';',
'            lv_chat_catagory := ''Enable Memory Chat'';',
'        ELSE',
'            IF lv_model != ''NoneLLM'' THEN',
'                lv_chat_catagory := ''Disable Memory Chat'';',
'            END IF;',
'        END IF;',
'',
'        lj_more_param := lj_more_param || ''}'';',
'',
'        KMCHAT_KB_BASE_PKG.txt_embedding(',
'            iv_kb_name     => lv_kb_name,',
'            iv_text        => lv_ques,',
'            ov_text_vector => l_vector,',
'            ov_status      => lv_txt_embedding_status);',
'',
'        IF lv_txt_embedding_status = ''success'' THEN',
'    --',
'            IF ln_feedback_id IS NOT NULL THEN',
'                DELETE kmchat_kb_feedback WHERE id = ln_feedback_id;',
'            END IF;',
'    --',
'            INSERT INTO kmchat_kb_feedback(kb_name, llm_model, chat_catagory, prompt_name, more_param, feedback, feedback_reason, question, question_vector, answer_disp, answer_json, chat_type, app_user, create_date, app_id) ',
'            VALUES(',
