'                lv_chat_catagory,',
'                lv_prompt_name,',
'                lj_more_param,',
'                l_type,',
'                l_reason,',
'                lv_ques,',
'                to_vector(l_vector),',
'                lc_answer,',
'                lc_answer_json,',
'                ''Chat RAG'',',
'                V(''APP_USER''),',
'                current_date,',
'                V(''APP_ID'')',
'            )RETURNING ID INTO ln_feedback_id;',
'',
'            ',
'            UPDATE  kmchat_kb_riva',
'            SET     feedback_id = ln_feedback_id',
'            ,       feedback = l_type ',
'            WHERE   id    = l_chat_id;',
'            COMMIT;',
'    --',
'            htp.p(''1'');',
'        ELSE',
unistr('            -- kbot\5411\91CF\5316\9519\8BEF'),
'            htp.p(''0''); ',
'        END IF;',
'    END IF;',
'--',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        rollback;',
'        htp.p(''0:'');  ',
'END;',
''))
,p_process_clob_language=>'PLSQL'
