prompt --application/pages/page_00040
begin
wwv_flow_imp_page.create_page(
 p_id=>40
,p_name=>'ChatRAG'
,p_alias=>'CHATRAG'
,p_step_title=>'ChatRAG'
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'const s_url = apex.item(P40_SERVER_URL).getValue();',
'const langCode = apex.item(P40_LANG_CODE).getValue();',
'let   chatId, $thumb, $bubble= '''';',
'const $chatArea = $("#chat-area");',
'let   querySimilarityFlag;',
'',
'// Display AI is thinking',
'let $loadingBubble = $(',
'    `<div class="chat-bubble bot loading-bubble">',
unistr('        <div class="avatar">\D83E\DD16</div>'),
'        <div class="content">',
'            <div class="message"><span class="dot-typing"></span><span class="dot-typing"></span></div>',
'        </div>',
'    </div>`',
');',
'// Send message button click event',
'let isSending = false;',
'async function sendMsg() {',
'    if (isSending) return;',
'    const userText = $(''#user-input'').val().trim();',
'    if (!userText) return;',
'    $(''#user-input'').val('''');',
'    if (userText === '''') return;',
'    isSending = true;',
'    querySimilarityFlag = apex.item(P40_QUERYSIMILARITY_FLAG).getValue();',
'    // Display user messages',
'    $chatArea.append(',
'        `<div class="chat-bubble user">',
'            <div class="avatar"><span class ="avatar-user"> ${apex.env.APP_USER} </span></div>',
'            <div class="content">',
'                <div class="message">  ${userText} </div>',
'                <div class="timestamp"> ${getLocalTime()} </div>',
'            </div>',
'        </div>`',
'    );',
'    $chatArea.append($loadingBubble);',
'    scrollChatToBottom();',
'    //feedback check',
'    const llmVal = apex.item(P40_MODEL).getValue();',
'    let requestBody = {',
'        user: apex.env.APP_USER,',
'        kb_name: apex.item("P40_KNOWLEDGE_BASE_NAME").getValue(),',
'        rerankerModel: apex.item("P40_RERANKER_MODEL").getValue(),',
'        reranker_topk: Number(apex.item("P40_RERANKER_TOPK").getValue()),',
'        score_threshold: Number(apex.item("P40_SCORE_THRESHOLD").getValue()),',
'        vector_store_limit: Number(apex.item("P40_VECTOR_STORE_LIMIT").getValue()),',
'        search_type: apex.item("P40_SEARCH_TYPE").getValue(),',
'        summary_flag: apex.item("P40_SUMMARY").getValue()',
'    };',
'',
'    if (llmVal === ''NoneLLM'') {',
'        requestBody.ask = userText;',
'    } else {',
'        requestBody.question = userText;',
'        requestBody.llm_model = apex.item("P40_MODEL").getValue();',
'        requestBody.prompt_name = apex.item("P40_PROMPT_NAME").getValue();',
'    }',
'    apex.server.process("INSTR_BOT_RES_FB", {',
'            x01: userText,',
'            x02: JSON.stringify(requestBody),',
'            x03: llmVal,',
'            x04: querySimilarityFlag',
'    }, {',
'        success: function(pData) {',
'            if(pData.code == 200){',
'                // feedback render',
'                feedBack_or_noneLLM_render(pData, llmVal);',
'            }else if(pData.code == 404){',
'                // rag render',
'                let synonym_json = {};',
'                if(pData.standard_qustion){',
'                    synonym_json.standard_qustion = pData.standard_qustion;',
'                    synonym_json.synonym_status = pData.synonym_status;',
'                    synonym_json.synonym_distance = pData.synonym_distance;',
'                    kbot_response_render(synonym_json, userText, ''synonym'', llmVal, requestBody);',
'                }else{',
'                    synonym_json.standard_qustion = '''';',
'                    synonym_json.synonym_status = '''';',
'                    synonym_json.synonym_distance = '''';',
'                    kbot_response_render(synonym_json, userText, ''standard'', llmVal, requestBody);',
'                }',
'            }else{',
'                print_sys_err_msg(pData.msg);',
'            }',
'                ',
'            isSending = false;',
'        },',
'        error: function(jqXHR, textStatus, errorThrown) {',
'            console.error("error", textStatus);',
'            print_sys_err_msg();',
'            ',
'        }',
'    });',
'};',
'',
'// feedback or noneLLM Result render',
'function feedBack_or_noneLLM_render(data, type){',
'    let botText, response_json = '''', response_status = ''success'';',
'    if(data.bot_response){',
'        response_json = JSON.parse(data.bot_response);',
'        if(response_json.status == ''success''){',
'            //Normal kbot output',
'            botText = data.response||"";',
'        }else{',
'            //Retrieve kbot error information',
'            botText = response_json.err_msg;',
'            response_status = ''faild'';',
'        }',
'    }else{',
'        //Retrieve PLSQL error information',
'        botText = data.response||"";',
'        response_status = ''faild'';',
'    }',
'            ',
'    // set selected class  ',
'    let likeSelected = data.feedback_type === ''good'' ? ''selected'' : '''';',
'    let dislikeSelected = data.feedback_type === ''bad'' ? ''selected'' : '''';',
'    let $botDiv = get_ai_response_dom(data.chat_id, data.ai_created_time, likeSelected, dislikeSelected);',
'    $loadingBubble.remove(); ',
'    $chatArea.append($botDiv);',
'    let $botStream = $botDiv.find(''.bot-stream'');',
'',
'    let i = 0;',
'    function typeWriter() {',
'        if (i < botText.length) {',
'            if (botText.substring(i, i + 5) === ''<br/>'') {',
'                $botStream.append(''<br/>'');',
'                i += 5; // skip </br>',
'            } else {',
'                $botStream.append(botText.charAt(i));',
'                i++;',
'            }',
'            scrollChatToBottom();',
'            setTimeout(typeWriter, 10);',
'        } else {',
'            if(type !== ''NoneLLM''){',
'                let aiResponseDom =  init_kbot_code_generation_showMore(data.chat_id, response_json, data.response, ''feedback'');',
'                $botStream.append(aiResponseDom);',
'            }else{',
'                let $botMsg = $botDiv.find(''.message'');',
'                let downloadDom = show_noneLLM_download(response_json);',
'                $botMsg.append(downloadDom);',
'            }',
'            ',
'',
'            scrollChatToBottom();',
'        }',
'    }',
'    //kbot response success',
'    if(response_status == ''success''){',
'        typeWriter();',
'    //kbot response error',
'    }else{',
'        $botStream.append(kbot_response_error(botText))',
'    }',
'',
'};',
'',
'// show noneLLM Download',
'function show_noneLLM_download(response){',
'    let downloadDom ='''';',
'    response.data.forEach((item, index) => {',
'        if(index == 0){',
unistr('            downloadDom = `<br/>&gt;&gt; ${langCode == ''zh-cn''?''\53C2\8003\8D44\6E90'':''Reference Resources''}: <span class="refFileSpan" >[<a  class="refFileA" href="${item.source}" target="_blank"> ${langCode == ''zh-cn''?''\4E0B\8F7D'':''Download''} </a>]  </span>`; '),
'            return;',
'        }',
'    });',
'    return downloadDom;',
'}',
'',
'// kbot response result render',
'async function kbot_response_render(synonym_json, question, type, llmVal, requestBody){',
'    let lvSessionId, ins_data_result, lv_sse_result = '''', noneLLM_response = '''', url = '''', newRequestBody = requestBody;;',
'    //get session_id and refrence',
'    const  userText = type == ''standard''?question:synonym_json.standard_qustion;',
'',
'    if(llmVal == ''NoneLLM''){',
'        newRequestBody.ask = userText;',
'        url = ''/knowledge_base/query'';',
'    }else{',
'        newRequestBody.question = userText;',
'        url = ''/chat/create_rag_stream'';',
'    }',
'    console.log(''RequestBody'',newRequestBody);',
'    const  refSource = await get_api_source(newRequestBody, url);',
'',
'    if(!refSource) return;',
'',
'    if(refSource.status == ''success''){',
'        if(refSource.data){',
'            refSource.data.forEach((item, index) => {',
'                if(index == 0){',
'                    if(llmVal == ''NoneLLM''){',
'                        noneLLM_response = item.content;',
'                    }else{',
'                        lvSessionId = item.sse_session_id;',
'                    }',
'                    ',
'                    return;',
'                }',
'            });',
'            //insert bot response refrence',
'            ins_data_result = JSON.parse(await instr_bot_response_ref(refSource, noneLLM_response, synonym_json, question, llmVal, newRequestBody, url));',
'            ',
'            if(!ins_data_result){return};',
'            if(ins_data_result.code == 500){',
'                print_sys_err_msg(ins_data_result.msg);',
'                return;',
'            }',
'        }else{',
'            return;',
'        }',
'',
'        // console.log(''session_id'', lvSessionId);',
'        // console.log(''nonellmResponse'', noneLLM_response);',
'        if(llmVal == ''NoneLLM''){',
'            feedBack_or_noneLLM_render(ins_data_result, llmVal);',
'        }else{',
'            let likeSelected = ins_data_result.feedback_type === ''good'' ? ''selected'' : '''';',
'            let dislikeSelected = ins_data_result.feedback_type === ''bad'' ? ''selected'' : '''';',
'            let $botDiv = get_ai_response_dom(ins_data_result.chat_id, ins_data_result.ai_created_time, likeSelected, dislikeSelected);',
'            ',
'            let $botStream = $botDiv.find(''.bot-stream'');',
'            ',
'            // SSE message EventListener',
'            let eventSource = new EventSource(`${s_url}/chat/stream_rag?sse_session_id=${lvSessionId}`);',
'            let firstMessageReceived = false;',
'',
'            eventSource.addEventListener(''message'', async (event) => {',
'                lv_sse_result +=  event.data;',
'',
'                if (!firstMessageReceived) {',
'',
'                    firstMessageReceived = true;',
'                    //Remove the corresponding AI animation',
'                    $loadingBubble.remove(); ',
'                    $chatArea.append($botDiv);',
'                    scrollChatToBottom();',
'                    ',
'                    //Display the original question when using synonyms',
'                    if(type == ''synonym''){',
'                        $botStream.append( `Rewrite Question: ${synonym_json.standard_qustion} <br/>`);',
'                    }',
'                }',
'',
'                $botStream.append(event.data);',
'            });',
'',
'            eventSource.addEventListener(''end'', async  (event) => {',
'                if(event.data == ''end''){',
'                    //insert bot response sse',
'                    if(type == ''synonym'') lv_sse_result = `Rewrite Question: ${synonym_json.standard_qustion} <br/>${lv_sse_result}`;',
'                    const ins_sse_result = JSON.parse(await instr_bot_response_sse(ins_data_result.chat_id, lv_sse_result, ins_data_result.history_id));',
'                    if(!ins_sse_result) return;',
'                    //PLSQL error',
'                    if(ins_sse_result.code == 500){',
'                        print_sys_err_msg(ins_sse_result.msg);',
'                        return;',
'                    }',
'',
'                    //show more refrence',
'                    const aiResponseDom = init_kbot_code_generation_showMore(ins_data_result.chat_id, refSource, lv_sse_result, ''sseResponse'');',
'                    $botStream.append(aiResponseDom);',
'                    scrollChatToBottom();',
'                }',
'            });',
'            eventSource.onerror = async (event) => {',
'                eventSource.close();',
'            };',
'        }',
'        ',
'    }else{',
'        print_sys_err_msg(refSource.err_msg);',
'        return;',
'    }',
'}',
'',
'function instr_bot_response_ref(refSource, noneLLM_response, synonym_json, question, llmVal, newRequestBody, url) {',
'    return new Promise((resolve, reject) => {',
'        const requestData = {',
'            response_json: JSON.stringify(refSource),',
'            response_disp: noneLLM_response',
'        };',
'        apex.server.process("INSTR_BOT_RES_REF", {',
'            x01: synonym_json.synonym_status,',
'            x02: synonym_json.synonym_distance,',
'            x03: synonym_json.standard_qustion,',
'            x04: question,',
'            x05: llmVal,',
'            x06: JSON.stringify(newRequestBody),',
'            x07: `${s_url}${url}`,',
'            x08: querySimilarityFlag,',
'            p_clob_01:JSON.stringify(requestData)',
'        }, {',
'            dataType:''text'',',
'            success: function(pData) {',
'                resolve(pData);',
'            },',
'            error: function(jqXHR, textStatus, errorThrown) {',
'                console.error("error", textStatus);',
'                print_sys_err_msg();',
'                reject(''''); ',
'            }',
'        });',
'    });',
'}',
'',
'function instr_bot_response_sse(chatId, answer, historyId) {',
'    return new Promise((resolve, reject) => {',
'        apex.server.process("INSTR_BOT_RES_SSE", {',
'            x01: chatId,',
'            x02: historyId,',
'            p_clob_01: answer,',
'        }, {',
'            dataType:''text'',',
'            success: function(pData) {',
'                resolve(pData); ',
'            },',
'            error: function(jqXHR, textStatus, errorThrown) {',
'                console.error("error", textStatus);',
'                print_sys_err_msg();',
'                reject(''''); ',
'            }',
'        });',
'    });',
'}',
'',
'',
'function get_error_msg_dom(msg){',
'    return $(`<div class="chat-bubble bot">',
unistr('                <div class="avatar">\D83E\DD16</div>'),
'                    <div class="content">',
'                        <div class="message">${msg}</div>',
'                        <div class="timestamp"> ${getLocalTime()} </div>',
'                    </div>',
'            </div>`);',
'}',
'',
'function print_sys_err_msg(msg = null) {',
'    let defaultMsg = langCode === ''zh-cn''',
unistr('        ? ''<div><strong>\7CFB\7EDF\9519\8BEF\FF1A</strong> \51FA\73B0\9519\8BEF\FF0C\8BF7\7A0D\540E\91CD\8BD5.</div>'''),
unistr('        : ''<div><strong>System error\FF1A</strong> An error occurred, please try again later.</div>'';'),
'',
'    let errorMsg = langCode === ''zh-cn''',
unistr('        ? `<div><strong>\7CFB\7EDF\9519\8BEF\FF1A</strong> ${msg || defaultMsg}</div>`'),
unistr('        : `<div><strong>System error\FF1A</strong> ${msg || defaultMsg}</div>`;'),
'',
'    $chatArea.append(get_error_msg_dom(errorMsg));',
'    $loadingBubble.remove(); ',
'    scrollChatToBottom();',
'    isSending = false;',
'}',
'',
'function get_ai_response_dom(chat_id, ai_created_time, likeSelected, dislikeSelected){',
'    return $botDiv = $(',
'            `<div class="chat-bubble bot" data-chat-id=" ${chat_id} ">',
unistr('                <div class="avatar">\D83E\DD16</div>'),
'                <div class="content">',
'                    <div class="message"><span class="bot-stream"></span></div>',
'                    <div class="meta-row">',
'                        <div class="timestamp"> ${ai_created_time} </div>',
'                        <div class="feedback">',
'                            <span class="thumb thumb-up ${likeSelected} "><span class="fa fa-thumbs-up" aria-hidden="true"></span></span>',
'                            <span class="thumb thumb-down ${dislikeSelected} "><span aria-hidden="true" class="fa fa-thumbs-down"></span></span>',
'                        </div>',
'                    </div>',
'                </div>',
'            </div>`',
'        );',
'}',
'',
'',
'async function get_api_source(requestBody,url) {',
'    try {',
'        const response = await axios.post(`${s_url}${url}`, requestBody, {',
'        headers: {',
'            ''Content-Type'': ''application/json'',',
'            ''accept'': ''application/json''',
'        },',
'        timeout: 10000',
'    });',
'    return response.data;',
'',
'    } catch (error) {',
'        if (error.response) {',
'            console.error(''Error data:'', error.response.data); ',
'            console.error(''Status:'', error.response.status);',
'            console.error(''Headers:'', error.response.headers);',
'        } else if (error.request) {',
'            console.error(''No response:'', error.request);',
'        } else {',
'            console.error(''Error:'', error.message);',
'        }',
'        print_sys_err_msg(error.message);',
'        return ''''; ',
'  }',
'}',
'',
'//page init',
'function initChat() {',
'    apex.message.clearErrors();',
'    apex.server.process("LOAD_HISTORY", {',
'        x01: apex.item(P40_KNOWLEDGE_BASE_NAME).getValue()',
'    }, {',
'        dataType:''text'',',
'        success: function(pData) {',
'            let str = JSON.parse(pData);',
'            //Welcome message',
unistr('            let tempMsg = langCode == ''zh-cn''?`\55E8 ${apex.env.APP_USER}\FF0C\5982\679C\60A8\5BF9\77E5\8BC6\5E93"${apex.item(P40_KNOWLEDGE_BASE_NAME).getValue()}"\6709\4EFB\4F55\7591\95EE\FF0C\8BF7\968F\65F6\63D0\95EE\3002\6211\5F88\4E50\610F\4E3A\60A8\63D0\4F9B\5E2E\52A9\FF01\D83D\DE0A`:`Hi ${apex.env.APP_USER}\FF0CIf you have any questions about the knowledge base "${apex.item(P40_KNOW')
||unistr('LEDGE_BASE_NAME).getValue()}", don\2019t hesitate to ask. I\2019m glad to assist!\D83D\DE0A`;'),
'            let $tempMsg = `<div class="chat-bubble bot">',
unistr('                <div class="avatar">\D83E\DD16</div>'),
'                    <div class="content"><div class="message">${tempMsg}</div></div>',
'                </div>`',
'            $chatArea.append($tempMsg);',
'',
'            str.history.forEach(function(row) {',
'                $chatArea.append(',
'                    `<div class="chat-bubble user">',
'                        <div class="avatar"><span class ="avatar-user"> ${apex.env.APP_USER} </span></div>',
'                        <div class="content">',
'                            <div class="message"> ${row.user_prompt} </div><div class="timestamp"> ${row.user_created_time} </div>',
'                        </div> ',
'                    </div>`',
'                );',
'',
'                // set selected class',
'                let likeSelected = row.feedback_type === ''good'' ? ''selected'' : '''';',
'                let dislikeSelected = row.feedback_type === ''bad'' ? ''selected'' : '''';',
'                let aiResponseDom = ',
'                    `<div class="chat-bubble bot" data-chat-id=" ${row.chat_id} ">',
unistr('                        <div class="avatar">\D83E\DD16</div>'),
'                        <div class="content">',
'                    <div class="message">`;',
'                // JSON null check',
'                if(row.bot_response){',
'                    let answerStr = JSON.parse(row.bot_response);',
'                    if(answerStr.status == ''success''){',
'                        //Normal kbot output',
'                        if(row.model_name !== ''NoneLLM''){',
'                            aiResponseDom = aiResponseDom + init_kbot_code_generation_showMore(row.chat_id, answerStr, row.response, ''init'');',
'                        }else{',
'                            if(row.response){',
'                                aiResponseDom = aiResponseDom + row.response + show_noneLLM_download(answerStr);',
'                            }',
'                        }',
'                        ',
'                    }else{',
'                        //Retrieve kbot error information',
'                        aiResponseDom = aiResponseDom + kbot_response_error(answerStr.err_msg);',
'                    }  ',
'                }else{',
'                    //Retrieve PLSQL error information',
'                    aiResponseDom = aiResponseDom + kbot_response_error(row.response);',
'                }',
'                aiResponseDom = `${aiResponseDom} </div><div class="meta-row">',
'                                    <div class="timestamp"> ${row.ai_created_time} </div>',
'                                    <div class="feedback">',
'                                        <span class="thumb thumb-up ${likeSelected} "><span class="fa fa-thumbs-up" aria-hidden="true"></span></span>',
'                                        <span class="thumb thumb-down ${dislikeSelected} "><span aria-hidden="true" class="fa fa-thumbs-down"></span></span>',
'                                    </div>',
'                                </div>',
'                            </div>',
'                        </div>`; ',
'                $chatArea.append(aiResponseDom);',
'            });',
'            scrollChatToBottom();',
'        },',
'        error: function (jqXHR, textStatus, errorThrown) {',
'            console.error("error", textStatus);',
'            print_sys_err_msg();',
'        }',
'    });',
'}',
'',
'// kbot response error',
'function kbot_response_error(value){',
unistr('    let errorMsg = langCode == ''zh-cn''?`<strong>\7CFB\7EDF\9519\8BEF\FF1A</strong><span style="color:#870505">"${value}"</span>`:`<strong>System error\FF1A</strong><span style="color:#870505">"${value}"</span>`;'),
'    return errorMsg;',
'',
'}',
'// kbot respone success',
'function init_kbot_code_generation_showMore(chat_id, valueJson, valueText, type){',
'    let aiResponseDom = '''';',
'    valueJson.data.forEach((item, index) => {',
'        if(index == 0){',
'             // answer',
'            if(type == ''init''){',
'                aiResponseDom = aiResponseDom + valueText;',
'            }',
'        }else{',
'            // answer ref',
'            if(index == 1){',
unistr('                aiResponseDom = `${aiResponseDom} <div class="showMoreClass"><a class="moreLink" id="a_${chat_id}" onclick="showMore(this, ${chat_id});return false;" href="#">>> ${langCode == ''zh-cn''?''\663E\793A\66F4\591A'':''Show more''}</a><div class="moreDiv" style=')
||'"display:none;" id="${chat_id}"><ul>`;',
'            }',
'            aiResponseDom = `${aiResponseDom} <li class="super"> ${item.content}`;',
'            // answer ref url and page num',
'            if(item.source){',
unistr('                aiResponseDom = `${aiResponseDom} <br/><span class="refFileSpan" >[<a  class="refFileA" href="${item.source}" target="_blank"> ${langCode == ''zh-cn''?''\4E0B\8F7D'':''Download''} </a>]  | </span>`;'),
unistr('                aiResponseDom = `${aiResponseDom} <span class="refFileSpan" >[<a  class="refFileA"  onclick="viewSource(''${item.viewer_source}'')" target="_blank"> ${langCode == ''zh-cn''?''\67E5\770B\6E90\6587\4EF6'':''View source''} - ${langCode == ''zh-cn''?''\9875\7801'':''PageNum''}:${')
||'item.page_num} ]</span></a></span>`;',
'            }',
'            aiResponseDom = `${aiResponseDom}</li>`;',
'            if(valueJson.data.length - 1 == index){',
'                aiResponseDom = `${aiResponseDom}</ul></div></div>`;',
'            }',
'        }',
'    });',
'    return aiResponseDom;',
'}',
'',
'function viewSource(url){',
'    apex.server.process("GET_VIEW_SOURCE_URL", {',
'        x01: url',
'    }, {',
'         dataType: "text",',
'        success: function(pData) {',
'           apex.navigation.redirect(pData);',
'        }',
'    });',
'}',
'',
'//Get local time',
'function getLocalTime() {',
'    const now = new Date();',
'',
'    const year = now.getFullYear();',
'    const month = String(now.getMonth() + 1).padStart(2, ''0'');',
'    const day = String(now.getDate()).padStart(2, ''0'');',
'    ',
'    const hours = String(now.getHours()).padStart(2, ''0'');',
'    const minutes = String(now.getMinutes()).padStart(2, ''0'');',
'    const seconds = String(now.getSeconds()).padStart(2, ''0'');',
'    ',
'    return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;',
'}',
'',
'//Rag page switching',
'function redirect_page(pageid, kbname, resValue){',
'    apex.server.process(''GET_RAG_URL'',{',
'            x01: pageid,',
'            x02: kbname,',
'            x03: resValue',
'        },',
'        {',
'            dataType: "text",',
'            success: function (pData) {           ',
'                apex.navigation.redirect(pData);',
'            }             ',
'        }',
'    )',
'}',
'',
'function showMore(o, id) {',
'    let divID = "div#" + id;',
'    if ($(divID).is(":hidden")) {',
'        $(divID).show(100);',
'        if(langCode == ''zh-cn''){',
unistr('            $(o).html(''>> \9690\85CF'');'),
'        }else{',
'            $(o).html(''>> Show Less'');',
'        }',
'    } else {',
'        $(divID).hide(100);',
'        if(langCode == ''zh-cn''){',
unistr('            $(o).html(''>> \663E\793A\66F4\591A'');'),
'        }else{',
'            $(o).html(''>> Show More'');',
'        }',
'    }',
'}',
'',
'// save chat profile',
'function saveProfile(){',
unistr('    let cMsg = langCode == ''zh-cn''?''\53C2\6570\5305\542B\7279\6B8A\5B57\7B26'':''Parameters contain special characters'';'),
'    apex.message.clearErrors();',
'    if(jsCheck(''P40_PROFILE_NAME'', apex.item(P40_PROFILE_NAME).getValue(), cMsg)||jsCheck(''P40_PROFILE_DESCRIPTION'', apex.item(P40_PROFILE_DESCRIPTION).getValue(), cMsg)){',
'        return true;',
'    };',
