unistr('            apex.message.showErrors([{ type: "error", location: [ "page", "inline" ], pageItem: "P40_PROFILE_NAME", message: ''\3010\914D\7F6E\540D\79F0\3011\4E0D\80FD\4E3A\7A7A.'', unsafe: false}]);'),
'        }else{',
unistr('            apex.message.showErrors([{ type: "error", location: [ "page", "inline" ], pageItem: "P40_PROFILE_NAME", message: ''\3010Profile Name\3011 cannot be empty.'', unsafe: false}]);'),
'        }    ',
'        return;',
'    }',
'    apex.server.process( "SAVE_PROFILE", {',
'        pageItems: ["P40_PROFILE_NAME", "P40_PROFILE_DESCRIPTION", "P40_MODEL", "P40_PROMPT_NAME", "P40_QUERYSIMILARITY_FLAG", "P40_SEARCH_TYPE", "P40_VECTOR_STORE_LIMIT", "P40_RERANKER_MODEL", "P40_RERANKER_TOPK", "P40_SCORE_THRESHOLD", "P40_SUMMARY'
||'"]',
'    }, {',
'        dataType:''text''',
'        ,success: function( data )  {',
'            if(data.trim().length == 0){',
'                if(langCode == ''zh-cn''){',
unistr('                    apex.message.showPageSuccess( ''\804A\5929\914D\7F6E\6587\4EF6\5DF2\6210\529F\4FDD\5B58.'');'),
'                }else{',
'                    apex.message.showPageSuccess( ''Chat profile saved successfully.'' );',
'                }',
'                apex.item(P40_PROFILE).refresh();',
'                $("#SaveProfilesStatic").dialog("close");',
'            }else{',
'                apex.message.showErrors([{ type: "error", location: "page", message: data, unsafe: false}]);',
'            }',
'        },',
'        error: function( jqXHR, textStatus, errorThrown ) {',
'            // handle error',
'            apex.message.showErrors([{ type: "error", location: "page", message: textStatus, unsafe: false}]);',
'        }',
'    } );',
'}',
'',
unistr('// save fb(good\3001bad\3001cancel)'),
'function saveFeedback(chatId, type, reason, thisDom, thisPDom) {',
'    apex.message.clearErrors();',
'    apex.server.process(''SAVE_FEEDBACK'', {',
'        x01: chatId,',
'        x02: type,',
'        x03: reason',
'    },{',
'        dataType:''text'',',
'        success: function (pData) {',
'            if(pData == 0){',
'                // error',
'                apex.message.showErrors([{ type: "error", location: "page", message: ''feedback error'', unsafe: false}]);',
'            }else if(pData == 1){',
'                // selected feedback',
'                thisPDom.find(''.thumb'').removeClass(''selected'');',
'                thisDom.addClass(''selected'');',
'            }else if(pData == 2){',
'                // bad cancel',
'                thisPDom.find(''.thumb'').removeClass(''selected'');',
'            }else{',
'                // good cancel',
'                $("#chat-area").empty();',
'                initChat();',
'            }',
'        },',
'        error: function (jqXHR, textStatus, errorThrown) {',
'            console.error("error", textStatus);',
'            apex.message.showErrors([{ type: "error", location: "page", message: textStatus, unsafe: false}]);',
'      }',
'    }',
'  );',
'}',
'',
'',
'// Scroll to the bottom of the page',
'function scrollChatToBottom() {',
'    $chatArea.scrollTop($chatArea[0].scrollHeight);',
'}',
'',
'',
'//get llm model',
'function get_model(){',
'    apex.message.clearErrors();',
'    axios.get(`${s_url}/chat/list_LLMs`, {',
'        timeout: 5000',
'        },{',
'            headers: {',
'            ''accept'': ''application/json''',
'        }',
'    }).then(response => {',
'        var select = apex.item(P40_MODEL).node;',
'        response.data.data.sort();',
'        response.data.data.forEach((item, index) => {',
'            if(index == 0){',
'                select.options.length = 0; ',
'            }',
'            var newOption = new Option(item, item);',
'',
'            select.add(newOption);',
'        });',
'        if(apex.item(P40_PROFILE_TEMP_MODEL).getValue()){',
'            apex.item(P40_MODEL).setValue(apex.item(P40_PROFILE_TEMP_MODEL).getValue(), apex.item(P40_PROFILE_TEMP_MODEL).getValue(), false);',
'        }else{',
'            apex.item(P40_MODEL).setValue(select.options[0].value, select.options[0].value, false);',
'        }',
'    }).catch(error => {',
'    if (error.code === ''ECONNABORTED'') {',
'        apex.message.showErrors([{ type: "error", location: "page", message: ''Get LLM timeout.'', unsafe: false}]);',
'    } else {',
'        apex.message.showErrors([{ type: "error", location: "page", message: "Other error:"+error.message + ".", unsafe: false}]);',
'    }',
'    });',
'}',
''))
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'$(document).ready(function() {',
'    get_model();',
'    initChat();',
'});',
'',
'$(''#send-btn'').on("click", function (e) {',
'    e.preventDefault();',
'    sendMsg();',
'});',
'$(''#user-input'').on("keypress", function (e) {',
'    if (e.which === 13) {',
'        e.preventDefault();',
'        sendMsg();',
'    }',
'});',
'',
'$(''#chat-area'').on(''click'', ''.thumb'', function () {',
'    $thumb = $(this);',
'    $bubble = $thumb.closest(''.chat-bubble'');',
'    chatId = $bubble.data(''chat-id'');',
'',
'    const isLike = $thumb.hasClass(''thumb-up'');',
'    const isDislike = $thumb.hasClass(''thumb-down'');',
'',
'    if (!chatId) return;',
'',
'    if (isLike) {',
'        saveFeedback(chatId, ''good'', null, $thumb, $bubble);',
'    } else if (isDislike) {',
'        if($thumb.hasClass(''selected'')){',
'            saveFeedback(chatId, ''bad'', null, $thumb, $bubble);',
'        }else{',
'            apex.item(P40_FB_MESSAGE).setValue('''');',
'            $(''#myDialogSelector'').dialog(''open'');',
'      }',
'  }',
'',
unistr('  // UI\FF1A'),
'//   $bubble.find(''.thumb'').removeClass(''selected'');',
'//   $thumb.addClass(''selected'');',
'});',
'',
'',
''))
