'            PROMPT_NAME,',
'            QUERY_SIMILARITY_FLAG,',
'            SEARCH_TYPE,',
'            VECTOR_TOPK,',
'            RERANKER_MODEL,',
'            RERANKER_TOPK,',
'            SCORE_THRESHOLD,',
'            SUMMARY',
'    INTO    :P40_PROFILE_TEMP_MODEL,',
'            :P40_PROMPT_NAME,',
'            :P40_QUERYSIMILARITY_FLAG,',
'            :P40_SEARCH_TYPE,',
'            :P40_VECTOR_STORE_LIMIT,',
