'            :P40_SCORE_THRESHOLD,',
'            :P40_SUMMARY',
'    FROM    KMCHAT_CHAT_USER_PROFILE',
'    WHERE (UPPER(APP_USER) = UPPER(V(''APP_USER'')) OR PROFILE_NAME = ''Sys_Default'')',
'    AND   APP_ID   = V(''APP_ID'')',
'    AND   ID = TO_NUMBER(:P40_PROFILE);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'PROFILE_SETTING'
,p_process_when_type=>'REQUEST_EQUALS_CONDITION'
,p_internal_uid=>85352807262229875
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(148688707928964255)
,p_process_sequence=>20
,p_process_point=>'AFTER_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'init set profile'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    LV_LLM_MODEL       VARCHAR2(400);',
'    LV_CHAT_CATAGORY   VARCHAR2(400);',
'    LV_PROMPT_NAME     VARCHAR2(400);',
'    LV_QUERY_SIMILARITY_FLAG VARCHAR2(400);',
'    LV_SEARCH_TYPE     VARCHAR2(400);',
'    LN_VECTOR_TOPK     NUMBER;',
'    LV_RERANKER_MODEL  VARCHAR2(400);',
'    LN_RERANKER_TOPK   NUMBER;',
'    LN_SCORE_THRESHOLD NUMBER;',
'    LN_HISTORY_K       NUMBER;',
'    lv_url             VARCHAR2(4000);',
'BEGIN',
'    SELECT  LLM_MODEL,',
'            PROMPT_NAME,',
'            QUERY_SIMILARITY_FLAG,',
'            SEARCH_TYPE,',
'            VECTOR_TOPK,',
'            RERANKER_MODEL,',
'            RERANKER_TOPK,',
'            SCORE_THRESHOLD,',
'            SUMMARY',
'    INTO    :P40_PROFILE_TEMP_MODEL,',
'            :P40_PROMPT_NAME,',
'            :P40_QUERYSIMILARITY_FLAG,',
'            :P40_SEARCH_TYPE,',
'            :P40_VECTOR_STORE_LIMIT,',
'            :P40_RERANKER_MODEL,',
'            :P40_RERANKER_TOPK,',
'            :P40_SCORE_THRESHOLD,',
'            :P40_SUMMARY',
'    FROM    KMCHAT_CHAT_USER_PROFILE',
'    WHERE UPPER(APP_USER) = UPPER(V(''APP_USER''))',
'    AND   APP_ID   = V(''APP_ID'')',
'    and   USER_DEFAULT_PROFILE = ''Y'';',
'    ',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        BEGIN',
'            SELECT  LLM_MODEL,',
'                    PROMPT_NAME,',
'                    QUERY_SIMILARITY_FLAG,',
'                    SEARCH_TYPE,',
'                    VECTOR_TOPK,',
'                    RERANKER_MODEL,',
'                    RERANKER_TOPK,',
'                    SCORE_THRESHOLD,',
'                    SUMMARY',
'            INTO    :P40_PROFILE_TEMP_MODEL,',
'                    :P40_PROMPT_NAME,',
'                    :P40_QUERYSIMILARITY_FLAG,',
'                    :P40_SEARCH_TYPE,',
'                    :P40_VECTOR_STORE_LIMIT,',
'                    :P40_RERANKER_MODEL,',
'                    :P40_RERANKER_TOPK,',
'                    :P40_SCORE_THRESHOLD,',
'                    :P40_SUMMARY',
'            FROM    KMCHAT_CHAT_USER_PROFILE',
'            WHERE   APP_ID   = V(''APP_ID'')',
'            and   PROFILE_NAME = ''Sys_Default'';',
'        EXCEPTION',
'            WHEN OTHERS THEN',
'                NULL;',
'        END;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'init'
,p_process_when_type=>'REQUEST_EQUALS_CONDITION'
,p_internal_uid=>85353291365229876
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(148687882763964254)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Clean History'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_clob 	        CLOB;',
'    l_server        VARCHAR2(4000);',
'BEGIN',
'    --  clear',
'    SELECT S_URL INTO l_server FROM KMCHAT_KB_SERVER WHERE S_NAME = ''SERVER'' AND APP_ID = V(''APP_ID''); ',
'',
'    apex_web_service.g_request_headers.delete();',
'    apex_web_service.g_request_headers(1).name  := ''accept'';',
'    apex_web_service.g_request_headers(1).value := ''application/json'';',
'    apex_web_service.g_request_headers(2).name  := ''Content-Type'';',
'    apex_web_service.g_request_headers(2).value := ''application/json''; ',
'    l_clob := apex_web_service.make_rest_request(',
'            p_url => l_server||''/chat/clear_disable_memory_rag_history'',',
'            p_http_method => ''POST'',',
'            p_body => ''{',
'               "user": "''||:APP_USER||''",',
'               "kb_name" : "''||:P40_KNOWLEDGE_BASE_NAME||''",',
'               "llm_model":"''||:P40_MODEL||''"',
'               }',
'               ''',
'        );',
'',
'    delete from kmchat_kb_riva where id in (',
'    select r.id',
'    from KMCHAT_kb_RIVA r connect by prior r.id=r.parent_id',
'    start with upper(r.appuser) = :APP_USER and r.app_id = V(''APP_ID'') and r.chat_type = ''Chat RAG'' and r.kb_name = :P40_KNOWLEDGE_BASE_NAME',
'    );',
'    commit;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(148678380135964232)
,p_internal_uid=>85352466200229875
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(147500558963937492)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'INSTR_BOT_RES_FB'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    ln_user_id                NUMBER;',
'    ln_ai_id                  NUMBER;',
'    lv_server_url             VARCHAR2(4000) := ''feedback'';',
'    lv_question               kmchat_kb_riva.TEXT_JSON%TYPE := apex_application.g_x01;',
'    lv_json_question          kmchat_kb_riva.TEXT_JSON%TYPE := apex_application.g_x02;',
'    lv_model_name             VARCHAR2(400) := apex_application.g_x03;',
'    lv_syn_status            VARCHAR2(1);',
'    ln_synonym_similarity_threshold NUMBER;',
'    lc_vector                vector;',
'    lv_txt_embedding_status  VARCHAR2(400);',
'    ln_syn_distance          NUMBER;',
'    lv_standard_question     VARCHAR2(4000);',
'    ln_query_similarity_threshold NUMBER;',
'    lc_fb_answer_JSON        CLOB;',
'    ln_distance              NUMBER;',
'    ln_feedback_id           NUMBER;',
'    ld_ai_create_date        DATE;',
'    lc_fb_answer             CLOB;',
'    lv_prompt_name           VARCHAR2(400);',
'    j                        apex_json.t_values;',
'    lv_kb_name               VARCHAR2(400);',
'    lv_querySimilarityFlag   VARCHAR2(200) :=  apex_application.g_x04;',
'BEGIN',
'--',
'    apex_json.parse(j, lv_json_question);',
'    lv_kb_name := apex_json.get_varchar2(p_values => j, p_path => ''kb_name'');',
'    ',
'    IF lv_model_name = ''NoneLLM'' THEN',
'        lv_prompt_name := NULL;',
'    ELSE',
'        lv_prompt_name := apex_json.get_varchar2(p_values => j, p_path => ''prompt_name'');',
'    END IF;',
'    -- FeedBack Check',
'    IF lv_querySimilarityFlag = ''On'' THEN',
unistr('        -- \95EE\7B54\5411\91CF\5316'),
'        KMCHAT_KB_BASE_PKG.txt_embedding(',
'            iv_kb_name     => lv_kb_name,',
'            iv_text        => lv_question,',
'            ov_text_vector => lc_vector,',
'            ov_status      => lv_txt_embedding_status);',
'',
'        IF lv_txt_embedding_status = ''success'' THEN',
unistr('            -- \83B7\53D6\76F8\4F3C\5EA6\9608\503C'),
'            BEGIN',
'                SELECT value ',
'                INTO   ln_query_similarity_threshold ',
'                FROM   kmchat_kb_dict',
'                WHERE  type=''QUERY_SIMILARITY_THRESHOLD'' ',
'                AND    active_yn = ''Y'' ',
'                AND    app_id = V(''APP_ID'')',
'                ORDER BY SEQ FETCH FIRST 1 ROWS ONLY;',
'            EXCEPTION',
'                WHEN OTHERS THEN',
'                    ln_query_similarity_threshold := 0;',
'            END;',
'            -- vector search',
'            BEGIN',
'                SELECT answer_json,',
'                       ANSWER_DISP,',
'                       VECTOR_DISTANCE(question_vector,lc_vector,COSINE) question_distance,',
'                       id',
'                INTO   lc_fb_answer_JSON,',
'                       lc_fb_answer,',
'                       ln_distance,',
'                       ln_feedback_id',
'                FROM   kmchat_kb_feedback',
'                WHERE  kb_name =  lv_kb_name',
'                AND    llm_model = lv_model_name',
'                -- AND    NVL(chat_catagory,1) = NVL(lv_chat_catagory,1)',
'                AND    NVL(prompt_name,1)   = NVL(lv_prompt_name,1)',
'                AND    app_user             = V(''APP_USER'')',
'                AND    app_id               = V(''APP_ID'')',
'                AND    feedback             = ''good''',
'                AND    chat_type            = ''Chat RAG''',
'                ORDER BY question_distance',
'                FETCH FIRST 1 ROWS ONLY;',
unistr('               -- \9608\503CCheck'),
'',
'                IF ln_distance > ln_query_similarity_threshold OR ln_feedback_id IS NULL THEN',
'                    lc_fb_answer_JSON := NULL;',
'                    lc_fb_answer := NULL;',
'                END IF;',
'            EXCEPTION',
'                WHEN OTHERS THEN',
'                    lc_fb_answer_JSON := NULL;',
'                    ln_feedback_id := NULL;',
'                    ln_distance := NULL;',
'                    lc_fb_answer := NULL;',
'            END;',
'        END IF;  ',
'    END IF;',
'',
'    -- synonyms Check',
'    IF lc_fb_answer_JSON IS NULL THEN',
'        -- Confirm whether synonyms in the knowledge base are enabled.',
'        BEGIN',
'            SELECT status,synonym_similarity_threshold',
'            INTO   lv_syn_status,ln_synonym_similarity_threshold',
'            FROM   kmchat_synonym_conf',
'            WHERE  kb_name = lv_kb_name',
'            AND    app_id = V(''APP_ID'');',
'        EXCEPTION',
'            WHEN OTHERS THEN',
'                lv_syn_status := ''N'';',
'                ln_synonym_similarity_threshold := ''0'';',
'        END;',
'        IF lv_syn_status = ''Y'' THEN',
'            ',
'            IF lv_txt_embedding_status IS NULL THEN ',
'                KMCHAT_KB_BASE_PKG.txt_embedding(',
'                    iv_kb_name     => lv_kb_name,',
'                    iv_text        => lv_question,',
'                    ov_text_vector => lc_vector,',
'                    ov_status      => lv_txt_embedding_status);',
'            END IF;',
'            ',
'            IF lv_txt_embedding_status = ''success'' THEN',
'                BEGIN',
'                    SELECT vector_distance(ksd.synonym_vector,lc_vector,cosine) syn_distance,',
'                           ksm.standard_question',
'                    INTO   ln_syn_distance,',
'                           lv_standard_question',
'                    FROM   kmchat_synonym_conf  ksc,',
'                           kmchat_synonym_master ksm,',
'                           kmchat_synonym_detail ksd',
'                    WHERE ksc.ID = ksm.conf_id',
'                    AND   ksm.ID = ksd.master_id',
'                    AND   ksc.kb_name = lv_kb_name',
'                    AND   ksc.app_id = V(''APP_ID'')',
'                    ORDER BY syn_distance',
'                    FETCH FIRST 1 ROWS ONLY;',
unistr('                    -- \9608\503CCheck'),
'                    IF ln_syn_distance > ln_synonym_similarity_threshold THEN',
'                        lv_standard_question := NULL;',
'                    END IF;',
'                EXCEPTION',
'                    WHEN OTHERS THEN',
'                        lv_standard_question := NULL;',
'                        ln_syn_distance := NULL;',
'                END;',
'            END IF;',
'        END IF;',
'        apex_json.open_object;',
'        apex_json.write(''code'', 404);',
'        apex_json.write(''synonym_status'', lv_syn_status);',
'        apex_json.write(''standard_qustion'', lv_standard_question);',
'        apex_json.write(''synonym_distance'', ln_syn_distance);',
'        ',
'        apex_json.close_object;',
'    ELSE',
'        -- question',
'        ln_user_id := KMCHAT_KB_RIVA_SEQ.nextval;',
'        insert into KMCHAT_KB_RIVA(id, MODEL_NAME, TEXT_DISP, text_json, APPUSER, APP_ID, CREATED_TIME, chat_type, kb_name) values(ln_user_id, lv_model_name, lv_question, lv_json_question, V(''APP_USER''), V(''APP_ID''), current_date, ''Chat RAG'' ,lv_kb_n'
||'ame);',
'        -- answer',
'        ln_ai_id := KMCHAT_KB_RIVA_SEQ.nextval;',
'        ld_ai_create_date := current_date;',
'',
'        INSERT INTO kmchat_kb_riva(id, text_disp, text_json, created_time, appuser, parent_id, url, model_name, app_id, feedback, chat_type,feedback_id, kb_name) ',
'        VALUES(ln_ai_id, lc_fb_answer , lc_fb_answer_JSON, ld_ai_create_date, ''chatbot'', ln_user_id, lv_server_url, lv_model_name , V(''APP_ID''),case when lc_fb_answer_JSON is not null then ''good'' else NULL end, ''Chat RAG'',ln_feedback_id, lv_kb_name);',
'        COMMIT;',
'        -- QA History Instr',
'        INSERT INTO kmchat_kb_qa',
'        (kb_name, llm_model, prompt_name,  question, answer, app_user, create_date, app_id, feedback_id, vector_distance, query_similarity_flag, synonym_status ,synonym_vector_distance, synonym_standard_question, chat_type)',
'        VALUES',
'        (lv_kb_name, lv_model_name, lv_prompt_name, lv_question, lc_fb_answer, V(''APP_USER''), ld_ai_create_date, V(''APP_ID''),ln_feedback_id, ln_distance, lv_querySimilarityFlag, null, null, null, ''Chat RAG''); ',
'        COMMIT;',
'        apex_json.open_object;',
'        apex_json.write(''code'', 200);',
'        apex_json.write(''response'', lc_fb_answer);',
'        apex_json.write(''bot_response'', lc_fb_answer_JSON);',
'        apex_json.write(''chat_id'', ln_ai_id);',
'        apex_json.write(''ai_created_time'',TO_CHAR(ld_ai_create_date,''yyyy-mm-dd hh24:mi:ss''));',
'        apex_json.write(''feedback_type'', case when lc_fb_answer_JSON is not null then ''good'' else NULL end);',
'        apex_json.close_object;',
'    END IF;',
'',
'',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        apex_json.open_object;',
'        apex_json.write(''code'', 500);',
'        apex_json.write(''msg'', lc_fb_answer);',
'        apex_json.close_object;',
'',
'END;',
'',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>84165142400203113
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(148686667756964246)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'INSTR_BOT_RES_REF'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_clob                    CLOB;',
'    l_clob_disp               CLOB;',
'    lv_prompt_name            VARCHAR2(400);',
'    ln_user_id                NUMBER;',
'    ln_ai_id                  NUMBER;',
'    lv_server_url             VARCHAR2(4000) := apex_application.g_x07;',
'    lv_question               kmchat_kb_riva.TEXT_JSON%TYPE := apex_application.g_x04;',
'    lv_json_question          kmchat_kb_riva.TEXT_JSON%TYPE := apex_application.g_x06;',
'    lv_model_name             VARCHAR2(400) := apex_application.g_x05;',
'    lv_kb_name                VARCHAR2(400); ',
'    j                         apex_json.t_values;',
'    k                         apex_json.t_values;',
'    ld_ai_create_date         DATE;',
'    ln_history_id             NUMBER;',
'    lv_querySimilarityFlag   VARCHAR2(200) :=  apex_application.g_x08;',
'BEGIN',
'    apex_json.parse(k, lv_json_question);',
'    lv_kb_name := apex_json.get_varchar2(p_values => k, p_path => ''kb_name'');',
'    IF lv_model_name = ''NoneLLM'' THEN',
'        lv_prompt_name := NULL;',
'    ELSE',
'        lv_prompt_name := apex_json.get_varchar2(p_values => k, p_path => ''prompt_name'');',
'    END IF;  ',
'--',
'    ln_user_id := KMCHAT_KB_RIVA_SEQ.nextval;',
'',
'    insert into KMCHAT_KB_RIVA(id, MODEL_NAME, TEXT_DISP, text_json, APPUSER, APP_ID, CREATED_TIME, chat_type, kb_name) ',
'    values(ln_user_id, apex_application.g_x05, lv_question, lv_json_question, V(''APP_USER''), V(''APP_ID''), current_date, ''Chat RAG'' ,lv_kb_name);',
'    ',
'    COMMIT;',
'',
'    apex_json.parse(j, apex_application.g_clob_01);',
'    ',
'',
'    l_clob := apex_json.get_clob(p_values => j, p_path => ''response_json'');',
'    l_clob_disp := apex_json.get_clob(p_values => j, p_path => ''response_disp'');',
'',
'    ln_ai_id := KMCHAT_KB_RIVA_SEQ.nextval;',
'    ld_ai_create_date := current_date;',
'    INSERT INTO kmchat_kb_riva(id, text_disp, text_json, created_time, appuser, parent_id, url, model_name, app_id, feedback, chat_type, kb_name) ',
'    VALUES(ln_ai_id, l_clob_disp , l_clob, ld_ai_create_date, ''chatbot'', ln_user_id, lv_server_url, apex_application.g_x05, V(''APP_ID''), null, ''Chat RAG'', lv_kb_name);',
'    COMMIT;',
'    -- QA History Instr',
'    INSERT INTO kmchat_kb_qa',
'    (kb_name, llm_model, prompt_name,  question, answer, app_user, create_date, app_id, query_similarity_flag, synonym_status ,synonym_vector_distance, synonym_standard_question, chat_type)',
'    VALUES',
'    (lv_kb_name, apex_application.g_x05, lv_prompt_name, lv_question, l_clob_disp, V(''APP_USER''), ld_ai_create_date, V(''APP_ID''), lv_querySimilarityFlag, apex_application.g_x01, apex_application.g_x02, apex_application.g_x03, ''Chat RAG'') ',
'    RETURNING ID INTO ln_history_id;',
'    COMMIT;',
'',
'    apex_json.open_object;',
'    apex_json.write(''code'', ''200'');',
'    apex_json.write(''response'', l_clob_disp);',
'    apex_json.write(''bot_response'', l_clob);',
'    apex_json.write(''history_id'', ln_history_id);',
'    apex_json.write(''chat_id'', ln_ai_id);',
'    apex_json.write(''ai_created_time'',TO_CHAR(ld_ai_create_date,''yyyy-mm-dd hh24:mi:ss''));',
'    apex_json.write(''feedback_type'', '''');',
'    apex_json.close_object;',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        apex_json.open_object;',
'        apex_json.write(''code'', ''500'');',
'        apex_json.write(''msg'',SQLERRM );',
'        apex_json.close_object;',
'END;',
'',
''))
,p_process_clob_language=>'PLSQL'
