wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(148687077151964253)
,p_process_sequence=>40
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'LOAD_HISTORY'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'  apex_json.open_object;',
'  apex_json.open_array(''history'');',
'',
'  FOR rec IN (select  a.TEXT_DISP       as question',
'                    , b.MODEL_NAME      as model_name',
'                    , to_char(a.CREATED_TIME,''yyyy-mm-dd hh24:mi:ss'')    as question_date',
'                    , b.id, b.TEXT_DISP as answer',
'                    , b.TEXT_JSON       as answer_json',
'                    , to_char(b.CREATED_TIME,''yyyy-mm-dd hh24:mi:ss'')     as answer_data',
'                    , b.FEEDBACK',
'                from kmchat_kb_riva a,',
'                     kmchat_kb_riva b',
'                where a.id = b.PARENT_ID',
'                and   a.appuser = V(''APP_USER'')',
'                and   a.app_id =  V(''APP_ID'')',
'                and   a.CHAT_TYPE = ''Chat RAG''',
'                and   a.kb_name  = apex_application.g_x01',
'                ORDER BY a.CREATED_TIME asc',
'  ) LOOP',
'    apex_json.open_object;',
'    apex_json.write(''feedback_type'', rec.FEEDBACK);',
'    apex_json.write(''model_name'', rec.model_name);',
'    apex_json.write(''user_prompt'', rec.question);',
'    apex_json.write(''response'', rec.answer);',
'    apex_json.write(''bot_response'', rec.answer_json);',
'    apex_json.write(''user_created_time'', rec.question_date);',
'    apex_json.write(''ai_created_time'', rec.answer_data);',
'    apex_json.write(''chat_id'', rec.id);',
'    apex_json.close_object;',
'  END LOOP;',
'',
'  apex_json.close_array;',
'  apex_json.close_object;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>85351660588229874
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(148687443972964254)
,p_process_sequence=>50
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SAVE_FEEDBACK'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_chat_id      NUMBER := APEX_APPLICATION.G_X01;',
'    l_type         VARCHAR2(10) := APEX_APPLICATION.G_X02; -- ''LIKE'' or ''DISLIKE''',
'    l_reason       VARCHAR2(4000) := APEX_APPLICATION.G_X03;',
'    l_id             NUMBER;',
'    ln_p_id          NUMBER;',
'    lc_answer        CLOB;',
'    lv_ques          VARCHAR2(4000);',
'    lc_JSON          CLOB;',
'    j                apex_json.t_values;',
'    lv_kb_name       VARCHAR2(4000);',
'    lv_model         VARCHAR2(4000);',
'    lv_prompt_name   VARCHAR2(4000);',
'    lj_more_param    VARCHAR2(4000);',
'    lv_chat_catagory VARCHAR2(4000) := NULL;',
'    lc_answer_json   CLOB;',
'    lv_server        VARCHAR2(400);',
'    l_clob           CLOB;',
'    l_vector         VECTOR;',
'    lv_txt_embedding_status VARCHAR2(4000);',
'    lv_search_type   VARCHAR2(400);',
'    ln_feedback_id   NUMBER;',
'    lv_feedback      VARCHAR2(100);',
'BEGIN',
'--',
'    SELECT A.text_disp,A.text_JSON,B.text_disp,B.text_json,b.feedback,B.feedback_id',
'    INTO   lv_ques,lc_JSON,lc_answer,lc_answer_json,lv_feedback,ln_feedback_id',
'    FROM   kmchat_kb_riva A,',
'           kmchat_kb_riva B ',
'    WHERE  A.ID = B.parent_id ',
'    AND    B.ID = l_chat_id;',
'',
'    IF ln_feedback_id IS NOT NULL AND lv_feedback = l_type THEN',
'        UPDATE kmchat_kb_riva SET feedback = NULL AND feedback_id = NULL WHERE feedback_id = ln_feedback_id;',
'        DELETE kmchat_kb_feedback WHERE id = ln_feedback_id;',
'        IF lv_feedback = ''good'' THEN',
'            htp.p(''3'');',
'        ELSE',
'            htp.p(''2'');',
'        END IF;',
'    ELSE',
'        -- APEX_DEBUG.WARN(''uncancel'');',
'        -- Feedback is null',
'        apex_json.parse(j,lc_JSON);',
'        lv_kb_name := apex_json.get_varchar2(p_path=>''kb_name'',p_values=>j);',
'        lv_model := NVL(apex_json.get_varchar2(p_path=>''llm_model'',p_values=>j),''NoneLLM'');',
'        lv_prompt_name := apex_json.get_varchar2(p_path=>''prompt_name'',p_values=>j);',
'            ',
'        lj_more_param := ''{'';',
'        IF apex_json.get_varchar2(p_path=>''vector_store_limit'',p_values=>j) IS NOT NULL THEN',
'            lj_more_param := lj_more_param||''',
'                "vector_topk" : "''||apex_json.get_varchar2(p_path=>''vector_store_limit'',p_values=>j)||''"',
'            '';',
'        END IF;',
'',
'        IF apex_json.get_varchar2(p_path=>''search_type'',p_values=>j) IS NOT NULL THEN',
'            lj_more_param := lj_more_param||'',"search_type" : "''||apex_json.get_varchar2(p_path=>''search_type'',p_values=>j)||''"',
'            '';',
'        END IF;',
'            ',
'        IF apex_json.get_varchar2(p_path=>''summary_flag'',p_values=>j) IS NOT NULL THEN',
'            lj_more_param := lj_more_param||'',"summary_flag" : "''||apex_json.get_varchar2(p_path=>''summary_flag'',p_values=>j)||''"',
'            '';',
'        END IF;',
'',
'        IF apex_json.get_varchar2(p_path=>''rerankerModel'',p_values=>j) IS NOT NULL THEN',
'            lj_more_param := lj_more_param||'',"rerankerModel" : "''||apex_json.get_varchar2(p_path=>''rerankerModel'',p_values=>j)||''"',
'            '';',
'        END IF;',
'',
'        IF apex_json.get_varchar2(p_path=>''reranker_topk'',p_values=>j) IS NOT NULL THEN',
'            lj_more_param := lj_more_param||'',"reranker_topk" : "''||apex_json.get_varchar2(p_path=>''reranker_topk'',p_values=>j)||''"',
'            '';',
'        END IF;',
'',
'        IF apex_json.get_varchar2(p_path=>''score_threshold'',p_values=>j) IS NOT NULL THEN',
'            lj_more_param := lj_more_param||'',"score_threshold" : "''||apex_json.get_varchar2(p_path=>''score_threshold'',p_values=>j)||''"',
'            '';',
'        END IF;',
'',
'        -- IF apex_json.get_varchar2(p_path=>''history_k'',p_values=>j) IS NOT NULL THEN',
'        --     lj_more_param := lj_more_param||'',"history_k" : "''||apex_json.get_varchar2(p_path=>''history_k'',p_values=>j)||''"',
'        --     '';',
'        --     lv_chat_catagory := ''Enable Memory Chat'';',
'        -- ELSE',
'        --     IF lv_model != ''NoneLLM'' THEN',
'        --         lv_chat_catagory := ''Disable Memory Chat'';',
'        --     END IF;',
'        -- END IF;',
'',
'        lj_more_param := lj_more_param || ''}'';',
'',
'        KMCHAT_KB_BASE_PKG.txt_embedding(',
'            iv_kb_name     => lv_kb_name,',
'            iv_text        => lv_ques,',
'            ov_text_vector => l_vector,',
'            ov_status      => lv_txt_embedding_status);',
'',
'        IF lv_txt_embedding_status = ''success'' THEN',
'    --',
'            IF ln_feedback_id IS NOT NULL THEN',
'                DELETE kmchat_kb_feedback WHERE id = ln_feedback_id;',
'            END IF;',
'    --',
'            INSERT INTO kmchat_kb_feedback(kb_name, llm_model, chat_catagory, prompt_name, more_param, feedback, feedback_reason, question, question_vector, answer_disp, answer_json, chat_type, app_user, create_date, app_id) ',
'            VALUES(',
'                lv_kb_name,',
'                lv_model,',
'                lv_chat_catagory,',
'                lv_prompt_name,',
'                lj_more_param,',
'                l_type,',
'                l_reason,',
'                lv_ques,',
'                to_vector(l_vector),',
'                lc_answer,',
'                lc_answer_json,',
'                ''Chat RAG'',',
'                V(''APP_USER''),',
'                current_date,',
'                V(''APP_ID'')',
'            )RETURNING ID INTO ln_feedback_id;',
'',
'            ',
'            UPDATE  kmchat_kb_riva',
'            SET     feedback_id = ln_feedback_id',
'            ,       feedback = l_type ',
'            WHERE   id    = l_chat_id;',
'            COMMIT;',
'    --',
'            htp.p(''1'');',
'        ELSE',
unistr('            -- kbot\5411\91CF\5316\9519\8BEF'),
'            htp.p(''0''); ',
'        END IF;',
'    END IF;',
'--',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        rollback;',
'        htp.p(''0:'');  ',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>85352027409229875
);
