wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(5877399465818674)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'save prompt'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_prompt_id number;',
'BEGIN',
'    IF :P41_PROMPT_ID IS NULL THEN',
'        INSERT INTO KBOT_MD_PROMPT',
'        (APP_ID, DOMAIN_ID, NAME, PROMPT_UNIQUE_NAME , PROMPT_CATEGORY, TEMPLATE, STATUS, CREATED_BY, CREATED_TIME, UPDATED_BY, UPDATED_TIME)',
'        VALUES',
'        (:APP_ID, :P41_DOMAIN_ID, :P41_PROMPT_NAME, ''AGENT''||trunc((SYSDATE - TO_DATE(''1970-01-01'', ''YYYY-MM-DD'')) * 24 * 60 * 60) ||''/''||:P41_PROMPT_NAME, 3, :P41_PROMPT_CONTENT, 1, :APP_USER, CURRENT_DATE, :APP_USER, CURRENT_DATE)',
'        RETURNING PROMPT_ID INTO l_prompt_id;',
'',
'        UPDATE KBOT_MD_AGENT',
'        SET PROMPT_ID = l_prompt_id',
'           ,UPDATED_BY = :APP_USER',
'           ,UPDATED_TIME = CURRENT_DATE',
'        WHERE AGENT_ID = :P41_AGENT_ID;',
'',
'        DECLARE',
'            l_agent_name VARCHAR2(400);',
'        BEGIN',
'            SELECT AGENT_NAME INTO l_agent_name FROM KBOT_MD_AGENT WHERE AGENT_ID = :P41_AGENT_ID;',
'            kbot_md_ui_utl.ins_action_record(',
'                iv_func_name => ''Agent Config'',',
'                iv_action    => ''Insert Agent Prompt completed (Agent name: '' || l_agent_name || '', Prompt Name: '' || :P41_PROMPT_NAME || '').''',
'            );',
'        EXCEPTION',
'            WHEN OTHERS THEN',
'                NULL;',
'        END;',
'    ELSE',
'        UPDATE KBOT_MD_PROMPT',
'        SET NAME = :P41_PROMPT_NAME',
'           ,TEMPLATE = :P41_PROMPT_CONTENT',
'           ,PROMPT_UNIQUE_NAME = ''AGENT''||trunc((SYSDATE - TO_DATE(''1970-01-01'', ''YYYY-MM-DD'')) * 24 * 60 * 60)||''/''||:P41_PROMPT_NAME',
'           ,UPDATED_BY = :APP_USER',
'           ,UPDATED_TIME = CURRENT_DATE',
'        WHERE PROMPT_ID = :P41_PROMPT_ID;',
'',
'        DECLARE',
'            l_agent_name VARCHAR2(400);',
'        BEGIN',
'            SELECT AGENT_NAME INTO l_agent_name FROM KBOT_MD_AGENT WHERE AGENT_ID = :P41_AGENT_ID;',
'            kbot_md_ui_utl.ins_action_record(',
'                iv_func_name => ''Agent Config'',',
'                iv_action    => ''Update Agent Prompt completed (Agent name: '' || l_agent_name || '', Prompt Name: '' || :P41_PROMPT_NAME || '').''',
'            );',
'        EXCEPTION',
'            WHEN OTHERS THEN',
'                NULL;',
'        END;',
'',
'    END IF;',
'    COMMIT;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(5739026753214185)
,p_process_success_message=>'Save completed.'
,p_internal_uid=>10389466069394824
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(5877236693818673)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SAVE_PROMPT'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_tool_id   number;',
'    l_prompt_id number;',
'BEGIN',
'    IF :P41_PROMPT_ID IS NULL THEN',
'        INSERT INTO KBOT_MD_PROMPT',
'        (APP_ID, DOMAIN_ID, NAME, PROMPT_UNIQUE_NAME, PROMPT_CATEGORY, TEMPLATE, STATUS, CREATED_BY, CREATED_TIME, UPDATED_BY, UPDATED_TIME)',
'        VALUES',
'        (:APP_ID, :P41_DOMAIN_ID, :P41_PROMPT_NAME, ''KBOT''||:APP_ID||''/''||:P41_PROMPT_NAME, 3, apex_application.g_clob_01, 1, :APP_USER, CURRENT_DATE, :APP_USER, CURRENT_DATE)',
'        RETURNING PROMPT_ID INTO l_prompt_id;',
'',
'        UPDATE KBOT_MD_AGENT',
'        SET PROMPT_ID = l_prompt_id',
'           ,UPDATED_BY = :APP_USER',
'           ,UPDATED_TIME = CURRENT_DATE',
'        WHERE AGENT_ID = :P41_AGENT_ID;',
'    ELSE',
'        UPDATE KBOT_MD_PROMPT',
'        SET NAME = :P41_PROMPT_NAME',
'           ,TEMPLATE = apex_application.g_clob_01',
'           ,PROMPT_UNIQUE_NAME = ''KBOT''||:APP_ID||''/''||:P41_PROMPT_NAME',
'           ,UPDATED_BY = :APP_USER',
'           ,UPDATED_TIME = CURRENT_DATE',
'        WHERE PROMPT_ID = :P41_PROMPT_ID;',
'    END IF;',
'    COMMIT;',
'    ',
'    apex_json.open_object();',
'    apex_json.write(''code'', ''200'');',
'    apex_json.write(''msg'', ''Save completed.'');  ',
'    apex_json.close_all();',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        apex_json.open_object();',
'        apex_json.write(''code'', SQLCODE);',
'        apex_json.write(''msg'', SQLERRM); ',
'        apex_json.close_all(); ',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>10389303297394823
);
end;
