wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(6651234410022573)
,p_computation_sequence=>10
,p_computation_item=>'P43_MODEL_PARAMS'
,p_computation_type=>'FUNCTION_BODY'
,p_computation_language=>'PLSQL'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_json clob;',
'    l_has_data BOOLEAN := FALSE;',
'BEGIN',
'    apex_json.initialize_clob_output;',
'    apex_json.open_object;',
'    ',
'    IF :P43_TEMPERATURE IS NOT NULL THEN',
'        apex_json.write(''temperature'', :P43_TEMPERATURE);',
'        l_has_data := TRUE;',
'    END IF;',
'',
'    IF :P43_MAX_TOKENS IS NOT NULL THEN',
'        apex_json.write(''max_tokens'', :P43_MAX_TOKENS);',
'        l_has_data := TRUE;',
'    END IF;',
'',
'    IF :P43_MODEL_PATH IS NOT NULL THEN',
'        apex_json.write(''model_path'', :P43_MODEL_PATH);',
'        l_has_data := TRUE;',
'    END IF;',
'',
'    IF :P43_BATCH_SIZE IS NOT NULL THEN',
'        apex_json.write(''batch_size'', :P43_BATCH_SIZE);',
'        l_has_data := TRUE;',
'    END IF;',
'    ',
'    IF :P43_PROVIDER = ''oci'' THEN',
'        apex_json.open_object(''config_file'');',
'        apex_json.write(''user'', :P43_OCI_USER_ID);',
'        apex_json.write(''fingerprint'', :P43_OCI_FINGERPRINT);',
'        apex_json.write(''tenancy'', :P43_OCI_TENANCY_ID);',
'        apex_json.write(''region'', :P43_OCI_REGION);',
unistr('        apex_json.write(''key_content'', :P43_OCI_PRIVATE_KEY); -- \81EA\52A8\5904\7406\6362\884C\7B26'),
'        apex_json.close_object;',
'        ',
'        apex_json.write(''compartment_id'', :P43_OCI_COMPARTMENT_ID);',
'        l_has_data := TRUE;',
'    END IF;',
'    ',
'    apex_json.close_object;',
'    ',
'    l_json := apex_json.get_clob_output;',
'    apex_json.free_output;',
'    ',
unistr('    -- \5982\679C\6CA1\6709\5199\5165\4EFB\4F55\6570\636E\FF0C\5219\8FD4\56DENULL'),
'    IF NOT l_has_data THEN',
'        RETURN NULL;',
'    END IF;',
'    ',
'    RETURN l_json;',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        apex_json.free_output;',
'        RAISE;',
'END;'))
,p_compute_when=>':REQUEST IN (''CREATE'', ''SAVE'')'
,p_compute_when_text=>'PLSQL'
,p_compute_when_type=>'EXPRESSION'
);
