'BEGIN',
'    kbot_md_ui_utl.ins_action_record(',
'        iv_func_name => ''Business Domain'',',
'        iv_action    => INITCAP(CASE :REQUEST WHEN ''SAVE'' THEN ''UPDATE'' ELSE :REQUEST END) || '' Data['' || :P45_NAME || ''] completed.''',
'    );',
'    -- Delete chat history',
'    IF :REQUEST = ''DELETE'' THEN',
'        FOR rec_data IN (SELECT agent_id from KBOT_MD_AGENT where domain_Id = :P45_DOMAIN_ID)LOOP',
'            DELETE KBOT_MD_CHAT_SESSION WHERE AGENT_ID = rec_data.agent_id;',
'            DELETE KBOT_MD_CHAT_HISTORY WHERE AGENT_ID = rec_data.agent_id;',
'        END LOOP;',
'    END IF;',
'END;'))
