wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(4469691781359275)
,p_computation_sequence=>110
,p_computation_item=>'P46_CHUNK_PARSER'
,p_computation_type=>'FUNCTION_BODY'
,p_computation_language=>'PLSQL'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_json clob;',
'    l_has_content boolean := false;',
'BEGIN',
'    l_json := ''{'';',
'    ',
'    IF :P46_SPLIT_STRATEGY IS NOT NULL THEN',
'        l_json := l_json || ''"split_strategy":'' || :P46_SPLIT_STRATEGY;',
'        l_has_content := true;',
'    END IF;',
'',
'    IF :P46_CHUNK_SIZE IS NOT NULL THEN',
'        IF l_has_content THEN',
'            l_json := l_json || '','';',
'        END IF;',
'        l_json := l_json || ''"chunk_size":'' || :P46_CHUNK_SIZE;',
'        l_has_content := true;',
'    END IF;',
'',
'    IF :P46_CHUNK_OVERLAP IS NOT NULL THEN',
'        IF l_has_content THEN',
'            l_json := l_json || '','';',
'        END IF;',
'        l_json := l_json || ''"chunk_overlap":'' || :P46_CHUNK_OVERLAP;',
'        l_has_content := true;',
'    END IF;',
'',
'    IF l_has_content THEN',
'        l_json := l_json || ''}'';',
'        apex_debug.warn(l_json);',
'        RETURN l_json;',
'    ELSE',
'        RETURN '''';',
'    END IF;',
'END;',
''))
,p_compute_when=>':REQUEST IN (''CREATE'')  OR (:REQUEST IN (''SAVE'') AND :P46_IS_DEFAULT_EDIT_FLAG = ''N'')'
,p_compute_when_text=>'PLSQL'
,p_compute_when_type=>'EXPRESSION'
);
