'',
'',
'',
'function styleApprovalButtons() {',
'    var $rejectBtn = $(''button[data-action="deleted"]'');',
'    var commonClasses = ''t-Button--hot t-Button--hoverIconPush'';',
'    var commonPadding = { ''padding-left'': ''15px'', ''padding-right'': ''15px'' };',
'',
'    $rejectBtn',
'        .addClass(commonClasses)',
'        .addClass(''t-Button--danger'')',
'        .css(commonPadding);',
'    ',
'    // $(''button[data-action] .a-Button-label'').css(''margin-right'', ''10px'');',
'}',
'',
'/**',
' * Upload files to the knowledge base',
' * @returns {Promise|boolean} ',
' */',
'async function uploadFiles() {',
'    if (isSending) return;',
'    apex.message.clearErrors();',
'    // return ;',
'    // 1. Validate and prepare metadata',
'    const uploadTo = apex.item("P47_UOLOAD_TO").getValue();',
'    let batchName;',
'    ',
'    // Validate different fields based on the upload target',
'    const batchField = uploadTo === ''Y'' ? "P47_BATCH_NAME" : "P47_BATCH_NAME_SELECT";',
'',
unistr('    if (!validateRequiredFields(batchField, apex.lang.formatMessage(''MSG_REQUIRED'', { name: langCode === ''zh-cn'' ? "\6279\6B21\540D\79F0" : "batch name" }))) {'),
'        requestFinish();',
'        return false;',
'    }',
'    batchName = apex.item(batchField).getValue();',
'',
'    // 2. Prepare metadata',
'    const metadata = {',
'        app_id: apex.env.APP_ID,',
'        domain_id: apex.item("P47_DOMAIN_ID").getValue(),',
'        kb_id: apex.item("P47_KB_ID").getValue(),',
'        overwrite: apex.item("P47_OVERWRITE").getValue(),',
'        batch_name: batchName,',
'        created_by: apex.env.APP_USER',
'    };',
'    console.log(JSON.stringify(metadata));',
'    // 3. check files',
'    const fileInput = document.getElementById(''P47_FILE_NAME'');',
'    if (!fileInput.files.length) {',
'        apex.message.showErrors({',
'            type: ''error'',',
'            location: ["inline"],',
'            pageItem: ''P47_FILE_NAME'',',
unistr('            message: apex.lang.formatMessage(''MSG_REQUIRED'', { name: langCode === ''zh-cn'' ? "\6587\4EF6" : "file" })'),
'        });',
'        requestFinish();',
'        return false;',
'    }',
'',
'    // 4. Prepare form data',
'    const formData = new FormData();',
'    Array.from(fileInput.files).forEach(file => {',
'        formData.append(''files'', file);',
'    });',
'    formData.append(''metadata'', JSON.stringify(metadata));',
'    isSending = true;',
'    // 5. Execute upload',
'    return axios.post(`${serviceUrl}/api/kb/upload`, formData, {',
'        headers: {',
'            ''accept'': ''application/json'',',
'            ''Content-Type'': ''multipart/form-data'',',
'            ''Authorization'': `Bearer ${accessToken}`',
'        }',
'    })',
'    .then(response => {',
'        console.log(''response'',response);',
'        if(response.data.code == 200){',
'            apex.item(P47_MSG).setValue(response.data.message);',
'            apex.page.submit(''UPLOAD'');',
'        }else{',
'            apex.message.showErrors({',
'                type: ''error'',',
'                location: ''page'',',
'                message: `File upload failed: ${response}`,',
'                unsafe: false',
'            });',
'        }',
'        ',
'        requestFinish();',
'    })',
'    .catch(error => {',
'        console.error(''Upload failed:'', error);',
'        const errorMsg = error.response?.data?.message || error.message;',
'        apex.message.showErrors({',
'            type: ''error'',',
'            location: ''page'',',
'            message: `File upload failed: ${errorMsg}`,',
'            unsafe: false',
'        });',
'        requestFinish();',
