'    apex.event.trigger("#removeRegionSpinner",''click'');',
'    isSending = false;',
'}',
'// null check',
'function validateRequiredFields(itemNames, errorMessage) {',
'     apex.message.clearErrors();',
unistr('    // \8BBE\7F6E\9ED8\8BA4\9519\8BEF\6D88\606F'),
'    errorMessage = errorMessage || "This field cannot be empty.";',
'',
'    if (typeof itemNames === ''string'') {',
'        itemNames = [itemNames];',
'    }',
'    ',
'    var isValid = true;',
'    $.each(itemNames, function(index, itemName) {',
'        var itemValue = apex.item(itemName).getValue();',
'        if (!itemValue || $.trim(itemValue) === '''') {',
'            isValid = false;',
'            apex.message.showErrors({',
'                type: "error",',
'                location: ["inline"],',
'                pageItem: itemName,',
'                message: errorMessage,',
'                unsafe: false',
