wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(4073269893909792)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'upload msg'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_domain_name varchar2(400);',
'    l_kb_name varchar2(400); ',
'BEGIN',
'    select kmd.name, kmk.kb_name ',
'    into   l_domain_name, l_kb_name',
'    from   kbot_md_domain kmd,',
'           kbot_md_kb     kmk',
'    where kmd.domain_id = kmk.domain_id',
'    and kmk.kb_id = :P47_KB_ID;',
'    kbot_md_ui_utl.ins_action_record(',
'        iv_func_name => ''KB Creation&Files Upload'',',
'        iv_action    => ''File upload completed (Business Domain: '' || l_domain_name || '', Knowledge Base: '' || l_kb_name || '').''',
'    );',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        NULL;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'UPLOAD'
,p_process_when_type=>'REQUEST_EQUALS_CONDITION'
,p_process_success_message=>'&P47_MSG.'
,p_internal_uid=>8585336497485942
);
