'SELECT ',
'    ''DOMAIN_'' || DOMAIN_ID AS ID,',
'    NULL AS PARENT_ID,',
'    NAME,',
'    ''fa fa-globe'' AS ICON,',
'    ''domain'' AS TYPE,',
'    1 AS TREE_LEVEL,',
'    DOMAIN_ID AS ORIGINAL_ID',
'FROM ',
'    KBOT_MD_DOMAIN',
'WHERE ',
'    APP_ID = :APP_ID',
'    AND STATUS = 1',
'',
'UNION ALL',
'',
unistr('-- \7B2C\4E8C\7EA7\FF1A\77E5\8BC6\5E93'),
'SELECT ',
'    ''KB_''||k.KB_ID AS ID,',
'    ''DOMAIN_'' || k.DOMAIN_ID AS PARENT_ID,',
'    k.KB_NAME AS NAME,',
'    ''fa fa-television'' AS ICON,',
'    ''kb'' AS TYPE,',
'    2 AS TREE_LEVEL,',
'    k.KB_ID AS ORIGINAL_ID',
'FROM ',
'    KBOT_MD_KB k',
'JOIN ',
'    KBOT_MD_DOMAIN d ON k.DOMAIN_ID = d.DOMAIN_ID AND k.APP_ID = d.APP_ID',
'WHERE ',
'    k.APP_ID = :APP_ID',
'    AND d.STATUS = 1',
'-- ORDER BY ',
'--     CASE WHEN PARENT_ID IS NULL THEN ID ELSE PARENT_ID END,',
'--     TREE_LEVEL, NAME'))
