wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1991805698791956)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'APPROVE_FILES'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_file_names         apex_t_varchar2;',
'    l_app_user           VARCHAR2(100) := V(''APP_USER'');',
'BEGIN',
'    l_file_names := apex_string.split(',
'        p_str => apex_application.g_x01,',
'        p_sep => '',''',
'    ); ',
'    ',
'    FOR i IN 1 .. l_file_names.COUNT LOOP',
'        BEGIN',
'            UPDATE KBOT_MD_KB_FILES',
'            SET    STATUS = 3',
'                  ,APPROVED_BY = l_app_user',
'                  ,APPROVED_TIME = CURRENT_DATE',
'            WHERE FILE_ID = l_file_names(i);',
'        EXCEPTION',
'            WHEN OTHERS THEN',
'                apex_json.open_object();',
'                apex_json.write(''code'', SQLCODE);',
'                apex_json.write(''msg'', ''Error processing file '' || l_file_names(i) || '': '' || SQLERRM);',
'                apex_json.close_all();',
'        END;',
'    END LOOP;',
'    ',
'    DECLARE',
'        l_domain_name varchar2(400);',
'        l_kb_name varchar2(400); ',
'    BEGIN',
'        select kmd.name, kmk.kb_name ',
'        into   l_domain_name, l_kb_name',
'        from   kbot_md_domain kmd,',
'               kbot_md_kb     kmk',
'        where kmd.domain_id = kmk.domain_id',
'        and kmk.kb_id = :P48_KB_ID;',
'',
'        kbot_md_ui_utl.ins_action_record(',
'            iv_func_name => ''Data Files - Pending Approve'',',
'            iv_action    => ''Files approval result (Business Domain: '' || l_domain_name || '', Knowledge Base: '' || l_kb_name || '', Status: Approved).''',
'        );',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            NULL;',
'    END;',
'',
'    apex_json.open_object();',
'    apex_json.write(''code'', ''200''); ',
'    apex_json.write(''processed_files'', l_file_names.COUNT);',
'    apex_json.close_all();',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        apex_json.open_object();',
'        apex_json.write(''code'', SQLCODE);',
'        apex_json.write(''msg'', SQLERRM); ',
'        apex_json.close_all(); ',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>6503872302368106
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1992964913791968)
,p_process_sequence=>30
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'REJECT_FILES'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_file_names         apex_t_varchar2;',
'    l_default_summary    NUMBER := kbot_md_ui_utl.get_dic_default_value(''SUMMARY_TYPE'',''R'');',
'    l_default_priority   NUMBER := kbot_md_ui_utl.get_dic_default_value(''PRIORITY_TYPE'',''R'');',
'    l_default_security   NUMBER := kbot_md_ui_utl.get_dic_default_value(''SECURITY_LEVEL_TYPE'',''R'');',
'    l_app_user           VARCHAR2(100) := V(''APP_USER'');',
'BEGIN',
'    l_file_names := apex_string.split(',
'        p_str => apex_application.g_x01,',
'        p_sep => '',''',
'    ); ',
'    ',
'    FOR i IN 1 .. l_file_names.COUNT LOOP',
'        BEGIN',
'            UPDATE KBOT_MD_KB_FILES',
'            SET    STATUS = 4',
'                  ,APPROVE_COMMENTS  = apex_application.g_x02',
'                  ,APPROVED_BY = l_app_user',
'                  ,APPROVED_TIME = CURRENT_DATE',
'            WHERE FILE_ID = l_file_names(i);',
'        EXCEPTION',
'            WHEN OTHERS THEN',
'                apex_json.open_object();',
'                apex_json.write(''code'', SQLCODE);',
'                apex_json.write(''msg'', ''Error processing file '' || l_file_names(i) || '': '' || SQLERRM);',
'                apex_json.close_all();',
'        END;',
'    END LOOP;',
'',
'    DECLARE',
'        l_domain_name varchar2(400);',
'        l_kb_name varchar2(400); ',
'    BEGIN',
'        select kmd.name, kmk.kb_name ',
'        into   l_domain_name, l_kb_name',
'        from   kbot_md_domain kmd,',
'               kbot_md_kb     kmk',
'        where kmd.domain_id = kmk.domain_id',
'        and kmk.kb_id = :P48_KB_ID;',
'',
'        kbot_md_ui_utl.ins_action_record(',
'            iv_func_name => ''Data Files - Pending Approve'',',
'            iv_action    => ''Files approval result (Business Domain: '' || l_domain_name || '', Knowledge Base: '' || l_kb_name || '', Status: rejected).''',
'        );',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            NULL;',
'    END;',
'',
'    apex_json.open_object();',
'    apex_json.write(''code'', ''200''); ',
'    apex_json.write(''processed_files'', l_file_names.COUNT);',
'    apex_json.close_all();',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        apex_json.open_object();',
'        apex_json.write(''code'', SQLCODE);',
'        apex_json.write(''msg'', SQLERRM); ',
'        apex_json.close_all(); ',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>6505031517368118
);
