 p_id=>wwv_flow_imp.id(733925767909773)
,p_validation_name=>'default check'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    ln_cnt NUMBER;',
'BEGIN',
'    IF :P50_IS_DEFAULT = 0 THEN',
'        RETURN TRUE;',
'    END IF;',
'',
'    IF :REQUEST = ''CREATE'' THEN',
'        SELECT COUNT(1)',
'        INTO   ln_cnt',
'        FROM   KBOT_MD_DATA_DIC',
'        WHERE  NAME = :P50_NAME',
'        AND    IS_DEFAULT = 1;',
'        ',
'        IF ln_cnt > 0 THEN',
'            RETURN false;',
'        ELSE',
'            RETURN true;',
'        END IF;',
'    ELSE',
'        SELECT COUNT(1)',
'        INTO   ln_cnt',
'        FROM   KBOT_MD_DATA_DIC',
'        WHERE  NAME = :P50_NAME',
'        AND    DIC_ID <> :P50_DIC_ID',
'        AND    IS_DEFAULT = 1;',
'        ',
'        IF ln_cnt > 0 THEN',
'            RETURN false;',
'        ELSE',
'            RETURN true;',
'        END IF;',
'    END IF;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'The same dictionary name is only allowed to contain one default value.'
,p_always_execute=>'Y'
,p_validation_condition=>':REQUEST IN(''CREATE'', ''SAVE'')'
,p_validation_condition2=>'PLSQL'
,p_validation_condition_type=>'EXPRESSION'
,p_associated_item=>wwv_flow_imp.id(733586961909770)
