,p_computation_sequence=>10
,p_computation_item=>'P51_IS_ENABLE'
,p_computation_point=>'AFTER_HEADER'
,p_computation_type=>'QUERY'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'  CASE ',
'    WHEN a.PROMPT_ID IS NOT NULL AND EXISTS (',
'      SELECT 1 ',
'      FROM KBOT_MD_AGENT_conf c ',
'      WHERE c.AGENT_ID = a.AGENT_ID',
'    ) THEN ''Y''',
'    ELSE ''N''',
'  END',
'FROM ',
'  KBOT_MD_AGENT a',
'WHERE ',
'  a.AGENT_ID = :P51_AGENT_ID;',
''))
,p_compute_when=>'P51_AGENT_ID'
,p_compute_when_type=>'ITEM_IS_NOT_NULL'
);
