wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(8254682801980195)
,p_computation_sequence=>10
,p_computation_item=>'P51_LLM_PARAMS'
,p_computation_type=>'FUNCTION_BODY'
,p_computation_language=>'PLSQL'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_json clob;',
'    l_has_content boolean := false;',
'BEGIN',
'    l_json := ''{'';',
'    ',
'    IF :P51_TEMPERATURE_D IS NOT NULL THEN',
'        l_json := l_json || ''"temperature":'' || :P51_TEMPERATURE_D;',
'        l_has_content := true;',
'    END IF;',
'',
'    IF :P51_MAX_TOKENS_D IS NOT NULL THEN',
'        IF l_has_content THEN',
'            l_json := l_json || '','';',
'        END IF;',
'        l_json := l_json || ''"max_tokens":'' || :P51_MAX_TOKENS_D;',
'        l_has_content := true;',
'    END IF;',
'',
'    IF l_has_content THEN',
'        l_json := l_json || ''}'';',
'        apex_debug.warn(l_json);',
'        RETURN l_json;',
'    ELSE',
'        RETURN '''';',
'    END IF;',
'END;',
''))
,p_compute_when=>':REQUEST IN (''CREATE'', ''SAVE'')'
,p_compute_when_text=>'PLSQL'
,p_compute_when_type=>'EXPRESSION'
);
