prompt --application/pages/page_00054
begin
wwv_flow_imp_page.create_page(
 p_id=>54
,p_name=>'Data Files - Pending Submit'
,p_alias=>'DATA-FILES-PENDING-SUBMIT'
,p_step_title=>'Data Files - Pending Submit'
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'const serviceUrl = apex.item(P0_SERVICE_URL).getValue();',
'const langCode = apex.item(P0_LANG_CODE).getValue();',
'let isSendingDeleteRequest = false;',
'const accessToken =  apex.item(P0_ACCESS_TOKEN).getValue();',
'',
'function redirectPage(){',
'    apex.server.process(    ',
'        ''GET_APEX_URL'',',
'        {x01: apex.item(P54_NODE_ID).getValue()},',
'        {success: function (pData) {           ',
'                apex.navigation.redirect(pData);',
'            },',
'            dataType: "text"                     ',
'        }',
'    )',
'}',
'',
'function getFileID(){',
'    let $grid = apex.region("queryResultStaticID").widget().interactiveGrid("getViews", "grid");',
'    let fileID = '''';',
'    for(let i = 0;i < $grid.getSelectedRecords().length;i++){',
'        if(i == $grid.getSelectedRecords().length-1){',
'            fileID += $grid.model.getValue( $grid.getSelectedRecords()[i], "FILE_ID");',
'        }else{',
'            fileID += $grid.model.getValue( $grid.getSelectedRecords()[i], "FILE_ID") + ",";',
'        }',
'    }',
'    return fileID;',
'}',
'',
'function getValArray(name) {',
'    let $grid = apex.region("queryResultStaticID").widget().interactiveGrid("getViews", "grid");',
'    let valArray = []; ',
'',
'    for (let i = 0; i < $grid.getSelectedRecords().length; i++) {',
'        valArray.push($grid.model.getValue($grid.getSelectedRecords()[i], name));',
'    }',
'    ',
'    return valArray; ',
'}',
'',
'function taskRequestDelete() {',
'    apex.message.clearErrors();',
'    if (isSendingDeleteRequest){',
'        alert( "Processing request, please wait...");',
'        return;',
'    } ',
'    isSendingDeleteRequest = true;',
'',
'    const fileIDs = getValArray(''FILE_ID'');',
'    const filePaths = getValArray(''FILE_PATH'');',
'    ',
'    if (!fileIDs?.length || !filePaths?.length) {',
'        isSendingDeleteRequest = false;',
'        return;',
'    }',
'',
'    const kbId = apex.item(''P54_KB_ID'').getValue();',
'    const domainId = apex.item(''P54_DOMAIN_ID'').getValue();',
'    ',
'    if (!kbId || !domainId) {',
'        isSendingDeleteRequest = false;',
'        return;',
'    }',
'',
'    const confirmOptions = {',
unistr('        title: langCode ==''zh-cn''?"\8B66\544A":"Warning",'),
'        style: "warning",',
'        iconClasses: "fa fa-warning fa-2x",',
unistr('        cancelLabel: langCode ==''zh-cn''?"\53D6\6D88":"Cancel",'),
unistr('        confirmLabel: langCode ==''zh-cn''?"\786E\5B9A":"Confirm"'),
'    };',
unistr('    let msgConfirm = langCode ==''zh-cn''?"\9009\4E2D\7684\6570\636E\6587\4EF6\5C06\88AB\5220\9664\FF0C\662F\5426\7EE7\7EED\FF1F":"The data will be deleted soon. Do you want to continue?";'),
'    apex.message.confirm(msgConfirm,',
'        (okPressed) => {',
'            if (!okPressed){',
'               isSendingDeleteRequest = false;',
'               return;',
'            } ',
'            apex.event.trigger("#addRegionSpinner",''click'');',
'            const formData = new FormData();',
'            const metadata = {',
'                app_id: apex.env.APP_ID,',
'                domain_id: domainId,',
'                kb_id: kbId,',
'                batch_id: null,',
'                batch_name: null,',
'                file_ids: fileIDs,',
'                file_paths: filePaths',
'            };',
'',
'            formData.append(''metadata'', JSON.stringify(metadata));',
'',
'            axios.post(`${serviceUrl}/api/kb/delete`,formData,',
'                {',
'                    headers: {',
'                        ''Content-Type'': ''multipart/form-data'',',
'                        ''Authorization'': `Bearer ${accessToken}`',
'                    }',
'                }',
'            )',
'            .then(response => {',
'                if (response.data.code == 200) {',
'                    apex.message.showPageSuccess(response.data.message);',
'                    apex.region("queryResultStaticID").refresh();',
'                    apex.server.process("ADD_ACTION_RECORD", {',
'                        pageItems: ["P54_KB_ID"]',
'                    }, {',
'                        dataType: ''text'',',
'                        error: function(jqXHR, textStatus, errorThrown) {',
'                            console.error("Error writing action record:", textStatus, errorThrown);',
'                        }',
'                    });',
'                } else {',
'                    apex.message.showErrors({',
'                        type: "error",',
'                        location: "page",',
'                        message: `Error: ${response.data.message || ''unknown error''}`,',
'                        unsafe: false',
'                    });',
'                    console.error(''error:'', response);',
'                }',
'',
'            })',
'            .catch(error => {',
'                console.error(''Deletion failed:'', error.response?.data || error.message);',
'            })',
'            .finally(() => {',
'                isSendingDeleteRequest = false;',
'                apex.event.trigger("#removeRegionSpinner",''click'');',
'            });',
'        },',
'        confirmOptions',
'    );',
'}',
'',
'function  taskRequestApprove(){',
'    apex.message.clearErrors();',
'    const fileIDs =  getFileID();',
'    console.log(fileIDs);',
'    if(!fileIDs) return;',
unistr('    let msgConfirm = langCode ==''zh-cn''?"\662F\5426\53D1\8D77\6587\4EF6\7684\5BA1\6279\7533\8BF7\FF1F":"Are you sure you want to request approval for these documents?";'),
'    apex.message.confirm( msgConfirm, function( okPressed ) {',
'        if( okPressed ) {',
'            apex.server.process( "REQUEST_APPROVE_FILES", {',
'                x01:fileIDs,',
'                pageItems: ["P54_KB_ID"]',
'            }, {',
'                dataType:''text''',
'                ,success: function( response )  {',
'                    if (typeof response === ''string'') {',
'                        response = JSON.parse(response);',
'                    }',
'                    if (response.code == 200) {',
'                        apex.message.showPageSuccess(',
'                            `Successfully submitted ${response.submit_files || ''all''} files.`',
'                        );',
'                        ',
'                        apex.region("queryResultStaticID").refresh();',
'',
'                    } else {',
'                        apex.message.showErrors({',
'                            type: "error",',
'                            location: "page",',
'                            message: `Error: ${response.msg || ''unknown error''}`,',
'                            unsafe: false',
'                        });',
'                        ',
'                        console.error(''error:'', response);',
'                    }',
'                },',
'                error: function( jqXHR, textStatus, errorThrown ) {',
'                    console.error(''error:'', jqXHR, textStatus, errorThrown);',
'                }',
'            } );',
'        }',
'    }, {',
unistr('        title: langCode ==''zh-cn''?"\901A\77E5":"Info",'),
'        style: "information",',
'        iconClasses: "fa fa-info-circle-o fa-2x",',
unistr('        cancelLabel: langCode ==''zh-cn''?"\5426":"No",'),
unistr('        confirmLabel: langCode ==''zh-cn''?"\662F":"Yes"'),
'    } );',
'}',
'',
'function extractIdAndType(str) {',
'  const match = str.match(/^(DOMAIN|KB)_(\d+)$/i);',
'  if (!match) return null;',
'',
'  const type = match[1].toLowerCase(); ',
'  const id = parseInt(match[2], 10); ',
'',
'  return { type, id };',
'}',
'',
'function styleApprovalButtons() {',
'    var $approveBtn = $(''button[data-action="RequestApproval"]'');',
'    var $rejectBtn = $(''button[data-action="deleted"]'');',
'    var $toPageBtn = $(''button[data-action="toPage"]'');',
'    var commonClasses = ''t-Button--hot t-Button--hoverIconPush'';',
'    var commonPadding = { ''padding-left'': ''20px'', ''padding-right'': ''20px'' };',
'    ',
'    $approveBtn',
'        .addClass(commonClasses)',
'        .addClass(''t-Button--success'')',
'        .css(commonPadding);',
'    ',
'    $rejectBtn',
'        .addClass(commonClasses)',
'        .addClass(''t-Button--danger'')',
'        .css(commonPadding);',
'',
'    if(apex.item(P54_IS_APPROVE_AUTH).getValue() == ''Y''){',
'       $toPageBtn',
'        .addClass(commonClasses)',
'        .addClass(''t-Button--success'')',
'        .css(commonPadding); ',
'    }else{',
'        $toPageBtn.hide();',
'    }',
'    // $(''button[data-action] .a-Button-label'').css(''margin-right'', ''10px'');',
'}'))
,p_javascript_code_onload=>'styleApprovalButtons();'
