'       kbot_md_ui_utl.get_dic_dname(''IS_TABLE_HEAD_FILL'', kukf.IS_TABLE_HEAD_FILL) AS Fill_Table_Head_For_Table,',
'       kbot_md_ui_utl.get_dic_dname(''SUMMARY_TYPE'', kukf.ENABLE_SUMMARY) ENABLE_SUMMARY,',
'       kukf.APPROVE_COMMENTS,',
'       kukf.created_by,',
'       kukf.created_time,',
'       kukf.approved_by,',
'       kukf.approved_time,',
'       kukf.file_version,',
'       JSON_QUERY(kukf.BIZ_METADATA, ''$.KeyWords'') BIZ_METADATA,',
