wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(105289741082149712)
,p_plug_name=>'Knowledge Base'
,p_region_name=>'taskListStatic'
,p_region_template_options=>'#DEFAULT#:i-h480:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(106470686057103554)
,p_plug_display_sequence=>10
,p_plug_display_point=>'REGION_POSITION_02'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('-- \7B2C\4E00\7EA7\FF1A\4E1A\52A1\57DF'),
'SELECT ',
'    ''DOMAIN_'' || DOMAIN_ID AS ID,',
'    NULL AS PARENT_ID,',
'    NAME,',
'    ''fa fa-globe'' AS ICON,',
'    ''domain'' AS TYPE,',
'    1 AS TREE_LEVEL,',
'    DOMAIN_ID AS ORIGINAL_ID',
'FROM ',
'    KBOT_MD_DOMAIN',
'WHERE ',
'    APP_ID = :APP_ID',
'    AND STATUS = 1',
'',
'UNION ALL',
'',
unistr('-- \7B2C\4E8C\7EA7\FF1A\77E5\8BC6\5E93'),
'SELECT ',
'    ''KB_''||k.KB_ID AS ID,',
'    ''DOMAIN_'' || k.DOMAIN_ID AS PARENT_ID,',
'    k.KB_NAME AS NAME,',
'    ''fa fa-television'' AS ICON,',
'    ''kb'' AS TYPE,',
'    2 AS TREE_LEVEL,',
'    k.KB_ID AS ORIGINAL_ID',
'FROM ',
'    KBOT_MD_KB k',
'JOIN ',
'    KBOT_MD_DOMAIN d ON k.DOMAIN_ID = d.DOMAIN_ID AND k.APP_ID = d.APP_ID',
'WHERE ',
'    k.APP_ID = :APP_ID',
'    AND d.STATUS = 1',
'-- ORDER BY ',
'--     CASE WHEN PARENT_ID IS NULL THEN ID ELSE PARENT_ID END,',
'--     TREE_LEVEL, NAME'))
,p_lazy_loading=>true
,p_plug_source_type=>'NATIVE_JSTREE'
,p_ai_enabled=>false
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'activate_node_link_with', 'S',
  'default_icon_css_class', 'icon-tree-folder',
  'icon_css_class_column', 'ICON',
  'icon_type_css_class', 'a-Icon',
  'node_id_column', 'ID',
  'node_label_column', 'NAME',
  'node_value_column', 'ID',
  'order_siblings_by', 'TYPE',
  'parent_key_column', 'PARENT_ID',
  'selected_node_page_item', 'P54_NODE_ID',
  'start_tree_with', 'NULL',
  'tree_hierarchy', 'SQL',
  'tree_tooltip', 'N')).to_clob
);
