wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(4218412008836274)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'REQUEST_APPROVE_FILES'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_file_names         apex_t_varchar2;',
'    l_app_user           VARCHAR2(100) := V(''APP_USER'');',
'BEGIN',
'    l_file_names := apex_string.split(',
'        p_str => apex_application.g_x01,',
'        p_sep => '',''',
'    ); ',
'    ',
'    FOR i IN 1 .. l_file_names.COUNT LOOP',
'        BEGIN',
'            UPDATE KBOT_MD_KB_FILES',
'            SET    STATUS = 2',
'                  ,UPDATED_BY = l_app_user',
'                  ,UPDATED_TIME = CURRENT_DATE',
'            WHERE FILE_ID = l_file_names(i);',
'        EXCEPTION',
'            WHEN OTHERS THEN',
'                apex_json.open_object();',
'                apex_json.write(''code'', SQLCODE);',
'                apex_json.write(''msg'', ''Error processing file '' || l_file_names(i) || '': '' || SQLERRM);',
'                apex_json.close_all();',
'        END;',
'    END LOOP;',
'',
'    DECLARE',
'        l_domain_name varchar2(400);',
'        l_kb_name varchar2(400); ',
'    BEGIN',
'        select kmd.name, kmk.kb_name ',
'        into   l_domain_name, l_kb_name',
'        from   kbot_md_domain kmd,',
'               kbot_md_kb     kmk',
'        where kmd.domain_id = kmk.domain_id',
'        and kmk.kb_id = :P54_KB_ID;',
'',
'        kbot_md_ui_utl.ins_action_record(',
'            iv_func_name => ''Data Files - Pending Submit'',',
'            iv_action    => ''File submission completed (Business Domain: '' || l_domain_name || '', Knowledge Base: '' || l_kb_name || '').''',
'        );',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            NULL;',
'    END;',
'',
'    apex_json.open_object();',
'    apex_json.write(''code'', ''200''); ',
'    apex_json.write(''submit_files'', l_file_names.COUNT);',
'    apex_json.close_all();',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        apex_json.open_object();',
'        apex_json.write(''code'', SQLCODE);',
'        apex_json.write(''msg'', SQLERRM); ',
'        apex_json.close_all(); ',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>8730478612412424
);
