,p_region_css_classes=>'fileListClass'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(106419126645103538)
,p_plug_display_sequence=>40
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select kukf.file_id,',
'       kukb.BATCH_name,',
'       kukf.FILE_NAME,',
'       kbot_md_ui_utl.get_dic_dname(''OVERWRITE_TYPE'',kukf.IS_OVERWRITE) as IS_OVERWRITE,',
'       kbot_md_ui_utl.format_file_size(kukf.FILE_SIZE) FILE_SIZE,',
'       kukf.created_by,',
'       kbot_md_ui_utl.get_dic_dname(''FILE_STATUS'',kukf.status) status,',
unistr('       -- \6570\636E\4E0A\4F20\9636\6BB5'),
'    case ',
'        when kukf.status = 1 then ''<div class="status-circle success"></div>''',
'        when kukf.status > 1 and kukf.status < 9 then ''<div class="status-circle success"></div>''',
'        else ''<div class="status-circle transparent"></div>''',
'    end as "Data Upload",',
'    ',
unistr('    -- \5F85\63D0\4EA4\9636\6BB5'),
'    case ',
'        when kukf.status = 2 then ''<div class="status-circle blinking"></div>''',
'        when kukf.status > 2 and kukf.status < 9 then ''<div class="status-circle success"></div>''',
'        when kukf.status < 2 then ''<div class="status-circle transparent"></div>''',
'        else ''<div class="status-circle transparent"></div>''',
'    end as "Pending Approve",',
'    ',
unistr('    -- \5BA1\6279\9636\6BB5'),
'    case ',
'        when kukf.status = 3 then ''<div class="status-circle success"></div>''',
'        when kukf.status = 4 then ''<div class="status-circle failed"></div>''',
'        when kukf.status < 3 or kukf.status =9 then ''<div class="status-circle transparent"></div>''',
'        else ''<div class="status-circle success"></div>''',
'    end as "Approve",',
'    ',
unistr('    -- \6570\636E\89E3\6790\9636\6BB5'),
'    case ',
'        when kukf.status = 5 or kukf.status = 8 then ''<div class="status-circle blinking"></div>''',
'        when kukf.status = 6 then ''<div class="status-circle success"></div>''',
'        when kukf.status = 7 then ''<div class="status-circle failed"></div>''',
'        when kukf.status < 5 or kukf.status = 9 then ''<div class="status-circle transparent"></div>''',
'        else ''<div class="status-circle transparent"></div>''',
'    end as "Data Parser",',
'       file_version,',
'       kukf.created_time,',
'       kukf.updated_by,',
'       kukf.updated_time,',
'       kukf.approved_by,',
'       kukf.approved_time,',
'       kukf.approve_comments,',
'       kukf.log_msg',
'  from KBOT_MD_KB_FILES kukf,',
'       KBOT_MD_KB       kuk,',
'       KBOT_MD_KB_BATCH  kukb,',
'       KBOT_MD_DOMAIN  kmd',
'  where kukf.app_id = :APP_ID',
'  and   kukf.KB_ID = kuk.kb_id',
'  and   kmd.domain_id = kuk.domain_id',
'  and   kukb.batch_id  = kukf.batch_id',
'  and   kuk.kb_id     = :P55_KB_ID'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P55_KB_ID,P55_NODE_ID'
