wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9375541505787465)
,p_process_sequence=>10
,p_parent_process_id=>wwv_flow_imp.id(9459522453181970)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>unistr('\5904\7406\8868\5355 API key Detail')
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_service_url  VARCHAR2(400) := :P0_SERVICE_URL;',
'    l_clob 	        CLOB;',
'    l_resp          apex_json.t_values;',
'    lv_token        VARCHAR2(4000);',
'    lv_str          VARCHAR2(32766);',
'    j               apex_json.t_values; ',
'BEGIN',
'    IF V(''REQUEST'') = ''CREATE'' THEN',
'        apex_web_service.g_request_headers.delete();',
'        apex_web_service.g_request_headers(1).name  := ''Content-Type'';',
'        apex_web_service.g_request_headers(1).value := ''application/json''; ',
'        l_clob := apex_web_service.make_rest_request(',
'                p_url => l_service_url || ''/api/security/create_accessor'',',
'                p_http_method => ''POST'',',
'                p_body => ''',
'                {',
'                  "app_id": ''|| :APP_ID ||'',',
'                  "accessor": "''|| :P60_ACCESSOR ||''",',
'                  "accessor_type": ''|| :P60_ACCESSOR_TYPE ||'',',
'                  "plain_password": "''|| :P60_HASHED_SECRET ||''",',
'                  "descs": "''|| :P60_DESCS ||''",',
'                  "by": "''|| :APP_USER ||''"',
'                }''',
'            );',
'        ',
'        apex_json.parse(p_values => l_resp,p_source => l_clob);',
'        IF apex_json.get_varchar2(p_path => ''code'',p_values => l_resp) <> ''200'' THEN',
'            APEX_ERROR.ADD_ERROR (',
'                p_message => apex_json.get_varchar2(p_path => ''message'',p_values => l_resp),',
'                p_display_location => apex_error.c_inline_in_notification',
'            );',
'',
'        END IF; ',
'',
'    ELSIF V(''REQUEST'') = ''SAVE'' THEN',
'        -- IF :P60_HASHED_SECRET IS NULL THEN',
'            update KBOT_MD_API_SECURITY',
'            set    STATUS = :P60_STATUS',
'                  ,DESCS = :P60_DESCS',
'                  ,UPDATED_BY = :APP_USER',
'                  ,UPDATED_TIME = CURRENT_DATE',
'            where SECURITY_ID = :P60_SECURITY_ID;',
'        -- else',
'            -- call api;',
'            NULL;',
'        -- end if;',
'    ELSE',
'        DELETE KBOT_MD_API_SECURITY',
'        WHERE SECURITY_ID = :P60_SECURITY_ID;',
'    END IF;',
'--',
'    COMMIT;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>13887608109363615
);
