,p_display_point=>'REGION_POSITION_02'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    DOMAIN_ID,',
'    NULL link_class,',
'    apex_page.get_url(p_items => ''P61_DOMAIN_ID'', p_values => DOMAIN_ID) LINK,',
'    ''fa fa-globe'' ICON_CLASS,',
'    null LINK_ATTR,',
'    ''u-color-14'' ICON_COLOR_CLASS,',
'    case when coalesce(:P61_domain_ID,''0'') = DOMAIN_ID',
'    then ''is-active'' ',
'    else ''''',
'    end LIST_CLASS,',
'    (substr(NAME, 1, 30)||( case when length(NAME) > 30 then ''...'' else '''' end )) LIST_TITLE,',
'    (substr(DESCS, 1, 30)||( case when length(DESCS) > 30 then ''...'' else '''' end )) LIST_TEXT,',
'    null LIST_BADGE',
'from kbot_md_domain x',
'where app_Id = V(''APP_ID'') ',
'AND   x.status = 1',
'AND',
'     (:P61_SEARCH is null ',
'     or upper(x.NAME) like ''%''||upper(:P61_SEARCH)||''%''',
'     or upper(x.DESCS) like ''%''||upper(:P61_SEARCH)|| ''%'' );'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P61_SEARCH'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(106485696477103559)
