wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(106745108768609546)
,p_plug_name=>'Set parameters and reparse'
,p_region_name=>'appListStatic'
,p_parent_plug_id=>wwv_flow_imp.id(106745139022609547)
,p_region_css_classes=>'fileListClass'
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--scrollBody:margin-top-sm'
,p_plug_template=>wwv_flow_imp.id(106470686057103554)
,p_plug_display_sequence=>50
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select kukf.FILE_ID,',
'       kukb.BATCH_name,',
'       kukf.FILE_NAME,',
'       kbot_md_ui_utl.get_dic_dname(''FILE_STATUS'',kukf.status) STATUS,',
'       kbot_md_ui_utl.get_dic_dname(''OVERWRITE_TYPE'',kukf.IS_OVERWRITE) as IS_OVERWRITE,',
'       kbot_md_ui_utl.format_file_size(kukf.FILE_SIZE) FILE_SIZE,',
'       kbot_md_ui_utl.get_dic_dname(''CHUNK_PARSER_TYPE'', JSON_VALUE(kukf.CHUNK_PARSER, ''$.split_strategy'')) AS SPLIT_STRATEGY,',
'       JSON_VALUE(kukf.CHUNK_PARSER, ''$.chunk_size'') AS CHUNK_SIZE,',
'       JSON_VALUE(kukf.CHUNK_PARSER, ''$.chunk_overlap'') AS CHUNK_OVERLAP,',
'       kbot_md_ui_utl.get_dic_dname(''IS_IMG2TXT'', kukf.IS_IMG2TXT) AS Transform_Image_to_Text,',
'       kbot_md_ui_utl.get_dic_dname(''IS_TABLE_HEAD_FILL'', kukf.IS_TABLE_HEAD_FILL) AS Fill_Table_Head_For_Table,',
'       kbot_md_ui_utl.get_dic_dname(''SUMMARY_TYPE'', kukf.ENABLE_SUMMARY) ENABLE_SUMMARY,',
'       CASE ',
'          WHEN kukf.PROCESS_PRIORITY = 1 THEN',
'            ''<span class="priority-low">'' || kbot_md_ui_utl.get_dic_dname(''PROCESS_PRIORITY_TYPE'',kukf.PROCESS_PRIORITY) || ''</span>''',
'          WHEN kukf.PROCESS_PRIORITY = 2 THEN ',
'            ''<span class="priority-medium">'' || kbot_md_ui_utl.get_dic_dname(''PROCESS_PRIORITY_TYPE'',kukf.PROCESS_PRIORITY) || ''</span>''',
'          WHEN kukf.PROCESS_PRIORITY = 3 THEN ',
'            ''<span class="priority-high">'' || kbot_md_ui_utl.get_dic_dname(''PROCESS_PRIORITY_TYPE'',kukf.PROCESS_PRIORITY) || ''</span>''',
'          ELSE ',
'            ''<span class="priority-unknown"> '' || nvl(kbot_md_ui_utl.get_dic_dname(''PROCESS_PRIORITY_TYPE'',kukf.PROCESS_PRIORITY), ''Others'') || '' </span>''',
'       END as PROCESS_PRIORITY,',
'       CASE ',
'          WHEN kukf.SECURITY_LEVEL = 1 THEN ',
'            ''<span class="security-low">'' || kbot_md_ui_utl.get_dic_dname(''SECURITY_LEVEL_TYPE'',kukf.SECURITY_LEVEL) ||''</span>''',
'          WHEN kukf.SECURITY_LEVEL = 2 THEN ',
'            ''<span class="security-medium">'' || kbot_md_ui_utl.get_dic_dname(''SECURITY_LEVEL_TYPE'',kukf.SECURITY_LEVEL) || ''</span>''',
'          WHEN kukf.SECURITY_LEVEL = 3 THEN ',
'            ''<span class="security-high">'' || kbot_md_ui_utl.get_dic_dname(''SECURITY_LEVEL_TYPE'',kukf.SECURITY_LEVEL) || ''</span>''',
'          ELSE ',
'            ''<span class="security-other">'' || nvl(kbot_md_ui_utl.get_dic_dname(''SECURITY_LEVEL_TYPE'',kukf.SECURITY_LEVEL), ''Others'') || ''</span>''',
'       END as SECURITY_LEVEL,',
'       kukf.file_version,',
'       ''''  view_file,',
'       kukf.created_by,',
'       kukf.created_time,',
'       '''' edit_file,',
'       '''' as tag',
'  from KBOT_MD_KB_FILES kukf,',
'       KBOT_MD_KB       kuk,',
'       KBOT_MD_KB_BATCH  kukb',
'  where kuk.kb_id = kukb.KB_ID',
'  and   kukb.batch_id  = kukf.batch_id',
'  and   kuk.kb_id     = :P63_KB_ID',
'  and   kuk.app_id    = :APP_ID',
'  and   (kukf.status = 6 or kukf.status =7);'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P63_KB_ID,P63_NODE_ID'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'list'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
