prompt --application/pages/page_00100
begin
wwv_flow_imp_page.create_page(
 p_id=>100
,p_name=>'kbot-Chat'
,p_alias=>'KBOT-CHAT'
,p_step_title=>'kbot-Chat'
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_javascript_file_urls=>'#APP_FILES#marked.min.js'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'const s_url = apex.item(P0_SERVICE_URL).getValue();',
'const langCode = apex.item(P0_LANG_CODE).getValue();',
'const accessToken =  apex.item(P0_ACCESS_TOKEN).getValue();',
'let   chatId, $thumb, $bubble= '''';',
'const $chatArea = $("#chat-area");',
'let   gDataIndex = 0;',
'let   isSending = false;',
'// Display AI is thinking',
'let $loadingBubble = $(',
'    `<div class="chat-bubble bot loading-bubble">',
unistr('        <div class="avatar">\D83E\DD16</div>'),
'        <div class="content">',
'            <div class="message"><span class="dot-typing"></span><span class="dot-typing"></span></div>',
'        </div>',
'    </div>`',
');',
'',
'',
'function delSessionConfirm(e){',
'    apex.message.clearErrors();',
'    e.stopPropagation();',
'    e.preventDefault();',
'    const $target = $(e.currentTarget).closest(''.t-SearchResults-item'');',
'    if ($target.length) {',
'        const sessionID = $target.data(''session-id'');',
unistr('        let msgConfirm = langCode == ''zh-cn''?"\662F\5426\5220\9664\6B64\4F1A\8BDD\5386\53F2\FF1F":"Are you sure you wish to delete this record?";'),
'        apex.message.confirm( msgConfirm, function( okPressed ) {',
'            if( okPressed ) {',
'                delSession(sessionID);',
'            }',
'        }, {',
unistr('            title: langCode=="zh-cn"?"\8B66\544A\FF01":"Warning!",'),
'            style: "danger",',
'            iconClasses: "fa fa-trash fa-2x",',
unistr('            cancelLabel: langCode=="zh-cn"?"\5426":"No",'),
unistr('            confirmLabel: langCode=="zh-cn"?"\786E\5B9A":"I''m sure"'),
'        } );',
'    }',
'}',
'',
'async function delSession(sessionID){',
'    try {',
'        const response = await axios.get(`${s_url}/api/agent/session/remove?session_id=${sessionID}`, {',
'        headers: {',
'            ''accept'': ''application/json'',',
'            ''Authorization'': `Bearer ${accessToken}`',
'            }',
'        });',
'        console.log(response);',
'        if(response.status == 200){',
'            apex.server.process("DEL_SESSION_RECORD", {',
'                x01: sessionID,',
'            }, {',
'                dataType:''text'',',
'                success: function(data) {',
'                    if(data.trim() !== ''1''){',
'                        console.error(data);',
'                        apex.message.showErrors([{type:"error", location:"page", message:data, unsafe:false}]);',
'                    }',
'                    if(apex.item(P100_SESSION_ID).getValue() == sessionID){',
'                        apex.page.submit( "NEW-CHAT" );',
'                    }else{',
'                        apex.region("sessionHisStatic").refresh();',
'                    }',
'                    ',
'                },',
'                error: function(jqXHR, textStatus, errorThrown) {',
'                    console.error("error", textStatus);',
'                    apex.message.showErrors([{type:"error", location:"page", message:''error'', unsafe:false}]);',
'                }',
'            });',
'        }else{',
'            apex.message.showErrors([{type:"error", location:"page", message:error, unsafe:false}]);',
'        }',
'',
'    } catch (error) {',
'            apex.message.showErrors([{type:"error", location:"page", message:error.message, unsafe:false}]);',
'    }',
'}',
'',
'',
'async function saveFeedback(index, feedback){',
'    let requestBody = {',
'        session_id: apex.item(P100_SESSION_ID).getValue(),',
'        question_index: index,',
'        feedback: feedback',
'    };',
'    url = ''/api/agent/feedback'';',
'    const  fbResult =  await getApiSource(requestBody, url);',
'    if(fbResult.code !== 200){',
'        console.error(fbResult.message);',
'    }',
'}',
'',
'async function sendMsg() {',
'    let ins_data_result, lv_sse_result = '''';',
'    if (isSending) return;',
'    const userText = $(''#user-input'').val().trim();',
'    if (!userText) return;',
'    $(''#user-input'').val('''');',
'    if (userText === '''') return;',
'    isSending = true;',
'',
'    // Display user messages',
'    $chatArea.append(',
'        `<div class="chat-bubble user">',
'            <div class="avatar"><span class ="avatar-user"> ${apex.env.APP_USER} </span></div>',
'            <div class="content">',
'                <div class="message">  ${userText} </div>',
'                <div class="timestamp"> ${getLocalTime()} </div>',
'            </div>',
'        </div>`',
'    );',
'    $chatArea.append($loadingBubble);',
'    scrollChatToBottom();',
'',
'    let requestBody = {',
'        session_id: apex.item(P100_SESSION_ID).getValue(),',
'        by: apex.env.APP_USER,',
'        agent_id: Number(apex.item("P100_AGENT_NAME").getValue()),',
'        security_level: Number(apex.item(P100_SECURITY_LEVEL).getValue()),',
'        request_time: getLocalTime(),',
'        question: userText',
'    };',
'    //get session_id and refrence',
'    url = ''/api/agent/chat'';',
'    const  refSource = await getApiSource(requestBody, url);',
'    ',
'    console.log(''/api/agent/chat'', refSource);',
'',
'    if(!refSource) return;',
'',
'    if(refSource.code === 200){',
'        if (gDataIndex == 0) {',
'            insSessionRecord(userText);',
'        }',
'        ',
'        let likeSelected = refSource.data.feedback == ''1'' ? ''selected'' : '''';',
'        let dislikeSelected = refSource.data.feedback == ''-1'' ? ''selected'' : '''';',
'        let $botDiv = getKbotResponseDom(gDataIndex, refSource.data.response_time, likeSelected, dislikeSelected);',
'        ',
'        let $botStream = $botDiv.find(''.bot-stream'');',
'',
'        let eventSource = new EventSource(`${s_url}/api/agent/stream?session_id=${apex.item(P100_SESSION_ID).getValue()}`);',
'        let firstMessageReceived = false;',
'        let content= '''';',
'        marked.setOptions({',
'            breaks: false, ',
'            gfm: true, ',
'        });',
'        eventSource.addEventListener(''message'', async (event) => {',
'            if(event.data == ''[DONE]''){',
'                const aiResponseDom = getShowMoreDom(gDataIndex, refSource.data.references);',
'                $botStream.append(aiResponseDom);',
'                scrollChatToBottom();',
'                gDataIndex ++;',
'                console.log(''end'');',
'                eventSource.close();',
'                isSending = false;',
'            }else{',
'                let responseObj = JSON.parse(event.data)',
'                ',
'                if (!firstMessageReceived) {',
'',
'                    firstMessageReceived = true;',
'                    //Remove the corresponding AI animation',
'                    hisSessionSelectListStyle();',
'                    $loadingBubble.remove(); ',
'                    $chatArea.append($botDiv);',
'                    scrollChatToBottom();',
'                }',
'                if(responseObj.choices[0].delta.content){',
'                    // console.log(responseObj.choices[0].delta.content);',
'                    content += responseObj.choices[0].delta.content;',
'                    $botStream.html(marked.parse(content.trim()));',
'                    scrollChatToBottom();',
'                }',
'            }',
'',
'        });',
'        eventSource.onerror = async (event) => {',
'            eventSource.close();',
'        };',
'    }',
'    else{',
'        printSysErrMsg(refSource.message);',
'        return;',
'    }',
'};',
'',
'async function getApiSource(requestBody,url) {',
'    console.log(requestBody);',
'    try {',
'        const response = await axios.post(`${s_url}${url}`, requestBody, {',
'        headers: {',
'            ''Content-Type'': ''application/json'',',
'            ''accept'': ''application/json'',',
'            ''Authorization'': `Bearer ${accessToken}`',
'        },',
'        // ,timeout: 10000',
'    });',
'    return response.data;',
'',
'    } catch (error) {',
'        if (error.response) {',
'            console.error(''Error data:'', error.response.data); ',
'            console.error(''Status:'', error.response.status);',
'            console.error(''Headers:'', error.response.headers);',
'        } else if (error.request) {',
'            console.error(''No response:'', error.request);',
'        } else {',
'            console.error(''Error:'', error.message);',
'        }',
'        printSysErrMsg(error.message);',
'        return ''''; ',
'  }',
'}',
'',
'function insSessionRecord(question){',
'    apex.server.process("INSTR_SESSION_RECORD", {',
'        x01: question,',
'        pageItems:[''P100_AGENT_NAME'', ''P100_SESSION_ID'']',
'    }, {',
'        dataType:''text'',',
'        success: function(data) {',
'            if(data.trim() !== ''1''){',
'                console.error(data);',
'                printSysErrMsg(data);',
'            }',
'            apex.region("sessionHisStatic").refresh();',
'        },',
'        error: function(jqXHR, textStatus, errorThrown) {',
'            console.error("error", textStatus);',
'        }',
'    });',
'}',
'',
'function getKbotResponseDom(index, response_time, likeSelected, dislikeSelected){',
'    return $botDiv = $(',
'        `<div class="chat-bubble bot" data-chat-id="${index}">',
unistr('            <div class="avatar">\D83E\DD16</div>'),
'            <div class="content">',
'                <div class="message"><span class="bot-stream"></span></div>',
'                <div class="meta-row">',
'                    <div class="timestamp"> ${response_time} </div>',
'                    <div class="feedback">',
'                        <span class="thumb thumb-up ${likeSelected} "><span class="fa fa-thumbs-up" aria-hidden="true"></span></span>',
'                        <span class="thumb thumb-down ${dislikeSelected} "><span aria-hidden="true" class="fa fa-thumbs-down"></span></span>',
'                    </div>',
'                </div>',
'            </div>',
'        </div>`',
'    );',
'}',
'',
'//page init',
'async function initChat(session_id, type) {',
'    if(type == ''CHANGE''){',
'        apex.item(P100_SESSION_ID).setValue(session_id);',
'        $("#chat-area").empty();',
'    }',
'    apex.message.clearErrors();',
'    hisSessionSelectListStyle();',
'    initWelcomeMsg();',
'    try {',
'        const response = await axios.get(`${s_url}/api/agent/session/get?session_id=${apex.item(P100_SESSION_ID).getValue()}`, {',
'            headers: {',
'                ''accept'': ''application/json'',',
'                ''Authorization'': `Bearer ${accessToken}`',
'            }',
'            // ,timeout: 3000',
'        });',
'        console.log(''init'',response);',
'        if(response.data.code === 200){',
'            gDataIndex = response.data.data.qa_data.length;',
'            response.data.data.qa_data.forEach((rec, index) => {',
'                initUserQuestionRender(rec.question, rec.request_time)',
'                let likeSelected = rec.feedback == ''1'' ? ''selected'' : '''';',
'                let dislikeSelected = rec.feedback == ''-1'' ? ''selected'' : '''';',
'                initKbotAnswerRender(index, rec.answer, rec.response_time, likeSelected, dislikeSelected, rec.references);',
'            });',
'            scrollChatToBottom();',
'        }else{',
'            //Session get failed.',
'            gDataIndex = 0;',
'            printSysErrMsg(response.data.message);',
'        }',
'',
'    } catch (error) {',
'        if (error.response) {',
'            console.error(''Error data:'', error.response.data); ',
'            console.error(''Status:'', error.response.status);',
'            console.error(''Headers:'', error.response.headers);',
'        } else if (error.request) {',
'            console.error(''No response:'', error.request);',
'        } else {',
'            console.error(''Error:'', error.message);',
'        }',
'        printSysErrMsg(error.message);',
'    }',
'}',
'',
'function initWelcomeMsg(){',
'    let $tempMsg = ',
'        `<div class="chat-bubble bot">',
unistr('            <div class="avatar">\D83E\DD16</div>'),
'                <div class="content">',
'                <div class="message">${apex.item(P100_WELCOME_MSG).getValue()}</div>',
'            </div>',
'        </div>`',
'    $chatArea.append($tempMsg);',
'    scrollChatToBottom();',
'}',
'',
'function initUserQuestionRender(question, resTime){',
'    const initUserQuestionDom = `',
'        <div class="chat-bubble user">',
'            <div class="avatar"><span class ="avatar-user"> ${apex.env.APP_USER} </span></div>',
'                <div class="content">',
'                    <div class="message"> ${question} </div><div class="timestamp"> ${resTime} </div>',
'                </div> ',
'        </div>',
'        `; ',
'    $chatArea.append(initUserQuestionDom);',
'}',
'',
'function initKbotAnswerRender(index, answer, resTime, likeSelected, dislikeSelected, ref){',
'    const initKbotAnswerDom = `',
'        <div class="chat-bubble bot" data-chat-id="${index}">',
unistr('            <div class="avatar">\D83E\DD16</div>'),
'                <div class="content">',
'                    <div class="message">${marked.parse(answer)} ${getShowMoreDom(index, ref)} </div>',
'                    <div class="meta-row">',
'                        <div class="timestamp"> ${resTime} </div>',
'                        <div class="feedback">',
'                            <span class="thumb thumb-up ${likeSelected} "><span class="fa fa-thumbs-up" aria-hidden="true"></span></span>',
'                            <span class="thumb thumb-down ${dislikeSelected} "><span aria-hidden="true" class="fa fa-thumbs-down"></span></span>',
'                        </div>',
'                </div>',
'            </div>',
'        </div>`; ',
'    $chatArea.append(initKbotAnswerDom);',
'}',
'',
'// kbot respone success',
'function getShowMoreDom(index, reference){',
'    let showMoreDom = '''';',
'    reference.forEach((item, i) => {',
'        if(i == 0){',
unistr('            showMoreDom = `<div class="showMoreClass"><a class="moreLink" id="a_${index}" onclick="showMore(this, ${index});return false;" href="#">>> ${langCode == ''zh-cn''?''\663E\793A\66F4\591A'':''Show more''}</a><div class="moreDiv" style="display:none;" id="${index')
||'}"><ul>`;',
'        }',
'        showMoreDom = `${showMoreDom} <li class="super"> ${item.content.replace(/\n/g, "<br>")}`;',
'            // answer ref url and page num',
'        if(item.download_link){',
unistr('            showMoreDom = `${showMoreDom} <br/><span class="refFileSpan" >[<a  class="refFileA" href="${item.download_link}" target="_blank"> ${langCode == ''zh-cn''?''\4E0B\8F7D'':''Download''} </a>]  | </span>`;'),
'        }',
'        if(item.preview_link){',
unistr('            showMoreDom = `${showMoreDom} <span class="refFileSpan" >[<a  class="refFileA"  onclick="viewSource(''${item.preview_link}'')" target="_blank"> ${langCode == ''zh-cn''?''\67E5\770B\6E90\6587\4EF6'':''View source''} - ${langCode == ''zh-cn''?''\9875\7801'':''PageNum''}:${item.page')
||'_num} ]</span></a></span>`;',
'        }',
'        showMoreDom = `${showMoreDom}</li>`;',
'        if(reference.length - 1 == i){',
'            showMoreDom = `${showMoreDom}</ul></div></div>`;',
'        }',
'    });',
'    return showMoreDom;',
'}',
'',
'function viewSource(url){',
'    apex.server.process("GET_VIEW_SOURCE_URL", {',
'        x01: url',
'    }, {',
'         dataType: "text",',
'        success: function(pData) {',
'           apex.navigation.redirect(pData);',
'        }',
'    });',
'}',
'',
'function printSysErrMsg(msg = null) {',
'    const defaultMsg = langCode === ''zh-cn''',
unistr('        ? ''<div><strong>\7CFB\7EDF\9519\8BEF\FF1A</strong> \51FA\73B0\9519\8BEF\FF0C\8BF7\7A0D\540E\91CD\8BD5.</div>'''),
unistr('        : ''<div><strong>System error\FF1A</strong> An error occurred, please try again later.</div>'';'),
'',
'    const errorMsg = langCode === ''zh-cn''',
unistr('        ? `<div><strong>\7CFB\7EDF\9519\8BEF\FF1A</strong> ${msg || defaultMsg}</div>`'),
unistr('        : `<div><strong>System error\FF1A</strong> ${msg || defaultMsg}</div>`;'),
'    ',
'    const errorMsgDom = $(`<div class="chat-bubble bot">',
unistr('            <div class="avatar">\D83E\DD16</div>'),
'            <div class="content">',
'                <div class="message">${errorMsg}</div>',
'                <div class="timestamp"> ${getLocalTime()} </div>',
'            </div>',
'        </div>`);',
'',
'    $chatArea.append(errorMsgDom);',
'    $loadingBubble.remove(); ',
'    scrollChatToBottom();',
'    isSending = false;',
'}',
'',
'function hisSessionSelectListStyle(){',
'    var currentSessionId = apex.item("P100_SESSION_ID").getValue();',
'    ',
'    // If there''s a session ID',
'    if (currentSessionId) {',
'        var sessionItems = document.querySelectorAll(''.t-SearchResults-item[data-session-id]'');',
'        ',
'        // Loop through each item',
'        sessionItems.forEach(function(item) {',
'            var itemSessionId = item.getAttribute(''data-session-id'');',
'            if (itemSessionId === currentSessionId) {',
'                item.classList.add(''selected-session'');',
'            } else {',
'                item.classList.remove(''selected-session'');',
'            }',
'        });',
'    }',
'}',
'',
'',
'//Get local time',
'function getLocalTime() {',
'    const now = new Date();',
unistr('    //get local time\FF08yyyy-mm-dd hh24:mi:ss\FF09'),
'    const year = now.getFullYear();',
'    const month = String(now.getMonth() + 1).padStart(2, ''0'');',
'    const day = String(now.getDate()).padStart(2, ''0'');',
'    const hours = String(now.getHours()).padStart(2, ''0'');',
'    const minutes = String(now.getMinutes()).padStart(2, ''0'');',
'    const seconds = String(now.getSeconds()).padStart(2, ''0'');',
'    //return',
'    return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;',
'}',
'',
'',
'',
'function showMore(o, id) {',
'    let divID = "div#" + id;',
'    if ($(divID).is(":hidden")) {',
'        $(divID).show(100);',
'        if(langCode == ''zh-cn''){',
unistr('            $(o).html(''>> \9690\85CF'');'),
'        }else{',
'            $(o).html(''>> Show Less'');',
'        }',
'    } else {',
'        $(divID).hide(100);',
'        if(langCode == ''zh-cn''){',
unistr('            $(o).html(''>> \663E\793A\66F4\591A'');'),
'        }else{',
'            $(o).html(''>> Show More'');',
'        }',
'    }',
'}',
'',
'',
'// Scroll to the bottom of the page',
'function scrollChatToBottom() {',
'    $chatArea.scrollTop($chatArea[0].scrollHeight);',
'}'))
