wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(12392805160325776)
,p_computation_sequence=>10
,p_computation_item=>'P100_SECURITY_LEVEL'
,p_computation_point=>'AFTER_HEADER'
,p_computation_type=>'FUNCTION_BODY'
,p_computation_language=>'PLSQL'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_sl        NUMBER;',
'    l_auth      VARCHAR2(4000);',
'    l_super     VARCHAR2(4000);',
'    l_max_value NUMBER;',
'BEGIN',
'',
'    SELECT JSON_VALUE(ar.KBOT_SUB, ''$."KBOT".securityLevel'')',
'         ,ar.KBOT',
'         ,ar.SUPER',
'    INTO l_sl',
'        ,l_auth',
'        ,l_super',
'    FROM AI_PLATFORM_USERS au',
'    JOIN AI_PLATFORM_PRIVILEGES_MU ar ',
'    ON   au.id = ar.USER_ID',
'    WHERE UPPER(au.USER_NAME) = :APP_USER;',
'',
'    SELECT max(return_value)',
'    INTO   l_max_value',
'    FROM kbot_md_data_dic ',
'    WHERE name = ''SECURITY_LEVEL_TYPE''',
'    AND   status = ''1''',
'    AND   app_id = :APP_ID',
'    ORDER BY return_value;',
'',
'    IF l_super = ''Y'' OR l_auth IN (''KB_ADMIN'',''KB_MANAGEMENT'')  THEN',
'        RETURN l_max_value;',
'    ELSE',
'        RETURN l_sl;',
'    END IF;',
'END;'))
);
