wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9920492311450795)
,p_process_sequence=>10
,p_process_point=>'AFTER_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET-SESSION-ID'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_session_id VARCHAR2(400);',
'BEGIN',
'    IF :REQUEST  = ''newChat'' THEN',
'        :P100_SESSION_ID := SYS_GUID();',
'    ELSE',
'        BEGIN',
'            SELECT session_id INTO l_session_id',
'            FROM KBOT_MD_CHAT_SESSION',
'            WHERE APP_ID = :APP_ID',
'            AND   UPPER(UPDATED_BY) = UPPER(:APP_USER)',
'            AND   AGENT_ID = :P100_AGENT_NAME',
'            ORDER BY UPDATED_TIME DESC',
'            FETCH FIRST 1 ROW ONLY;',
'',
'            :P100_SESSION_ID := l_session_id;',
'        EXCEPTION ',
'            WHEN OTHERS THEN',
'                :P100_SESSION_ID := SYS_GUID();',
'        END;',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>14432558915026945
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(10343564145347487)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Clean History'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_clob 	        CLOB;',
'    l_server        VARCHAR2(4000);',
'BEGIN',
'    --  clear',
'    SELECT S_URL INTO l_server FROM KMCHAT_KB_SERVER WHERE S_NAME = ''SERVER'' AND APP_ID = V(''APP_ID''); ',
'',
'    apex_web_service.g_request_headers.delete();',
'    apex_web_service.g_request_headers(1).name  := ''accept'';',
'    apex_web_service.g_request_headers(1).value := ''application/json'';',
'    apex_web_service.g_request_headers(2).name  := ''Content-Type'';',
'    apex_web_service.g_request_headers(2).value := ''application/json''; ',
'    l_clob := apex_web_service.make_rest_request(',
'            p_url => l_server||''/chat/clear_disable_memory_rag_history'',',
'            p_http_method => ''POST'',',
'            p_body => ''{',
'               "user": "''||:APP_USER||''",',
'               "kb_name" : "''||:P100_KNOWLEDGE_BASE_NAME||''",',
'               "llm_model":"''||:P100_MODEL||''"',
'               }',
'               ''',
'        );',
'',
'    delete from kmchat_kb_riva where id in (',
'    select r.id',
'    from KMCHAT_kb_RIVA r connect by prior r.id=r.parent_id',
'    start with upper(r.appuser) = :APP_USER and r.app_id = V(''APP_ID'') and r.chat_type = ''Chat RAG'' and r.kb_name = :P100_KNOWLEDGE_BASE_NAME',
'    );',
'    commit;',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(10334177689347476)
,p_process_when_type=>'NEVER'
,p_internal_uid=>14855630748923637
);
