,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH all_roles AS (',
'  SELECT INITCAP(''ADMIN'') AS auth_role UNION ALL',
'  SELECT INITCAP(''DOMAIN ADMIN'') UNION ALL',
'  SELECT INITCAP(''TIER OPERATOR'')',
'),',
'user_counts AS (',
'  SELECT auth_role, COUNT(1) AS user_count',
'  FROM kbot_ui_user',
'  WHERE app_id = :app_id',
'  GROUP BY auth_role',
')',
'SELECT ',
'  ar.auth_role, ',
'  COALESCE(uc.user_count, 0) AS user_count',
'FROM all_roles ar',
'LEFT JOIN user_counts uc ON upper(ar.auth_role) = uc.auth_role'))
,p_ajax_enabled=>'Y'
