wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(96422695483722948)
,p_process_sequence=>30
,p_parent_process_id=>wwv_flow_imp.id(96422838636722949)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'USER EDIT'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    IF V(''REQUEST'') = ''CREATE'' THEN',
'        IF :P10012_USER_PWD IS NULL THEN',
'            apex_error.add_error (',
'                p_message =>''Password cannot be null.'',',
'                p_display_location => apex_error.c_inline_with_field_and_notif,',
'                p_page_item_name   => ''P10012_USER_PWD'');',
'        ELSE',
'            INSERT INTO kbot_ui_user',
'            (  user_name,',
'               user_pwd,',
'               auth_role,',
'               created_by,',
'               created_time,',
'               updated_by,',
'               updated_time,',
'               domain_id,',
'               app_id',
'            )VALUES(',
'               :P10012_USER_NAME,',
'               kbot_ui_utl.encode(:P10012_USER_PWD),',
'               :P10012_AUTH_ROLE,',
'               V(''APP_USER''),',
'               current_date,',
'               V(''APP_USER''),',
'               current_date,',
'               :P10012_DOMAIN_ID,',
'               V(''APP_ID'')',
'            );',
'        END IF;',
'',
'    ELSIF V(''REQUEST'') = ''SAVE'' THEN',
'        IF :P10012_PWD_CHANGE = ''Y'' THEN',
'            IF :P10012_USER_NEW_PWD IS NULL THEN',
'                apex_error.add_error (',
'                    p_message =>''Password cannot be null.'',',
'                    p_display_location => apex_error.c_inline_with_field_and_notif,',
'                    p_page_item_name   => ''P10012_USER_NEW_PWD''',
'                    );',
'            ELSE',
'                UPDATE kbot_ui_user',
'                SET user_name  = :P10012_USER_NAME,',
'                    user_pwd   = kbot_ui_utl.encode(:P10012_USER_NEW_PWD),',
'                    auth_role  = :P10012_AUTH_ROLE,',
'                    updated_time = current_date,',
'                    updated_by  = V(''APP_USER''),',
'                    domain_id = :P10012_DOMAIN_ID',
'                WHERE ID = :P10012_ID;',
'            END IF;',
'        ELSE',
'            UPDATE kbot_ui_user',
'            SET user_name  = :P10012_USER_NAME,',
'                auth_role  = :P10012_Auth_Role,',
'                updated_time = current_date,',
'                updated_by  = V(''APP_USER''),',
'                domain_id = :P10012_DOMAIN_ID',
'            WHERE ID = :P10012_ID;',
'        END IF;',
'    ELSE',
'        DELETE kbot_ui_user',
'        WHERE ID = :P10012_ID;',
'    END IF;',
'--',
'    COMMIT;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>26195840184325429
);
